window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s16-78","number":78,"surah":16,"verses":[48],"references":[{"surah":16,"verses":[48]}],"verseLabel":"النحل: 48","question":"ما دلالة قوله تعالى في الظلال: ﴿يتفيأ﴾ بصيغة المضارع؟","answer":"تصور الصيغة تجدد رجوع الظلال وامتدادها وانقباضها على مدار الزمن وفق تقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص525، تحت «دلالة الصيغة فيء والتعبير عنها بالمضارع»","url":""}]},{"id":"s16-215","number":215,"surah":16,"verses":[48],"references":[{"surah":16,"verses":[48]}],"verseLabel":"النحل: 48","question":"ما بلاغة وصف الظلال بأنها ﴿سجدًا لله﴾؟","answer":"استعير السجود لانقياد الظلال التام لنظام الله، وفيه تعريض بمن يأبى الخضوع مع ظهور دلائله حوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص530، تحت «بلاغة استعارة لفظ السجود لمعنى الانقياد والخضوع»","url":""}]},{"id":"s16-79","number":79,"surah":16,"verses":[48],"references":[{"surah":16,"verses":[48]}],"verseLabel":"النحل: 48","question":"ما سرّ إفراد ﴿الْيَمِينِ﴾ وجمع ﴿الشَّمَائِلِ﴾؟","answer":"من توجيهه أن المفرد يراد به جنس الجهة، والجمع يراعي تعدد أصحاب الظلال؛ وقيل: روعي لفظ «ما» المفرد في اليمين ومعناها المتعدد في الشمائل. فالإفراد والجمع لا يحصران الظلال في شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص527، 528، تحت «سر التفنن بإفراد اليمين وجمع الشمائل»","url":""}]},{"id":"s16-80","number":80,"surah":16,"verses":[49],"references":[{"surah":16,"verses":[49]}],"verseLabel":"النحل: 49","question":"ما دلالة تخصيص الدواب والملائكة بالذكر في سياق السجود؟","answer":"الدواب من ذوات الحس والحركة في الأرض، والملائكة أشرف المخلوقات السماوية؛ فذكرهما يبين خضوع الصنفين لله. وتخصيص الملائكة بعد العموم تشريف لهم وتوكيد لعبوديتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص542، تحت «دلالة تخصيص الدواب والملائكة بالذكر»","url":""}]},{"id":"s16-81","number":81,"surah":16,"verses":[50],"references":[{"surah":16,"verses":[50]}],"verseLabel":"النحل: 50","question":"ما فائدة التعبير بشبه الجملة من فوقهم في قوله تعالى: ﴿يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ﴾؟","answer":"من توجيه العبارة أنها تثني على الله بعلو القهر وعظمة السلطان؛ فهم يخافون ربهم العالي القاهر لهم، فيجتمع الخوف والتعظيم مع تمام الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص549، تحت «فائدة التعبير بشبه الجملة من فوقهم»","url":""}]},{"id":"s16-82","number":82,"surah":16,"verses":[50],"references":[{"surah":16,"verses":[50]}],"verseLabel":"النحل: 50","question":"ما دلالة ختام الآية بـ﴿وَيَفْعَلُونَ مَا يُؤْمَرُونَ﴾؟","answer":"بعد نفي الاستكبار أثبت كمال الامتثال العملي؛ خوفهم يثمر طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص550، تحت «بلاغة الإيجاز في التذييل»","url":""}]},{"id":"s16-83","number":83,"surah":16,"verses":[51],"references":[{"surah":16,"verses":[51]}],"verseLabel":"النحل: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَتَّخِذُوا إِلَهَيْنِ اثْنَيْنِ﴾ مع أن التثنية مفهومة؟","answer":"جاء «اثنين» لبيان أن النهي منصب على التعدد نفسه؛ فليست الألوهية ممنوعة وإنما الشرك فيها. ويقابله ﴿إِنَّمَا هُوَ إِلَهٌ وَاحِدٌ﴾، فيتحدد موضع النفي والإثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص558، تحت «الفائدة من التأكيد بالوصف اثنين»","url":""}]},{"id":"s16-84","number":84,"surah":16,"verses":[52],"references":[{"surah":16,"verses":[52]}],"verseLabel":"النحل: 52","question":"ما فائدة تقديم ﴿له﴾ في قوله تعالى: ﴿وله الدين واصبًا﴾؟","answer":"يفيد قصر الطاعة والعبادة على الله وحده؛ فلا يستحق الدين الدائم سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص574، تحت «فائدة القصر بتقديم شبه الجملة في وله الدين»","url":""}]},{"id":"s16-216","number":216,"surah":16,"verses":[52],"references":[{"surah":16,"verses":[52]}],"verseLabel":"النحل: 52","question":"ما دلالة وصف الدين بقوله: ﴿واصبًا﴾؟","answer":"الكلمة كناية عن الدوام والثبات؛ فطاعة الله لا تنقطع وسلطانه لا يزول كما تزول طاعة غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص575، تحت «بلاغة الكناية في كلمة واصبا»","url":""}]},{"id":"s16-85","number":85,"surah":16,"verses":[53],"references":[{"surah":16,"verses":[53]}],"verseLabel":"النحل: 53","question":"ما دلالة تنكير ﴿نعمة﴾ في قوله: ﴿وما بكم من نعمة﴾؟","answer":"وقعت النكرة في سياق العموم لتشمل كل نعمة ظاهرة وباطنة، صغيرة وكبيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص584، تحت «دلالة تنكير نعمة»","url":""}]},{"id":"s16-217","number":217,"surah":16,"verses":[53],"references":[{"surah":16,"verses":[53]}],"verseLabel":"النحل: 53","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿فمن الله﴾؟","answer":"تفيد ابتداء صدور النعم كلها من الله، فترد كل نعمة إلى المنعم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص585، تحت «نوع من ودلالتها»","url":""}]},{"id":"s16-86","number":86,"surah":16,"verses":[53],"references":[{"surah":16,"verses":[53]}],"verseLabel":"النحل: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿تَجْأَرُونَ﴾ لا تدعون؟","answer":"الجؤار رفع الصوت بالتضرع والاستغاثة؛ فيصور شدة افتقارهم عند الضر، وتقديم «إليه» يبين أنهم حينئذ يخصون الله باللجوء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص580، تحت «شرح المفردات تجأرون»","url":""}]},{"id":"s16-87","number":87,"surah":16,"verses":[54],"references":[{"surah":16,"verses":[54]}],"verseLabel":"النحل: 54","question":"ما دلالة ﴿إذا﴾ في قوله: ﴿إذا فريق منكم بربهم يشركون﴾؟","answer":"تفيد المفاجأة، فتكشف سرعة انقلاب فريق منهم إلى الشرك بعد أن يكشف الله عنهم الضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص592، تحت «دلالة إذا الفجائية وفائدتها»","url":""}]},{"id":"s16-218","number":218,"surah":16,"verses":[54],"references":[{"surah":16,"verses":[54]}],"verseLabel":"النحل: 54","question":"ما بلاغة تقديم ﴿بربهم﴾ في قوله: ﴿بربهم يشركون﴾؟","answer":"يفظع المقابلة؛ فهم يشركون بالرب الذي رباهم بالنعم وكشف عنهم الضر، فقدم المتعلق لإبراز قبح فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص593، تحت «بلاغة تقديم بربهم على يشركون»","url":""}]},{"id":"s16-88","number":88,"surah":16,"verses":[56],"references":[{"surah":16,"verses":[56]}],"verseLabel":"النحل: 56","question":"ما سرّ التعبير بـ﴿ما﴾ في قوله: ﴿ويجعلون لما لا يعلمون نصيبًا﴾؟","answer":"تشير ﴿ما﴾ إلى أصنام لا تعقل ولا تستحق شيئًا، ومع ذلك يجعلون لها نصيبًا من رزق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص611، تحت «سر التعبير بما»","url":""}]},{"id":"s16-219","number":219,"surah":16,"verses":[56],"references":[{"surah":16,"verses":[56]}],"verseLabel":"النحل: 56","question":"ما دلالة حذف مفعول ﴿يعلمون﴾ في الآية؟","answer":"يعمم جهلهم؛ فلا يعلمون حقيقة معبوداتهم ولا دليلًا على استحقاقها العبادة أو النصيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص612، تحت «دلالة حذف مفعول يعلمون»","url":""}]},{"id":"s16-89","number":89,"surah":16,"verses":[57],"references":[{"surah":16,"verses":[57]}],"verseLabel":"النحل: 57","question":"ما سرّ التعبير في قوله تعالى عن نسبة البنات: ﴿سُبْحَانَهُ﴾؟","answer":"قطع الحكاية بتنزيه فوري قبل ذكر ما يشتهون لأنفسهم، فظهرت بشاعة القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص624، تحت «بلاغة الاعتراض بقوله سبحانه»","url":""}]},{"id":"s16-90","number":90,"surah":16,"verses":[58],"references":[{"surah":16,"verses":[58]}],"verseLabel":"النحل: 58","question":"ما سرّ التعبير بالفعل ﴿ظل﴾ في قوله: ﴿ظل وجهه مسودًا﴾؟","answer":"يصور استمرار حال الكآبة والغم ملازمة له عند بشارته بالأنثى، لا مجرد تغير عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص634، تحت «سر اختيار التعبير بالفعل ظل»","url":""}]},{"id":"s16-220","number":220,"surah":16,"verses":[58],"references":[{"surah":16,"verses":[58]}],"verseLabel":"النحل: 58","question":"ما بلاغة وصف الوجه بأنه ﴿مسودًا﴾؟","answer":"هو كناية عن شدة الغم والحزن، حتى ظهر أثر ما في النفس على الوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص635، تحت «بلاغة الكناية في قوله مسودا»","url":""}]},{"id":"s16-91","number":91,"surah":16,"verses":[59],"references":[{"surah":16,"verses":[59]}],"verseLabel":"النحل: 59","question":"ما سرّ التعبير بالمواراة دون الاختفاء في قوله تعالى: ﴿يَتَوَارَى مِنَ الْقَوْمِ﴾؟","answer":"التواري تكلف الاختفاء، يصور العار الاجتماعي الذي صنعوه ثم أساؤوا الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص644، تحت «سر التعبير بالمواراة دون الاختفاء»","url":""}]},{"id":"s16-92","number":92,"surah":16,"verses":[60],"references":[{"surah":16,"verses":[60]}],"verseLabel":"النحل: 60","question":"ما سرّ التعبير بالمثل في قوله تعالى: ﴿لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ﴾؟","answer":"«مثل السوء» وصف النقص والقبح الذي استحقوه بأفعالهم؛ وقوبل به المثل الأعلى المختص بالله، أي كمال صفاته وتنزهه عما نسبوه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص662، تحت «سر التعبير بالمثل»","url":""}]},{"id":"s16-93","number":93,"surah":16,"verses":[61],"references":[{"surah":16,"verses":[61]}],"verseLabel":"النحل: 61","question":"ما دلالة تقييد الإمهال بـ﴿إِلَى أَجَلٍ مُسَمًّى﴾؟","answer":"الإمهال تأخير إلى غاية محددة، وليس تركًا للمحاسبة. و«مسمى» يدل على أجل عيّنه الله وحدده، وإن خفي وقته على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص679، تحت «دلالة وصف الأجل بقوله مسمى»","url":""}]},{"id":"s16-94","number":94,"surah":16,"verses":[62],"references":[{"surah":16,"verses":[62]}],"verseLabel":"النحل: 62","question":"ما دلالة الموصول في ما يكرهون في قوله تعالى: ﴿وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ﴾؟","answer":"الموصول يعم ما يكرهونه لأنفسهم من أحوال وخصال، كالبنات والشركاء والاستخفاف؛ فذكره بهذا الوصف يكشف تناقضهم في نسبة تلك الأمور إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص687، تحت «دلالة الموصول في ما يكرهون»","url":""}]},{"id":"s16-95","number":95,"surah":16,"verses":[63],"references":[{"surah":16,"verses":[63]}],"verseLabel":"النحل: 63","question":"ما موقع جملة القسم تالله لقد مما قبلها في قوله تعالى: ﴿تَاللَّهِ لَقَدْ أَرْسَلْنَا﴾؟","answer":"يثبت القسم إرسال الرسل إلى الأمم السابقة، وفيه تسلية للنبي: ما يلقاه من التكذيب قد لقيه الرسل قبله؛ فليس وحيدًا في مواجهة إعراض قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص697، تحت «موقع جملة القسم تالله لقد مما قبلها»","url":""}]},{"id":"s16-96","number":96,"surah":16,"verses":[63],"references":[{"surah":16,"verses":[63]}],"verseLabel":"النحل: 63","question":"ما وجه البلاغة في إظهار الفاعل في قوله تعالى: ﴿فَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ﴾؟","answer":"التزيين تحسين الباطل في نظر أصحابه حتى يتعلقوا به؛ وذكر الشيطان ظاهرًا ينبه إلى مصدر هذا التضليل، في مقابلة الرسل الذين يكشفون قبح الأعمال ويدعون إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص701، تحت «بلاغة إظهار الفاعل»","url":""}]},{"id":"s16-97","number":97,"surah":16,"verses":[64],"references":[{"surah":16,"verses":[64]}],"verseLabel":"النحل: 64","question":"ما وجه البلاغة في أسلوب القصر في قوله تعالى: ﴿إِلَّا لِتُبَيِّنَ لَهُمُ الَّذِي اخْتَلَفُوا فِيهِ﴾؟","answer":"القصر يبرز الغاية العظمى من التنزيل: بيان الحق فيما اختلفوا فيه، لا استيعاب كل فوائده في هذه العبارة وحدها. ومن هذا البيان تكون الهداية والرحمة للمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص712، تحت «بلاغة أسلوب القصر»","url":""}]},{"id":"s16-98","number":98,"surah":16,"verses":[65],"references":[{"surah":16,"verses":[65]}],"verseLabel":"النحل: 65","question":"ما سرّ ختام آية إحياء الأرض بـ﴿لِقَوْمٍ يَسْمَعُونَ﴾؟","answer":"المراد سماع تدبر وقبول؛ فالعبرة بإحياء الأرض لا ينتفع بها من يسمع الألفاظ ثم يعرض عن دلالتها. وذكر السماع يعرض بالغافلين الذين لم يستجيبوا للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص728، تحت «بلاغة الكناية في لقوم يسمعون»","url":""}]},{"id":"s16-99","number":99,"surah":16,"verses":[66],"references":[{"surah":16,"verses":[66]}],"verseLabel":"النحل: 66","question":"ما دلالة الجمع بين الفرث والدم واللبن؟","answer":"موضع العبرة خروج اللبن خالصًا سائغًا، مع أن منشأه في باطن الأنعام بين الفرث والدم؛ فلا يحمل لون الدم ولا رائحة الفرث. فالمقابلة تبرز صفاء النعمة وعجيب القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص741، تحت «غرض الترتيب في من بين فرث ودم»","url":""}]},{"id":"s16-100","number":100,"surah":16,"verses":[67],"references":[{"surah":16,"verses":[67]}],"verseLabel":"النحل: 67","question":"ما سرّ تقييد «ورزقًا حسنًا» دون السكر؟","answer":"خُصّ الرزق بوصف الحسن دون السَّكَر؛ وفي المقابلة تنبيه إلى اختلاف ما يصنعه الناس من الثمرات. وعلى تفسير السَّكَر بالمسكر، تتضمن العبارة تعريضًا بعدم حسنه، ولو كان نزولها قبل تحريمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص750، تحت «سر تقييد «ورزقًا حسنًا» دون السكر»","url":""}]},{"id":"s16-101","number":101,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما نكتة الانتقال إلى قوله: ﴿وأوحى ربك إلى النحل﴾ في سياق النعم؟","answer":"انتقل السياق من تعداد النعم العامة إلى مشهد تفصيلي عجيب في خلق النحل وهدايته، ليستدل القارئ من دقة الصنعة على المنعم وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص757، تحت «نكتة تغيير أسلوب التذكير بالنعم»","url":""}]},{"id":"s16-221","number":221,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما دلالة الفعل ﴿أوحى﴾ في هداية النحل؟","answer":"يدل على إلهام خفي سريع أودعه الله في فطرة النحل، فصدر نظامه الدقيق من تسخير وهداية لا من تعليم بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص758، تحت «دلالة الفعل أوحى مادة وصيغة»","url":""}]},{"id":"s16-222","number":222,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما دلالة قوله ﴿ربك﴾ في آية النحل؟","answer":"إضافة الرب إلى النبي تستحضر عناية المربي ومدبر الخلق، وتصل نعمة هداية النحل برسالة التذكير التي يخاطب بها النبي قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص758، تحت «دلالة الإضافة في قوله ربك»","url":""}]},{"id":"s16-102","number":102,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما سرّ خطاب النحل بصيغة المؤنث في قوله تعالى: ﴿اتَّخِذِي﴾؟","answer":"أُنّث ضمير الخطاب في «اتخذي» لأن النحل جمع نحلة، فناسبه التأنيث. فالتوجيه المذكور هنا لغوي متعلق باسم الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص759، تحت «بلاغة التأنيث في ضمير الخطاب»","url":""}]},{"id":"s16-103","number":103,"surah":16,"verses":[68],"references":[{"surah":16,"verses":[68]}],"verseLabel":"النحل: 68","question":"ما النكتة البلاغية في الترتيب في أماكن الاتخاذ الثلاثة في قوله تعالى: ﴿اتَّخِذِي مِنَ الْجِبَالِ بُيُوتًا وَمِنَ الشَّجَرِ وَمِمَّا يَعْرِشُونَ﴾؟","answer":"قدّمت الجبال لأن أكثر بيوت النحل تكون فيها، ثم الشجر، ثم ما يبنيه الناس؛ ففي الترتيب مراعاة لكثرة هذه المساكن. ويذكر المصدر أيضًا وجهًا يتعلق بتفاوت مراتب العسل بحسب مواضع بيوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص761، 762، تحت «نكتة الترتيب في أماكن الاتخاذ الثلاثة»","url":""}]},{"id":"s16-104","number":104,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلِي مِنْ كُلِّ الثَّمَرَاتِ﴾ مع أنها لا تأكل الثمار كلها؟","answer":"«مِن» للتبعيض؛ فالمعنى أن تأخذ مما تشتهي من الثمرات، لا أن يلزمها استيعاب كل ثمرة. وأُطلقت الثمرات على الأزهار باعتبار ما تؤول إليه؛ إذ تصير الأزهار ثمرات.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص762، 763، تحت «دلالة حرف الجر «مِنْ» في «مِنْ كُلِّ الثَّمَرَاتِ»؛ بلاغة إطلاق الثمرات على الزهور»","url":""}]},{"id":"s16-105","number":105,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما النكتة البلاغية في التعبير بـ«السبل» جمعًا، وما سرّ إضافة السبل إلى «ربك»، وما سرّ تقييد الفعل بالحال «ذللًا»؟","answer":"جمع السبل يشعر بكثرتها وتنوعها، وإضافتها إلى الرب تذكّر بأنه خالقها والمهيّئ لسلوكها. و«ذللًا» في التوجيه المذكور حال من النحل: تسلك منقادة مذللة، وذلك من آثار تسخير الله لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص763، 764، تحت «نكتة التعبير بـ«السبل» جمعًا؛ سر إضافة السبل إلى «ربك»؛ سر تقييد الفعل بالحال «ذللًا»»","url":""}]},{"id":"s16-106","number":106,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخْرُجُ مِنْ بُطُونِهَا شَرَابٌ﴾، دون أن يقال عسل؟","answer":"اختير اسم الجنس «شراب» لإبراز جهة الانتفاع بالعسل، وهو ما يتصل بقوله بعده: ﴿فِيهِ شِفَاءٌ لِلنَّاسِ﴾. وسُمّي شرابًا لأنه مائع يُشرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص766، تحت «سرّ التعبير عن العسل بالشراب»","url":""}]},{"id":"s16-107","number":107,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما دلالة موقع قوله «مختلف ألوانه»؟","answer":"الجملة صفة للشراب، وتلفت إلى تنوع ألوان العسل مع خروجه من هذا المخلوق الضعيف؛ فيكون اختلافه نفسه موضع اعتبار بقدرة الله وإنعامه، فضلًا عن نفعه غذاءً وشفاءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص767، تحت «دلالة موقع قوله «مختلف ألوانه»»","url":""}]},{"id":"s16-108","number":108,"surah":16,"verses":[69],"references":[{"surah":16,"verses":[69]}],"verseLabel":"النحل: 69","question":"ما سرّ ختم آية النحل بقوله تعالى: ﴿لِقَوْمٍ يَتَفَكَّرُونَ﴾؟","answer":"لأن الاعتبار بنظام النحل وما يخرج منه يحتاج إلى إعمال فكر دقيق في أحواله العجيبة. والمضارع يناسب تجدد التفكر كلما تجددت مشاهدة هذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص771، 772، تحت «دلالة المضارع «يتفكرون» مادة وصيغة»","url":""}]},{"id":"s16-109","number":109,"surah":16,"verses":[70],"references":[{"surah":16,"verses":[70]}],"verseLabel":"النحل: 70","question":"ما غرض تقديم اسم الله في قوله: ﴿والله خلقكم ثم يتوفاكم﴾؟","answer":"يقرر اختصاص الله بالخلق والتوفي، ويرد النعمتين وتدبير العمر كله إلى فاعل واحد لا شريك له.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص776، تحت «غرض تقديم المسند إليه»","url":""}]},{"id":"s16-223","number":223,"surah":16,"verses":[70],"references":[{"surah":16,"verses":[70]}],"verseLabel":"النحل: 70","question":"ما دلالة ﴿ثم﴾ في قوله: ﴿ثم يتوفاكم﴾؟","answer":"تفيد تراخي الوفاة عن الخلق وامتداد أطوار الحياة بينهما، فتوجز الرحلة الإنسانية من البدء إلى الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص777، تحت «دلالة «ثم» في قوله «ثم يتوفاكم»»","url":""}]},{"id":"s16-110","number":110,"surah":16,"verses":[70],"references":[{"surah":16,"verses":[70]}],"verseLabel":"النحل: 70","question":"ما وجه البلاغة في المجاز العقلي في قوله «أرذل العمر»؟","answer":"أُضيف الوصف إلى العمر، والمقصود حال الإنسان في مرحلة الهرم وضعف القوى؛ فالمدة نفسها لا توصف بالشرف أو الخسة. ونسبة الرذالة إلى العمر مجاز عقلي يبرز ما قد يصيب الإنسان فيه من ضعف بعد قوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص779، تحت «بلاغة المجاز العقلي في قوله «أرذل العمر»»","url":""}]},{"id":"s16-111","number":111,"surah":16,"verses":[71],"references":[{"surah":16,"verses":[71]}],"verseLabel":"النحل: 71","question":"ما وجه البلاغة في التشبيه الضمني التمثيلي في قوله «فما الذين فضلوا»؟","answer":"يضرب السياق مثلًا يبطل التسوية بين الله وغيره: فالذين فُضّلوا في الرزق لا يجعلون مماليكهم شركاء مساويين لهم فيه، فكيف يجعلون لله شركاء من خلقه؟ والمقصود إلزامهم بما لا يرضونه لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص791، 792، تحت «بلاغة التشبيه الضمني التمثيلي في قوله «فما الذين فضلوا»»","url":""}]},{"id":"s16-112","number":112,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]},{"surah":30,"verses":[21]}],"verseLabel":"النحل: 72؛ الروم: 21","question":"ما معنى قوله تعالى: ﴿من أنفسكم أزواجًا﴾؟","answer":"أي من جنسكم الإنساني؛ فالمجانسة أدعى إلى الألفة والتفاهم، وهي من تمام نعمة الله على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص16، تحت «معنى الأنفسية في قوله «من أنفسكم»»","url":""}]},{"id":"s16-224","number":224,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]},{"surah":30,"verses":[21]}],"verseLabel":"النحل: 72؛ الروم: 21","question":"ما الصورة في قوله تعالى: ﴿لتسكنوا إليها﴾؟","answer":"صور طمأنينة الزوج إلى زوجه بسكون المضطرب إلى موضع أمنه، فدل على الراحة النفسية والألفة العميقة في هذه الصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج43، ص136، تحت «بلاغة الاستعارة في «لتسكنوا»»","url":""}]},{"id":"s16-113","number":113,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]}],"verseLabel":"النحل: 72","question":"ما دلالة العطف والترتيب في «بنين وحفدة»؟","answer":"العطف يبرز تنوع النعمة وتكاملها. ومن التوجيهات المذكورة تفسير الحفدة بمن يسرع في المعونة والخدمة؛ فتجتمع نعمة البنوة ونعمة العون. وقُدّم البنون للاهتمام بهم ومباشرة الصلة بهم، ثم ذُكر الحفدة لاتساع النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص20، تحت «دلالة العطف والترتيب في «بنين وحفدة»»","url":""}]},{"id":"s16-114","number":114,"surah":16,"verses":[73],"references":[{"surah":16,"verses":[73]}],"verseLabel":"النحل: 73","question":"ما سرّ تقييد العبد بالوصف بلفظ «مملوك»، وما علة وصف العبد المملوك بأنه «لا يقدر على شيء»؟","answer":"«مملوك» يعيّن المراد بالعبد، لأن العبودية لله تشمل البشر جميعًا. ثم يزيد وصفُه بالعجز الصورةَ وضوحًا؛ فالمثل يقابل العاجز الذي لا يملك التصرف بمن رزقه الله قدرة على الإنفاق، لإبطال التسوية بين الله والمعبودات العاجزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص64، 66، تحت «سر تقييد العبد بالوصف بلفظ «مملوك»؛ علة وصف العبد المملوك بأنه «لا يقدر على شيء»»","url":""}]},{"id":"s16-115","number":115,"surah":16,"verses":[75],"references":[{"surah":16,"verses":[75]}],"verseLabel":"النحل: 75","question":"ما دلالة مقابلة الأبكم بمن يأمر بالعدل في مثل سورة النحل؟","answer":"يجمع المثل صفات العجز وعدم النفع، ويقابلها بمن يأمر بالعدل ويسير على صراط مستقيم. ثم ينكر الاستفهام التسوية بينهما؛ ليظهر بطلان التسوية بين المعبود العاجز والخالق القادر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص91، 92، 99، تحت «سر وصفه بالبكم بلفظ «أبكم»؛ سر وصفه بأنه «لا يقدر على شيء»؛ بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s16-116","number":116,"surah":16,"verses":[77],"references":[{"surah":16,"verses":[77]}],"verseLabel":"النحل: 77","question":"ما سرّ تقديم غيب السماوات والأرض قبل أمر الساعة؟","answer":"ينتقل السياق من عموم الغيب الذي يختص الله بعلمه إلى الساعة، وهي من أعظم ما جادلوا فيه من الغيب. ثم يبيّن سهولة إقامتها على الله، فيجتمع الاستدلال بكمال العلم وشمول القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص118، 119، تحت «دلالة الواو في قوله «وما أمر الساعة»؛ سر تخصيص الساعة بالذكر»","url":""}]},{"id":"s16-117","number":117,"surah":16,"verses":[77],"references":[{"surah":16,"verses":[77]}],"verseLabel":"النحل: 77","question":"ما سرّ التعبير في قوله تعالى في الساعة: ﴿كَلَمْحِ الْبَصَرِ أَوْ هُوَ أَقْرَبُ﴾؟","answer":"يشبّه وقوع الساعة بلمح البصر لتقريب سرعة حصولها وسهولتها على الله. ومن توجيهات «أو هو أقرب» الترقي في تصوير السرعة؛ فلا ينحصر المقصود في مقدار لمح البصر، بل الأمر أهون وأسرع عند تعلق الإرادة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص121، 122، 123، تحت «بلاغة التشبيه في قوله «كلمح البصر»؛ دلالة «أو» في قوله «أو هو أقرب»»","url":""}]},{"id":"s16-118","number":118,"surah":16,"verses":[77],"references":[{"surah":16,"verses":[77]}],"verseLabel":"النحل: 77","question":"ما سرّ تخصيص الساعة بالذكر بعد غيب السماوات والأرض؟","answer":"لأن الساعة كانت موضع إنكار وجدال، فناسب إفرادها بعد ذكر الغيب. وإقامتها وبعث الأجساد بعد موتها من أعظم ما يدل على تمام علم الله وشمول قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص119، تحت «سر تخصيص الساعة بالذكر»","url":""}]},{"id":"s16-119","number":119,"surah":16,"verses":[78],"references":[{"surah":16,"verses":[78]}],"verseLabel":"النحل: 78","question":"ما سرّ تقديم السمع على الأبصار والأفئدة؟","answer":"من وجوه التقديم أن السمع طريق تلقي الوحي، وله منزلة عظيمة في تحصيل العلم وفهم الرسالة. ثم ذُكر البصر، وجُعلت الأفئدة خاتمة هذه الوسائل لأن بها الوعي والحفظ؛ فيناسب الترتيب سياقَ الامتنان بأدوات المعرفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص141، 142، تحت «بلاغة الترتيب بين «السمع والأبصار والأفئدة»»","url":""}]},{"id":"s16-120","number":120,"surah":16,"verses":[79],"references":[{"surah":16,"verses":[79]}],"verseLabel":"النحل: 79","question":"ما سرّ التقييد بالحال في «مسخرات»، وما سرّ إضافة الجو إلى السماء في السياق، وما سرّ التعبير بلفظ «مسخرات» وأثره في المعنى؟","answer":"وصف الطير بالتسخير يوجّه النظر إلى ما هيّأه الله لها من أسباب الطيران. وذكر جو السماء يصوّر ارتفاعها في فضاء بعيد عن الأرض، فيزداد ظهور دلالة القدرة في بقائها محلّقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص154، 155، 156، تحت «سر التقييد بالحال في «مسخرات»؛ سر إضافة الجو إلى السماء في السياق؛ سر التعبير بلفظ «مسخرات» وأثره في المعنى»","url":""}]},{"id":"s16-121","number":121,"surah":16,"verses":[79],"references":[{"surah":16,"verses":[79]}],"verseLabel":"النحل: 79","question":"ما دلالة القصر في قوله: ﴿ما يمسكهن إلا الله﴾؟","answer":"يقصر إمساك الطير في الجو على قدرة الله وتسخيره، فينفي استقلال الأسباب الظاهرة بهذا النظام العجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص157، تحت «بلاغة أسلوب القصر ونوعه في السياق»","url":""}]},{"id":"s16-225","number":225,"surah":16,"verses":[79],"references":[{"surah":16,"verses":[79]}],"verseLabel":"النحل: 79","question":"لماذا عبّر عن بقاء الطير في الجو بالإمساك؟","answer":"صور حفظها من السقوط كأن قدرة الله تمسكها، فأبرز استمرار العناية والتسخير في كل لحظة من طيرانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص158، تحت «نكتة التعبير بالإمساك مادة وصيغة»","url":""}]},{"id":"s16-122","number":122,"surah":16,"verses":[80],"references":[{"surah":16,"verses":[80]}],"verseLabel":"النحل: 80","question":"ما سرّ وصف البيوت بأنها ﴿سَكَنًا﴾؟","answer":"ينقل التعبير النظر من بناء البيت إلى غايته: الراحة والقرار والطمأنينة، وسكون الجوارح عن الحركة والاضطراب؛ فيبرز النعمة التي يجدها الإنسان في مسكنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص176، تحت «دلالة التعبير بـ«سكنًا»»","url":""}]},{"id":"s16-123","number":123,"surah":16,"verses":[81],"references":[{"surah":16,"verses":[81]}],"verseLabel":"النحل: 81","question":"لماذا اكتفى بذكر الحر في ﴿سَرَابِيلَ تَقِيكُمُ الْحَرَّ﴾ ولم يذكر البرد؟","answer":"هذا من الاكتفاء بذكر أحد المتقابلين، لدلالة السياق على أن الملابس تقي الحر والبرد. وخصّ الحر بالذكر لمناسبة حال المخاطبين الذين يغلب عليهم العيش في بلاد حارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص197، 198، تحت «بلاغة الاكتفاء في قوله «تقيكم الحر»»","url":""}]},{"id":"s16-124","number":124,"surah":16,"verses":[81],"references":[{"surah":16,"verses":[81]}],"verseLabel":"النحل: 81","question":"ما فائدة تكرار لفظتي «سرابيل تقيكم»، وما فائدة الإضافة في قوله «بأسكم»؟","answer":"المراد هنا الدروع وما يُلبس لاتقاء أذى الحرب، بعد ذكر الملابس الواقية من الحر. وإضافة البأس إلى المخاطبين تشير إلى بأس بعضهم على بعض؛ فتتعدد جهات النعمة بين الوقاية في المعيشة والوقاية في القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص199، 200، تحت «فائدة تكرار لفظتي «سرابيل تقيكم»؛ فائدة الإضافة في قوله «بأسكم»»","url":""}]},{"id":"s16-125","number":125,"surah":16,"verses":[83],"references":[{"surah":16,"verses":[83]}],"verseLabel":"النحل: 83","question":"لماذا قال: ﴿يعرفون نعمت الله﴾ ولم يقل يعلمونها؟","answer":"المعرفة تدل على ظهور النعمة وتميزها لديهم بعد إدراك آثارها، فلا يبقى إنكارهم ناشئًا عن خفاء أو جهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص215، تحت «سر اختيار فعل المعرفة»","url":""}]},{"id":"s16-226","number":226,"surah":16,"verses":[83],"references":[{"surah":16,"verses":[83]}],"verseLabel":"النحل: 83","question":"ما أثر ﴿ثم﴾ في قوله: ﴿ثم ينكرونها﴾؟","answer":"تفيد الاستبعاد والتراخي الرتبي؛ إذ كان مقتضى معرفتهم النعمة أن يشكروها، فجاء الإنكار بعدها أشد قبحًا وعجبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص216، تحت «أثر حرف العطف «ثم»»","url":""}]},{"id":"s16-126","number":126,"surah":16,"verses":[84],"references":[{"surah":16,"verses":[84]}],"verseLabel":"النحل: 84","question":"ما فائدة تقديم الجار والمجرور «من كل»، وما اللطيفة البلاغية في استعمال لفظ الشهادة في «شهيدًا»؟","answer":"تقديم ﴿مِنْ كُلِّ أُمَّةٍ﴾ يفيد أن لكل أمة شهيدها المختص بها. وهو نبيها الذي يشهد عليها، فتظهر دقة إقامة الحجة على الأمم بما بلغها من رسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص225، 226، تحت «فائدة تقديم الجار والمجرور «من كل»؛ لطيفة استعمال لفظ الشهادة في «شهيدًا»»","url":""}]},{"id":"s16-127","number":127,"surah":16,"verses":[86],"references":[{"surah":16,"verses":[86]}],"verseLabel":"النحل: 86","question":"ما دلالة التناسب بين ﴿أَشْرَكُوا﴾ و﴿شُرَكَاءَهُمْ﴾ في قوله تعالى: ﴿وَإِذَا رَأَى الَّذِينَ أَشْرَكُوا شُرَكَاءَهُمْ﴾؟","answer":"بين «أشركوا» و«شركاءهم» جناس اشتقاق يربط اللفظين ويؤكد نسبة الشرك إليهم. فهذه المعبودات لا تستحق الشركة لله، وإنما صارت شركاء في زعم عابديها؛ وبذلك يكشف التعبير فساد اعتقادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص245، تحت «علة الجناس في قوله «أشركوا شركاءهم»»","url":""}]},{"id":"s16-128","number":128,"surah":16,"verses":[88],"references":[{"surah":16,"verses":[88]}],"verseLabel":"النحل: 88","question":"ما دلالة الإخبار عن زيادة العذاب للكافرين في قوله تعالى: ﴿زِدْنَاهُمْ عَذَابًا فَوْقَ الْعَذَابِ﴾؟","answer":"الزيادة تناسب اجتماع الكفر والصد عن سبيل الله: لم يقتصروا على ضلال أنفسهم، بل سعوا في إضلال غيرهم. فكانت زيادة العذاب مقابلة لزيادة جرمهم وإفسادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص265، تحت «دلالة الإخبار عن زيادة العذاب للكافرين»","url":""}]},{"id":"s16-129","number":129,"surah":16,"verses":[88],"references":[{"surah":16,"verses":[88]}],"verseLabel":"النحل: 88","question":"ما سرّ ختم الآية بقوله ﴿بِمَا كَانُوا يُفْسِدُونَ﴾ دون «يكفرون»؟","answer":"لأن سبب زيادة العذاب هنا إفسادهم بإضلال الناس والصد عن سبيل الله، لا مجرد كفرهم. فلفظ الفساد يبيّن الجرم المتعدي الذي استحقوا بسببه هذه الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص267، تحت «إيثار التعبير بلفظ الفساد دون الكفر في فاصلة الآية»","url":""}]},{"id":"s16-130","number":130,"surah":16,"verses":[89],"references":[{"surah":16,"verses":[89]}],"verseLabel":"النحل: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ﴾ بصيغة نزّل؟","answer":"التضعيف في «نزّلنا» يناسب التدرج والتنجيم؛ فقد نزل القرآن مفرّقًا بحسب الحوادث وما تقتضيه الحكمة. فالصيغة تلائم كيفية نزوله شيئًا بعد شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص275، 276، تحت «سر استعمال صيغة «نزّل» دون «أنزل»»","url":""}]},{"id":"s16-131","number":131,"surah":16,"verses":[89],"references":[{"surah":16,"verses":[89]}],"verseLabel":"النحل: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿تِبْيَانًا﴾ لا بيانًا؟","answer":"يفيد «تبيانًا» في هذا السياق المبالغة في البيان؛ فالكتاب منزل لإيضاح ما يحتاج إليه الناس في هدايتهم وأمر دينهم. وجاء المصدر مؤكدًا لوظيفته في البيان والكشف.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص277، تحت «إيثار لفظ «تبيانًا» دون «بيانًا»»","url":""}]},{"id":"s16-132","number":132,"surah":16,"verses":[89],"references":[{"surah":16,"verses":[89]}],"verseLabel":"النحل: 89","question":"ما سرّ ترتيب أوصاف الكتاب: تبيانًا وهدى ورحمة وبشرى؟","answer":"يتدرج الترتيب من التبيان الذي تقوم به الهداية، إلى الهدى الذي تتحقق به الرحمة، ثم البشرى التي يتقدم بها الإخبار بما يسرّ المؤمنين. فالأوصاف مترابطة بحسب آثارها وغاياتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص278، 279، تحت «علة ترتيب المعاني الواصفة للكتاب»","url":""}]},{"id":"s16-133","number":133,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما دلالة إيثار استعمال الاسم الأحسن «الله» دون اسم الله «الرب»، وما سرّ ترتيب المأمورات في الآية؟","answer":"ذكر اسم الجلالة يضفي على الأمر مهابة وتعظيمًا، لأنه أمر المستحق للكمال. وقُدّم العدل الذي يقوم به أداء الواجب، ثم الإحسان الذي يتجاوزه إلى الفضل؛ فيترقى السياق من القدر اللازم إلى الزيادة في الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص284، 287، 288، تحت «إيثار استعمال الاسم الأحسن «الله» دون اسم الله «الرب»؛ سر ترتيب المأمورات في الآية»","url":""}]},{"id":"s16-134","number":134,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿ذِي الْقُرْبَى﴾ بالإفراد؟","answer":"الإفراد يجعل الخطاب متناولًا كل ذي قرابة على حدة؛ فيتوجه الاعتناء إلى كل فرد، ولا يكتفى بالنظر إلى الأقارب باعتبارهم جماعة. وهذا أدعى إلى توثيق صلة الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص289، تحت «سر إفراد «ذي»»","url":""}]},{"id":"s16-135","number":135,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما دلالة الجمع بين الفحشاء والمنكر والبغي؟","answer":"الفحشاء ما عظم قبحه، وعطف المنكر يوسّع النهي ليشمل ما يُنكر من المعاصي عمومًا. ثم خُصّ البغي، وهو التجاوز والعدوان، بالذكر اهتمامًا بالنهي عنه؛ وفي مقابلته للعدل تأكيد لقبح الاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص291، 292، 293، تحت «سر إيثار لفظ «الفحشاء» دون «الفاحشة» أو «الفواحش»؛ دلالة عطف «المنكر» على «الفحشاء»؛ إيثار لفظ «البغي» دون لفظ «الظلم»»","url":""}]},{"id":"s16-136","number":136,"surah":16,"verses":[90],"references":[{"surah":16,"verses":[90]}],"verseLabel":"النحل: 90","question":"ما سرّ ختم آية العدل والإحسان بقوله تعالى: ﴿لَعَلَّكُمْ تَذَكَّرُونَ﴾؟","answer":"لأن فضل هذه المأمورات وقبح هذه المنهيات مما تدركه النفوس ولا يحتاج إلى بحث خفي. فناسب الحث على استحضارها والتذكر بها؛ إذ يدعو ذلك إلى الامتثال وترك القبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص294، 295، تحت «إيثار لفظ «التذكر» دون غيره»","url":""}]},{"id":"s16-137","number":137,"surah":16,"verses":[91],"references":[{"surah":16,"verses":[91]}],"verseLabel":"النحل: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَنْقُضُوا الْأَيْمَانَ﴾ لا تنكثوا؟","answer":"النقض يستعمل في حلّ البناء والحبل والعقد بعد إحكامها، فاستعير لإبطال العهد. وهو أنسب هنا لتعظيم جناية الإخلال بالأيمان بعد توكيدها، في مقابل الأمر بالوفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص307، تحت «سر إيثار لفظ النقض دون النكث»","url":""}]},{"id":"s16-138","number":138,"surah":16,"verses":[91],"references":[{"surah":16,"verses":[91]}],"verseLabel":"النحل: 91","question":"ما سرّ تقديم الجار والمجرور «عليكم» على المفعول الثاني «كفيلًا»؟","answer":"تقديم «عليكم» يخصّ المخاطبين بهذه الشهادة: أنتم الذين استشهدتم بالله على أنفسكم حين حلفتم. وفي ذلك تهويل لنقض اليمين وتذكير بما ألزموا به أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص309، 310، تحت «سر تقديم الجار والمجرور «عليكم» على المفعول الثاني «كفيلًا»»","url":""}]},{"id":"s16-139","number":139,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"ما دلالة تشبيه ناقض العهد بالتي نقضت غزلها؟","answer":"يشبّه ناقض العهد بمن تحكم غزلها ثم تحلّه بيدها؛ فيصوّر إبطال المرء ما أنفق جهده في إحكامه. والغرض تشنيع هذا الفعل وإظهار سفه فاعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص318، تحت «دلالة التشبيه في الآية وأثره»","url":""}]},{"id":"s16-140","number":140,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"ما دلالة التعبير بالمصدر المؤول في قوله تعالى: ﴿أن تكون أمة هي أربى من أمة﴾؟","answer":"حوّل المصدر المؤول معنى تفوق جماعة إلى علة متصورة لنقض الأيمان، ففضح اتخاذ كثرة فريق ذريعةً للتقلب في العهود.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص323، تحت «دلالة التعبير بالمصدر المؤول»","url":""}]},{"id":"s16-227","number":227,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"لماذا اختير لفظ ﴿أربى﴾ في وصف أمة؟","answer":"يفيد الزيادة والنماء، فيصور جماعة أكثر عددًا أو قوة، ويكشف أن باعث نقض العهد منفعة متوهمة تتبع الطرف الأقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص323، تحت «سر إيثار لفظ «أربى»»","url":""}]},{"id":"s16-141","number":141,"surah":16,"verses":[92],"references":[{"surah":16,"verses":[92]}],"verseLabel":"النحل: 92","question":"ما علة فصل جملة «إنما يبلوكم الله به» عما قبلها، وما وجه البلاغة في الحصر بـ«إنما»؟","answer":"فُصلت الجملة لتعلّل ما يقع من تفاوت بين الجماعات: إنه ابتلاء يظهر به الوفاء بالعهد. و«إنما» تقصر هذا التفاوت على كونه اختبارًا في هذا المقام، فلا يجعل ذريعة إلى نقض الأيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص324، تحت «علة فصل جملة «إنما يبلوكم الله به» عما قبلها؛ بلاغة الحصر بـ«إنما»»","url":""}]},{"id":"s16-142","number":142,"surah":16,"verses":[94],"references":[{"surah":16,"verses":[94]}],"verseLabel":"النحل: 94","question":"ما وجه البلاغة في الاستعارة في جملة «فتزل قدم بعد ثبوتها»؟","answer":"صُوّر الانحراف عن الاستقامة بعد التمكن منها بزلة قدم بعد رسوخها؛ فالمعنى النفسي والديني يصير مشهدًا محسوسًا للسقوط بعد الثبات. وفيه تحذير من أثر اتخاذ الأيمان خديعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص352، تحت «بلاغة الاستعارة في جملة «فتزل قدم بعد ثبوتها»»","url":""}]},{"id":"s16-143","number":143,"surah":16,"verses":[94],"references":[{"surah":16,"verses":[94]}],"verseLabel":"النحل: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿بَعْدَ ثُبُوتِهَا﴾ لا ثباتها؟","answer":"يفيد المصدر تحقق الرسوخ قبل الزلة، فيشتد به تصوير الانتقال من حال إلى ضدها. ويذكر المصدر توجيهًا لغويًا يخص «الثبوت» هنا بالرسوخ المعنوي والمجازي، فيناسب ثبات المرء على العهد والحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص351، تحت «نكتة التعبير بالثبوت دون الثبات»","url":""}]},{"id":"s16-144","number":144,"surah":16,"verses":[94],"references":[{"surah":16,"verses":[94]}],"verseLabel":"النحل: 94","question":"ما وجه البلاغة في الاستعارة التبعية المكنية في «وتذوقوا السوء»؟","answer":"صُوّر الإحساس بالسوء بذوق طعام مرّ مستبشع، فينقل أثر العذاب من معنى مجرد إلى تجربة حسية مباشرة. ويؤكد التعبير شدة إدراكهم عاقبة فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص353، 354، تحت «بلاغة الاستعارة التبعية المكنية في «وتذوقوا السوء»»","url":""}]},{"id":"s16-145","number":145,"surah":16,"verses":[95],"references":[{"surah":16,"verses":[95]}],"verseLabel":"النحل: 95","question":"ما وجه البلاغة في المجاز بالاستعارة في «ولا تشتروا»، وكيف يُوجَّه بلاغيًا الصفة «قليلًا»؟","answer":"صُوّر استبدال الوفاء بالعهد بحظ دنيوي بصورة المعاوضة والشراء. و«قليلًا» تكشف ضآلة كل عوض يؤخذ بإزاء نقض عهد الله، مهما بدا كثيرًا، إذا قيس بما عنده من الثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص363، 364، 365، تحت «بلاغة المجاز بالاستعارة في «ولا تشتروا»؛ توجيه الصفة «قليلًا»»","url":""}]},{"id":"s16-146","number":146,"surah":16,"verses":[96],"references":[{"surah":16,"verses":[96]}],"verseLabel":"النحل: 96","question":"لماذا قيل: ﴿ما عندكم ينفد وما عند الله باق﴾؟","answer":"عبّر عن متاع الناس بالمضارع لتجدد نفاده، وعن ثواب الله باسم الفاعل لإفادة ثبات بقائه ودوامه؛ فبرز التفاوت بين الزائل والدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص374، تحت «بلاغة العدول عن المضارع إلى اسم الفاعل في وصف ما عند الله»","url":""}]},{"id":"s16-147","number":147,"surah":16,"verses":[96],"references":[{"surah":16,"verses":[96]}],"verseLabel":"النحل: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ صَبَرُوا﴾ لا الصابرين؟","answer":"الموصول وصلته يبرزان الصبر علة للجزاء. ويذكر المصدر أن التعبير بالفعل يفتح باب الرجاء لمن تحقق منه الصبر، ولو لم يصر وصفًا دائمًا له؛ فكيف بمن جعله سجيّة ثابتة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص376، 377، تحت «سر التعبير بالاسم الموصول «الذين»؛ سر العدول من «الصابرين» إلى «الذين صبروا»»","url":""}]},{"id":"s16-148","number":148,"surah":16,"verses":[97],"references":[{"surah":16,"verses":[97]}],"verseLabel":"النحل: 97","question":"لماذا صرّح بـ﴿مِنْ ذَكَرٍ أَوْ أُنْثَى﴾ مع أن ﴿من﴾ تعم؟","answer":"لزيادة تأكيد شمول الوعد للرجال والنساء وإزالة توهم اختصاصه بالذكور. فالتصريح يقرر أن مناط هذا الجزاء العمل الصالح مع الإيمان، ويصحح تصورات تنقص المرأة من حقها فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص385، 386، تحت «فائدة التصريح بالذكر والأنثى مع دلالة «من» على العموم»","url":""}]},{"id":"s16-149","number":149,"surah":16,"verses":[97],"references":[{"surah":16,"verses":[97]}],"verseLabel":"النحل: 97","question":"ما سر تنكير ﴿حياة﴾ في قوله: ﴿فلنحيينه حياة طيبة﴾؟","answer":"يفيد التعظيم والتفخيم؛ فهي حياة متميزة بالرضا والطمأنينة وحسن العيش، لا مجرد بقاء جسدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص390، تحت «نكتة تنكير الحياة»","url":""}]},{"id":"s16-150","number":150,"surah":16,"verses":[98],"references":[{"surah":16,"verses":[98]}],"verseLabel":"النحل: 98","question":"ما دلالة الأمر في قوله: ﴿فاستعذ بالله﴾ عند قراءة القرآن؟","answer":"يرشد إلى الالتجاء إلى الله وطلب الحماية من وساوس الشيطان قبل التلاوة، لتصفو النفس لتدبر الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص400، تحت «بيان التعبير بالأمر»","url":""}]},{"id":"s16-228","number":228,"surah":16,"verses":[98],"references":[{"surah":16,"verses":[98]}],"verseLabel":"النحل: 98","question":"لماذا نصت الآية على الاستعاذة عند القراءة؟","answer":"لأن المقام مقام دفع عدو يصد عن الفهم والعمل، فناسبه طلب العصمة من شره، أما البسملة فمقصودها البدء باسم الله والتبرك به.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص403، تحت «إيثار الاستعاذة على البسملة»","url":""}]},{"id":"s16-151","number":151,"surah":16,"verses":[98],"references":[{"surah":16,"verses":[98]}],"verseLabel":"النحل: 98","question":"ما سرّ تعريف القرآن وإظهار اسمه في آية الاستعاذة؟","answer":"في التعريف وإظهار اسم القرآن تذكير بعظم المقروء: إنه الكتاب الجامع لصفات الكمال والتبيان. ويبرز الاسم معنى الجمع والضم، بدل الاكتفاء بضمير يعود إلى الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص399، تحت «وجها تعريف القرآن وإظهاره»","url":""}]},{"id":"s16-152","number":152,"surah":16,"verses":[99],"references":[{"surah":16,"verses":[99]}],"verseLabel":"النحل: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿لَيْسَ لَهُ سُلْطَانٌ﴾ لا قدرة؟","answer":"لفظ السلطان يجمع معاني التسلط والولاية والاستيلاء والتمكن، ويستعمل أيضًا للحجة. واختياره هنا ينفي عن الشيطان هذا السلطان على أهل الإيمان والتوكل، فلا يجد في اعتمادهم على ربهم مدخلًا يستولي به عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص408، 409، تحت «إيثار لفظ السلطان دون غيره»","url":""}]},{"id":"s16-153","number":153,"surah":16,"verses":[99],"references":[{"surah":16,"verses":[99]}],"verseLabel":"النحل: 99","question":"ما سر قوله: ﴿على ربهم يتوكلون﴾ بلفظ الرب وإضافته إليهم؟","answer":"يستحضر رعايته وتربيته للمؤمنين، فيقوى اعتمادهم على من يتولى شؤونهم ويحفظهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص410، تحت «إيثار لفظ الرب دون غيره وإضافته إلى ضمير المؤمنين»","url":""}]},{"id":"s16-229","number":229,"surah":16,"verses":[99],"references":[{"surah":16,"verses":[99]}],"verseLabel":"النحل: 99","question":"لماذا قدم ﴿على ربهم﴾ في قوله: ﴿وعلى ربهم يتوكلون﴾؟","answer":"يفيد تخصيص التوكل بالله وحده؛ فهم يأخذون بالأسباب ولا يعتمدون في النتيجة إلا على ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص410، تحت «نكتة تقديم شبه الجملة على الفعل»","url":""}]},{"id":"s16-154","number":154,"surah":16,"verses":[101],"references":[{"surah":16,"verses":[101]}],"verseLabel":"النحل: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِذَا بَدَّلْنَا آيَةً مَكَانَ آيَةٍ﴾ لا نسخنا؟","answer":"التبديل يبرز وضع آية مكان آية، فيجمع رفع ما سبق وإقامة غيره مقامه وفق الحكمة والمصلحة. فهو يصوّر في السياق معنى الاستبدال، لا مجرد الرفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص420، 421، تحت «إيثار لفظ التبديل دون النسخ والتعويض»","url":""}]},{"id":"s16-155","number":155,"surah":16,"verses":[101],"references":[{"surah":16,"verses":[101]}],"verseLabel":"النحل: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ أَعْلَمُ بِمَا يُنَزِّلُ﴾ اعتراضًا؟","answer":"وقعت الجملة بين الشرط وجوابه لتدفع تهمة الافتراء، وتقرر أن تبديل الآية نابع من علم الله وحكمته ومراعاته للمصالح. فهي تنبّه إلى أن تبدل الحكم ليس تناقضًا ولا تصرفًا من الرسول من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص422، 423، تحت «فائدة جملة الاعتراض»","url":""}]},{"id":"s16-156","number":156,"surah":16,"verses":[102],"references":[{"surah":16,"verses":[102]}],"verseLabel":"النحل: 102","question":"ما سرّ تقديم الهدى على البشرى في وصف القرآن؟","answer":"الهداية هي المقصود الأول الذي يسعى إليه المسلم، والبشرى ثمرة الاهتداء. فقُدّم الأصل والأهم، ثم ما يترتب عليه من البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص436، تحت «إيثار الوصفين الهدى والبشرى دون غيرهما ومراعاة الترتيب بينهما»","url":""}]},{"id":"s16-157","number":157,"surah":16,"verses":[102],"references":[{"surah":16,"verses":[102]}],"verseLabel":"النحل: 102","question":"ما دلالة تسمية جبريل ﴿روح القدس﴾؟","answer":"الروح تشير إلى أن الوحي يحيي القلوب، والقدس إلى الطهر؛ ففي الاسم تشريف للملك وتنزيه لمصدر القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص433، تحت «بلاغة إضافة الروح إلى القدس»","url":""}]},{"id":"s16-230","number":230,"surah":16,"verses":[102],"references":[{"surah":16,"verses":[102]}],"verseLabel":"النحل: 102","question":"كيف يسند تنزيل القرآن إلى جبريل مع أن الله أنزله؟","answer":"الله هو المنزل أمرًا ووحيًا، وجبريل مباشر النزول بالتبليغ؛ فالإسنادان يبينان الآمر والواسطة ولا تعارض بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص433، تحت «وجه إسناد الإنزال إلى روح القدس بعد إسناده إليه تعالى»","url":""}]},{"id":"s16-158","number":158,"surah":16,"verses":[103],"references":[{"surah":16,"verses":[103]}],"verseLabel":"النحل: 103","question":"ما وجه البلاغة في القصر بـ«إنما»، وما دلالة التعبير بقولهم «بشر» دون غيره؟","answer":"قصدوا قصر مصدر ما يأتي به الرسول على تعليم بشر، نافيـن عنه الوحي. واختيار «إنما» يصوّر دعواهم الباطلة كأنها حقيقة مقررة، مع ما في وصف المعلّم بأنه بشر من جحود مصدر القرآن الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص447، 448، تحت «بلاغة القصر بـ«إنما»؛ دلالة التعبير بقولهم «بشر» دون غيره»","url":""}]},{"id":"s16-159","number":159,"surah":16,"verses":[103],"references":[{"surah":16,"verses":[103]}],"verseLabel":"النحل: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿لِسَانُ الَّذِي يُلْحِدُونَ إِلَيْهِ أَعْجَمِيٌّ﴾ لا أعجم؟","answer":"يربط المصدر هذا الوصف بالعجمة وعدم الإبانة، ويرى في صيغة النسبة تقوية لهذا المعنى حتى كأن العجمة تمكنت من صاحب اللسان. وفي مقابلة ذلك بالقرآن العربي المبين إبطال لدعوى أن هذا الشخص مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص455، 456، تحت «براعة التعبير بقوله «أعجمي»؛ سر العدول عن «أعجم» إلى «أعجمي»»","url":""}]},{"id":"s16-160","number":160,"surah":16,"verses":[103],"references":[{"surah":16,"verses":[103]}],"verseLabel":"النحل: 103","question":"لماذا وصف لسان القرآن بـ﴿عَرَبِيٌّ مُبِينٌ﴾ لا فصيح؟","answer":"الفصاحة داخلة في وصف العربية، أما «مبين» فتزيد بيان أثر القرآن: يوضح المعاني والحقائق ويكشفها للسامعين. فالوصف يبرز وظيفة البيان، لا جودة الألفاظ وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص458، تحت «سر إيثار الوصف بالإبانة دون الفصاحة»","url":""}]},{"id":"s16-161","number":161,"surah":16,"verses":[104],"references":[{"surah":16,"verses":[104]}],"verseLabel":"النحل: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ لَا يُؤْمِنُونَ﴾ لا الكافرون؟","answer":"الصلة تذكر الصفة التي تعلق بها الحكم: امتناعهم عن الإيمان بالآيات. والمضارع المنفي يصوّر استمرار هذا الامتناع وتجدد رفضهم، فيربط حرمانهم من الهداية بإعراضهم المتكرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص466، 467، تحت «سر العدول عن التعبير بالكافرين إلى «الذين لا يؤمنون»؛ دلالة التعبير بالمضارع المنفي»","url":""}]},{"id":"s16-162","number":162,"surah":16,"verses":[105],"references":[{"surah":16,"verses":[105]}],"verseLabel":"النحل: 105","question":"ما دلالة القصر في قوله: ﴿إنما يفتري الكذب الذين لا يؤمنون بآيات الله﴾؟","answer":"يحصر اختلاق الكذب فيمن لا يؤمن بآيات الله، فينفيه عن الرسول ويبين أن تهمة المشركين عائدة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص477، تحت «دلالة القصر»","url":""}]},{"id":"s16-163","number":163,"surah":16,"verses":[105],"references":[{"surah":16,"verses":[105]}],"verseLabel":"النحل: 105","question":"ما سر التذييل بقوله: ﴿وأولئك هم الكاذبون﴾؟","answer":"أكد بضمير الفصل والقصر أن الكذب صفتهم المحققة، فصار التذييل حكمًا عامًا يرد افتراءهم على الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص483، تحت «بلاغة القصر في جملة التذييل»","url":""}]},{"id":"s16-164","number":164,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما وجه البلاغة في موقع جملة «وقلبه مطمئن بالإيمان»، وما النكتة البلاغية في اصطفاء وصف الاطمئنان للقلب؟","answer":"جاءت الجملة حالًا تقيد الاستثناء: يقع الإكراه على القول الظاهر مع بقاء القلب ثابتًا على الإيمان. ووصف الاطمئنان يصور رسوخ التصديق رغم الخطر والاضطراب الخارجي، فيميز هذه الحال ممن رضي بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص498، 499، تحت «بلاغة موقع جملة «وقلبه مطمئن بالإيمان»؛ نكتة اصطفاء وصف الاطمئنان للقلب»","url":""}]},{"id":"s16-165","number":165,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما سرّ التعبير في قوله تعالى: ﴿قَلْبُهُ﴾ لا فؤاده؟","answer":"يناسب القلب هنا معنى استقرار الإيمان وثباته، وقد قُيّد بالاطمئنان لبيان ذلك. ويذكر المصدر أن الفؤاد أنسب في أصل دلالته للتوقد والتحرق والتوثب، فلا يلائم هذا المقام كما يلائمه القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص498، تحت «سر التعبير بالقلب دون الفؤاد»","url":""}]},{"id":"s16-166","number":166,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما سرّ التعبير بفعل الشرح في قوله تعالى: ﴿شرح بالكفر صدرًا﴾؟","answer":"الشرح يدل على التوسعة؛ فصور من يختار الكفر راضيًا بأنه فتح له صدره وقبله اختيارًا، لا مكرهًا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص504، تحت «سر التعبير بفعل الشرح»","url":""}]},{"id":"s16-231","number":231,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"لماذا قال: ﴿شرح بالكفر صدرًا﴾ ولم يقل قلبًا؟","answer":"الصدر موضع الانفساح والاحتواء، فالتعبير يصور إحاطة الكفر بباطنه واستقباله له على سعة، مع بقاء القلب موضع الاعتقاد في الداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص506، تحت «سر التعبير بـ«صدرًا» دون القلب»","url":""}]},{"id":"s16-167","number":167,"surah":16,"verses":[106],"references":[{"surah":16,"verses":[106]}],"verseLabel":"النحل: 106","question":"ما سرّ تقديم ﴿فَعَلَيْهِمْ غَضَبٌ مِنَ اللَّهِ﴾؟","answer":"تقديم «عليهم» يلفت إلى اختصاصهم بهذا الوعيد واستحقاقهم الغضب بسبب رضاهم بالكفر، وفيه بيان أنهم ألحقوه بأنفسهم باختيارهم. كما يناسب تقديمَ الخبر على النكرة المراد تعظيمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص507، تحت «دلالة تقديم المسند في قوله «فعليهم غضب»»","url":""}]},{"id":"s16-168","number":168,"surah":16,"verses":[107],"references":[{"surah":16,"verses":[107]}],"verseLabel":"النحل: 107","question":"ما النكتة البلاغية في التعبير بالحب في قوله «استحبوا»، وأين تتجلى براعة التعبير بقوله «استحبوا»؟","answer":"الاستحباب هنا يتجاوز الميل إلى الإيثار: قدّموا الدنيا على الآخرة وطلبوا حظها. وتفيد الصيغة، في التوجيه المذكور، شدة التعلق والتكلف في طلب المحبوب، لا مجرد حب عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص517، 518، تحت «نكتة التعبير بالحب في قوله «استحبوا»؛ براعة التعبير بقوله «استحبوا»»","url":""}]},{"id":"s16-169","number":169,"surah":16,"verses":[108],"references":[{"surah":16,"verses":[108]}],"verseLabel":"النحل: 108","question":"لماذا قال: ﴿طبع الله على قلوبهم﴾ ولم يقل ختم؟","answer":"الطبع أدل على ثبات الأثر وتمكنه حتى يصير كالعلامة الملازمة؛ وهو مناسب لاستحكام إعراضهم بعد اختيارهم الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص526، تحت «سر التعبير بالطبع دون الختم»","url":""}]},{"id":"s16-170","number":170,"surah":16,"verses":[108],"references":[{"surah":16,"verses":[108]}],"verseLabel":"النحل: 108","question":"ما سرّ إفراد السمع وجمع الأبصار؟","answer":"من التوجيهات المذكورة أن السمع مصدر، والمصدر لا يلزمه الجمع، مع اتحاد جنس متعلقه وهو الصوت. أما الأبصار فتتفاوت جهاتها ومرئياتها وطرائق الاعتبار بها، فناسبها الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص531، 532، تحت «سر التعبير بالإفراد في قوله «وسمعهم»؛ سر التعبير بالجمع «وأبصارهم» دون المفرد»","url":""}]},{"id":"s16-171","number":171,"surah":16,"verses":[109],"references":[{"surah":16,"verses":[109]}],"verseLabel":"النحل: 109","question":"ما سر قوله: ﴿هم الخاسرون﴾ في جملة اسمية مقصورة؟","answer":"تفيد الاسمية ثبوت الخسارة، ويفيد القصر أنهم المستحقون لتمامها؛ لأنهم استبدلوا بالآخرة عرض الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص541، تحت «علة التعبير بالجملة الاسمية في الخسارة»","url":""}]},{"id":"s16-172","number":172,"surah":16,"verses":[110],"references":[{"surah":16,"verses":[110]}],"verseLabel":"النحل: 110","question":"ما دلالة حذف متعلقات ﴿هَاجَرُوا﴾ و﴿جَاهَدُوا﴾ و﴿صَبَرُوا﴾؟","answer":"حذف جهة الهجرة يشمل صورها دون حصرها في وجهة واحدة. وفي الجهاد والصبر يوجّه الحذف العناية إلى تحقق الفعلين نفسيهما، مع علم المخاطب بما يقتضيه السياق، فلا يتقيد الثناء بمفعول مذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص549، 552، تحت «دلالة حذف متعلق «هاجروا»؛ سر حذف مفعول «جاهدوا» وحذف متعلق «صبروا»»","url":""}]},{"id":"s16-173","number":173,"surah":16,"verses":[110],"references":[{"surah":16,"verses":[110]}],"verseLabel":"النحل: 110","question":"ما سرّ تقديم ﴿لَغَفُورٌ﴾ على ﴿رَحِيمٌ﴾؟","answer":"المغفرة سلامة من أثر الذنب، والرحمة إنعام وإحسان؛ فناسب أن يقدم رفع الضرر ثم يذكر ما يعقبه من الفضل. وفي الترتيب طمأنة للمؤمنين بوعد العفو والإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص557، 558، تحت «فائدة تقديم «لغفور» على «رحيم»»","url":""}]},{"id":"s16-174","number":174,"surah":16,"verses":[111],"references":[{"surah":16,"verses":[111]}],"verseLabel":"النحل: 111","question":"ما فائدة استعمال «كل» دون جمع النفس، وما النكتة البلاغية في اختيار «تجادل» دون تدافع؟","answer":"«كل نفس» تنص على شمول الموقف لكل إنسان. والمضارع يستحضر مشهد المجادلة، واختيارها يصور شدة تمسك النفس بما ترجوه سبيلًا إلى النجاة، مع انشغال كل امرئ بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص563، 564، 565، تحت «فائدة استعمال «كل» دون جمع النفس؛ نكتة اختيار «تجادل» دون تدافع»","url":""}]},{"id":"s16-175","number":175,"surah":16,"verses":[111],"references":[{"surah":16,"verses":[111]}],"verseLabel":"النحل: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا عَمِلَتْ﴾ لا ما قدمت؟","answer":"العمل يعم ما قام به الإنسان في الدنيا من خير أو شر. أما التقديم فقد يغلب في المقام الذي يراد فيه ما قدّمه المرء للثواب؛ فناسب لفظ العمل هنا شمول الجزاء لجميع الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص568، تحت «فائدة ذكر مفردة العمل دون لفظ التقديم»","url":""}]},{"id":"s16-176","number":176,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما دلالة إسناد الأمن والكفر والعذاب إلى القرية؟","answer":"المراد أهلها، لكن إسناد أحوالهم إلى القرية يصور أثرها وقد عم المكان كله؛ فتبدو النعمة ثم عاقبة جحودها مشهدًا شاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص578، تحت «بلاغة المجاز العقلي»","url":""}]},{"id":"s16-177","number":177,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما أثر إسناد الإتيان إلى الرزق في قوله: ﴿يأتيها رزقها﴾؟","answer":"يصوّر الرزق كأنه يقصد أهل القرية ويصل إليهم ميسرًا، من غير عناء شديد في طلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص581، تحت «بلاغة إسناد الإتيان إلى الرزق»","url":""}]},{"id":"s16-232","number":232,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما وجه البلاغة في تقييد إتيان الرزق بـ«رغدًا»؟","answer":"يبين سعة الرزق وهناءه وسهولة الانتفاع به، فلا يقتصر وصف النعمة على مجرد وجود القوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص582، تحت «بلاغة تقييد إتيان الرزق بـ«رغدًا»»","url":""}]},{"id":"s16-233","number":233,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما أثر قوله: ﴿من كل مكان﴾ في وصف رزق القرية؟","answer":"يفيد كثرة موارده وتنوع جهاته، فتكتمل صورة النعمة المحيطة التي كان حقها الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص583، تحت «دلالة التعبير بصيغة العموم»","url":""}]},{"id":"s16-178","number":178,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما سر جمع الذوق واللباس في قوله: ﴿فأذاقها الله لباس الجوع والخوف﴾؟","answer":"الإذاقة تصور الإحساس المباشر المتمكن بالألم، واللباس يصور إحاطة الجوع والخوف وملازمتهما؛ فاجتمع الباطن المحسوس والأثر المحيط.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص588، تحت «براعة اجتماع استعارات فريدة ومعان تليدة»","url":""}]},{"id":"s16-179","number":179,"surah":16,"verses":[112],"references":[{"surah":16,"verses":[112]}],"verseLabel":"النحل: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا كَانُوا يَصْنَعُونَ﴾ لا يعملون؟","answer":"الصنع يبرز تعمدهم الكفر وتفننهم فيه حتى صار عادة راسخة. والمضارع يصوّر تجدده واستمراره؛ فليس المقصود هفوة عابرة، بل سلوكًا يداومون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص595، 596، تحت «سر إيثار لفظ «يصنعون»؛ نكتة التعبير بالفعل المضارع»","url":""}]},{"id":"s16-180","number":180,"surah":16,"verses":[113],"references":[{"surah":16,"verses":[113]}],"verseLabel":"النحل: 113","question":"ما دلالة قوله: ﴿وهم ظالمون﴾ بعد أخذ العذاب لهم؟","answer":"الجملة حالية، واسميتها تقرر رسوخهم في الظلم وقت العقوبة؛ فظهر أن العذاب أخذهم وهم مقيمون على الكفر والتكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص601، تحت «بلاغة الاسمية في جملة الفاصلة»","url":""}]},{"id":"s16-181","number":181,"surah":16,"verses":[114],"references":[{"surah":16,"verses":[114]}],"verseLabel":"النحل: 114","question":"ما سرّ تقديم ﴿حَلَالًا﴾ على ﴿طَيِّبًا﴾؟","answer":"الحلال هو الأصل في إباحة الأكل، والطيب وصف تابع يكمل الانتفاع به واستطابته. فقُدّم ما تقوم عليه مشروعية الأكل، ثم ذُكر ما يصف جودته وملاءمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص609، تحت «نكتة تقديم «حلالًا» على «طيبًا»»","url":""}]},{"id":"s16-182","number":182,"surah":16,"verses":[114],"references":[{"surah":16,"verses":[114]}],"verseLabel":"النحل: 114","question":"ما سرّ إفراد ﴿نِعْمَتَ اللَّهِ﴾ في آية الأكل والشكر؟","answer":"يذكر المصدر أن المراد في هذا السياق نعمة الأكل من الرزق الحلال الطيب، أو نعمة المباحات من الطعام في مجموعها. فلحظها نعمة واحدة جامعة، فناسب إفرادها بعد الأمر بالأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص610، تحت «نكتة إفراد «نعمت الله»»","url":""}]},{"id":"s16-184","number":184,"surah":16,"verses":[115],"references":[{"surah":16,"verses":[115]}],"verseLabel":"النحل: 115","question":"لماذا قيل: ﴿وما أهل لغير الله به﴾ ولم يصرح بالأصنام؟","answer":"لفظ «غير» مع الموصول يعم كل ما ذبح متوجهًا به إلى سوى الله، فلا يحصر الحكم في أصنام مسماة، وفيه إيجاز وشمول.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص616، تحت «نكتة استعمال «لغير الله» دون التصريح بالأصنام»","url":""}]},{"id":"s16-185","number":185,"surah":16,"verses":[115],"references":[{"surah":16,"verses":[115]}],"verseLabel":"النحل: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنِ اضْطُرَّ﴾ لا أُجبر؟","answer":"الاضطرار أعم؛ فقد ينشأ من حاجة ملجئة داخلية، وقد يكون بسبب ضغط خارجي. أما الإجبار فيغلب فيه حمل الغير للإنسان على الفعل؛ فاختير الأعم لاستيعاب صور الضرورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص618، 619، تحت «نكتة اختيار لفظ الاضطرار دون الإجبار»","url":""}]},{"id":"s16-186","number":186,"surah":16,"verses":[115],"references":[{"surah":16,"verses":[115]}],"verseLabel":"النحل: 115","question":"ما مناسبة ختام حكم المضطر بقوله تعالى: ﴿إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ﴾؟","answer":"غفور للمضطر فيما أكل، رحيم به حين رخّص له عند الاضطرار؛ فجمع له العفو والرخصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص621، 622، تحت «نكتة جمع وصفي «غفور رحيم»»","url":""}]},{"id":"s16-187","number":187,"surah":16,"verses":[116],"references":[{"surah":16,"verses":[116]}],"verseLabel":"النحل: 116","question":"ما دلالة إسناد وصف الكذب إلى الألسنة في الآية؟","answer":"في الإسناد إلى الألسنة تشنيع لافترائهم، إذ يجعل أدوات البيان نفسها تباشر الكذب على الله. ويكشف أنهم يطلقون من القول ما يعلمون بطلانه في أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص630، تحت «نكتة إسناد وصف الكذب إلى الألسن»","url":""}]},{"id":"s16-188","number":188,"surah":16,"verses":[116],"references":[{"surah":16,"verses":[116]}],"verseLabel":"النحل: 116","question":"ما سر قوله: ﴿تفتروا على الله الكذب﴾ بدل أن تكذبوا؟","answer":"الافتراء يبرز الاختلاق المتعمد، وذكر الكذب معه يؤكد قبح الصنيع وشناعة نسبة الحكم المصنوع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص633، تحت «نكتة ذكر افتراء الكذب دون الكذب مباشرة»","url":""}]},{"id":"s16-234","number":234,"surah":16,"verses":[116],"references":[{"surah":16,"verses":[116]}],"verseLabel":"النحل: 116","question":"لماذا قدم ﴿على الله﴾ على ﴿الكذب﴾؟","answer":"يركز التقديم على عظم الجناية؛ فهي ليست خبرًا كاذبًا فحسب، بل كذب متعمد منسوب إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص634، تحت «فائدة تقديم الجار والمجرور على المفعول»","url":""}]},{"id":"s16-189","number":189,"surah":16,"verses":[117],"references":[{"surah":16,"verses":[117]}],"verseLabel":"النحل: 117","question":"ما دلالة وصف منفعة الافتراء بأنها ﴿متاع قليل﴾؟","answer":"يحقر ما ينالونه في الدنيا، فهو محدود زائل مهما بدا كبيرًا، فلا يساوي ما يترتب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص638، تحت «بلاغة وصف المتاع بالقليل»","url":""}]},{"id":"s16-235","number":235,"surah":16,"verses":[117],"references":[{"surah":16,"verses":[117]}],"verseLabel":"النحل: 117","question":"ما أثر عطف قوله: ﴿ولهم عذاب أليم﴾ على المتاع القليل؟","answer":"يجمع لهم بين حقارة المكسب العاجل وفداحة الجزاء الآجل، فتظهر خسارة من آثر الزائل على النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص639، تحت «دلالة الواو في قوله «ولهم عذاب أليم»»","url":""}]},{"id":"s16-190","number":190,"surah":16,"verses":[119],"references":[{"surah":16,"verses":[119]}],"verseLabel":"النحل: 119","question":"ما سرّ إعادة ﴿إِنَّ رَبَّكَ﴾ في قوله تعالى: ﴿إِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَحِيمٌ﴾؟","answer":"أعيد صدر الجملة بعد طول الفصل لإحكام اتصال الخبر بمن وعدهم الله بالمغفرة. وفي الإعادة أيضًا توكيد للوعد وتنويه به، حتى لا يضيع مع امتداد الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص658، تحت «نكتة فصل جملة «إن ربك من بعدها»»","url":""}]},{"id":"s16-191","number":191,"surah":16,"verses":[119],"references":[{"surah":16,"verses":[119]}],"verseLabel":"النحل: 119","question":"ما سر حذف مفعول ﴿أَصْلَحُوا﴾؟","answer":"ليعم إصلاح الاعتقاد والعمل وما أفسدته الجهالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص658، تحت «نكتة حذف متعلق «وأصلحوا»»","url":""}]},{"id":"s16-192","number":192,"surah":16,"verses":[120],"references":[{"surah":16,"verses":[120]}],"verseLabel":"النحل: 120","question":"ما سر وصف إبراهيم عليه السلام وحده بأنه ﴿أُمَّةً﴾؟","answer":"من توجيهات الوصف أنه إمام يُؤتم به، وأن ما قام به من خصال الخير يعادل ما تتوزعه جماعة. وفيه تعظيم لمنزلته وبيان اجتماع وجوه الهدى فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص667، 668، تحت «بلاغة المجاز في الوصف بالأمة»","url":""}]},{"id":"s16-193","number":193,"surah":16,"verses":[120],"references":[{"surah":16,"verses":[120]}],"verseLabel":"النحل: 120","question":"ما دلالة البناء الصرفي لقوله «قانتًا»، وما دلالة البناء الصرفي لقوله «حنيفًا»؟","answer":"«قانتًا» تصفه بالطاعة المستقرة لله، و«حنيفًا» تصفه بالميل عن الباطل إلى الحق. فاجتمع له دوام العبودية وصحة الوجهة، وجاء الوصفان دالين على تمكنهما فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص668، 669، تحت «دلالة البناء الصرفي لقوله «قانتًا»؛ البناء الصرفي لقوله «حنيفًا»»","url":""}]},{"id":"s16-194","number":194,"surah":16,"verses":[120],"references":[{"surah":16,"verses":[120]}],"verseLabel":"النحل: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَمْ يَكُ مِنَ الْمُشْرِكِينَ﴾ بحذف النون؟","answer":"حذف النون جائز للتخفيف في هذا التركيب المجزوم، ويذكر المصدر كثرة الاستعمال في تعليله. ومن توجيهاته البلاغية مناسبة هذا التخفيف لقوة نفي الشرك عن إبراهيم وبراءته منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص671، تحت «دلالة الموقع النحوي لقوله «ولم يك»»","url":""}]},{"id":"s16-195","number":195,"surah":16,"verses":[121],"references":[{"surah":16,"verses":[121]}],"verseLabel":"النحل: 121","question":"ما سرّ التعبير في قوله تعالى: ﴿شَاكِرًا لِأَنْعُمِهِ﴾ بجمع القلة؟","answer":"من التوجيهات المذكورة التنبيه بالأدنى على الأعلى: كان إبراهيم شاكرًا للنعم وإن قلّت، فكيف بالكثيرة؟ فجمع القلة يمدح استيعاب شكره، ولا يحصر نعم الله في عدد قليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص672، تحت «غرض التعبير بجمع القلة «لأنعمه»»","url":""}]},{"id":"s16-196","number":196,"surah":16,"verses":[121],"references":[{"surah":16,"verses":[121]}],"verseLabel":"النحل: 121","question":"ما النكتة البلاغية في فصل جملة «اجتباه»، وما الغرض البلاغي من تقديم الاجتباء على الهداية، وما الفرق الدلالي بين الاجتباء والاصطفاء؟","answer":"الاجتباء يتضمن الاختيار والإعداد والتهيئة. وفصل الجملة يناسب بيان ما منحه الله لإبراهيم بعد ذكر خصاله، وتقديم الاجتباء على الهداية من تقديم السبب على ثمرته في هذا السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص672، 673، 683، تحت «نكتة فصل جملة «اجتباه»؛ غرض تقديم الاجتباء على الهداية؛ الاجتباء والاصطفاء»","url":""}]},{"id":"s16-197","number":197,"surah":16,"verses":[122],"references":[{"surah":16,"verses":[122]}],"verseLabel":"النحل: 122","question":"ما سر تقديم ﴿فِي الدُّنْيَا﴾ و﴿فِي الْآخِرَةِ﴾؟","answer":"في تقديم «في الدنيا» عناية بموطن الإيتاء وتشويق إلى الحسنة المذكورة بعده. وتقديم «في الآخرة» يبرز مقام إبراهيم فيها ويشوّق إلى الحكم بأنه من الصالحين؛ فيتضح الإكرام في الدارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص676، 677، تحت «نكتة تقديم شبه الجملة «في الدنيا»؛ نكتة تقديم شبه الجملة «في الآخرة»»","url":""}]},{"id":"s16-198","number":198,"surah":16,"verses":[123],"references":[{"surah":16,"verses":[123]}],"verseLabel":"النحل: 123","question":"ما دلالة الأمر: ﴿اتبع ملة إبراهيم﴾؟","answer":"يدعو إلى الثبات على أصول الحنيفية الجامعة للتوحيد، ويبين أن رسالة محمد امتداد لدين الأنبياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص679، تحت «دلالة الأمر باتباع الملة»","url":""}]},{"id":"s16-236","number":236,"surah":16,"verses":[123],"references":[{"surah":16,"verses":[123]}],"verseLabel":"النحل: 123","question":"ما سر إضافة الملة إلى إبراهيم؟","answer":"تعظم شأن الملة وصاحبها، وتلزم من يدعي الانتساب إليه بحقيقة دينه: إخلاص العبادة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص680، تحت «نكتة الإضافة في «ملة إبراهيم»»","url":""}]},{"id":"s16-199","number":199,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما دلالة القصر في قوله: ﴿إنما جعل السبت على الذين اختلفوا فيه﴾؟","answer":"يخص تكليف السبت بالذين اختلفوا فيه، فيبين أنه تشريع خاص بهم لا أصل من ملة إبراهيم الحنيفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص690، تحت «بلاغة القصر في مطلع الآية»","url":""}]},{"id":"s16-237","number":237,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما دلالة الفعل ﴿جعل﴾ في شأن السبت؟","answer":"يفيد فرض تعظيم السبت وترتيب أحكامه عليهم بتشريع ملزم، لا مجرد اختيار عادة زمنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص690، تحت «نكتة التعبير بـ«جعل» مادة وصيغة»","url":""}]},{"id":"s16-238","number":238,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما أثر تعدية ﴿جعل﴾ بحرف ﴿على﴾؟","answer":"تشعر بالتكليف والإلزام وبما فيه من ثقل عليهم بسبب اختلافهم، فناسبت خصوصية الحكم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص691، تحت «نكتة تعدية الجعل بـ«على»»","url":""}]},{"id":"s16-200","number":200,"surah":16,"verses":[124],"references":[{"surah":16,"verses":[124]}],"verseLabel":"النحل: 124","question":"ما سر تقديم ﴿فِيهِ﴾ في قوله تعالى: ﴿فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ﴾؟","answer":"قُدّمت ﴿فيه﴾ على خبر «كان» لأن ما وقع فيه الاختلاف هو مدار الحديث وسبب الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص694، تحت «نكتة تقديم شبه الجملة «فيه»»","url":""}]},{"id":"s16-201","number":201,"surah":16,"verses":[125],"references":[{"surah":16,"verses":[125]}],"verseLabel":"النحل: 125","question":"لماذا جمعت الدعوة بين الحكمة والموعظة الحسنة؟","answer":"الحكمة تقيم البرهان وتضع الخطاب في موضعه، والموعظة تحرك القلب بالترغيب والترهيب؛ فتكامل خطاب العقل والوجدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص702، تحت «فائدة عطف الموعظة على الحكمة»","url":""}]},{"id":"s16-239","number":239,"surah":16,"verses":[125],"references":[{"surah":16,"verses":[125]}],"verseLabel":"النحل: 125","question":"لماذا أفرد الجدال بقوله: ﴿وجادلهم بالتي هي أحسن﴾؟","answer":"لأن الجدال يواجه معارضةً مباشرة فاحتاج أمرًا مستقلًا وقيدًا زائدًا بأحسن الطرق، اتقاء تحول الحجة إلى خصومة منفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص703، تحت «نكتة تغاير النظم في قوله «وجادلهم»»","url":""}]},{"id":"s16-202","number":202,"surah":16,"verses":[126],"references":[{"surah":16,"verses":[126]}],"verseLabel":"النحل: 126","question":"ما دلالة الشرط في قوله: ﴿وإن عاقبتم فعاقبوا بمثل ما عوقبتم به﴾؟","answer":"جعل العقوبة أمرًا مفروض الوقوع لا مطلوبًا، ثم قيد الرد بالمماثلة حتى لا يتجاوز قدر الاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص715، تحت «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s16-240","number":240,"surah":16,"verses":[126],"references":[{"surah":16,"verses":[126]}],"verseLabel":"النحل: 126","question":"ما دلالة قوله بعد إباحة المقابلة: ﴿ولئن صبرتم لهو خير للصابرين﴾؟","answer":"نكر الخير لتعظيم ما في الصبر من فضل وعاقبة حسنة، فرغب في العفو بعد أن قرر حق المقابلة العادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص717، تحت «نكتة تنكير «خير»»","url":""}]},{"id":"s16-203","number":203,"surah":16,"verses":[126],"references":[{"surah":16,"verses":[126]}],"verseLabel":"النحل: 126","question":"ما سر حذف مفعول ﴿عَاقَبْتُمْ﴾؟","answer":"حذف المفعول يعمم من يقع عليه الرد ممن يستحقه، ويوجه العناية إلى الفعل وضابطه: أن يكون بمثل ما وقع من الاعتداء، دون تجاوز.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص715، تحت «غرض حذف مفعول «عاقبتم»»","url":""}]},{"id":"s16-204","number":204,"surah":16,"verses":[127],"references":[{"surah":16,"verses":[127]}],"verseLabel":"النحل: 127","question":"ما دلالة الأمر في فعل الأمر «واصبر»، وما وجه البلاغة في القصر في قوله «وما صبرك إلا بالله»؟","answer":"الأمر يدعو إلى الثبات والدوام على الصبر، ثم يقرر القصر أن تحققه إنما يكون بتوفيق الله ومعونته. فتقترن المطالبة بالصبر بالتنبيه إلى مصدر القوة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص718، 719، تحت «دلالة الأمر في فعل الأمر «واصبر»؛ بلاغة القصر في قوله «وما صبرك إلا بالله»»","url":""}]},{"id":"s16-205","number":205,"surah":16,"verses":[127],"references":[{"surah":16,"verses":[127]}],"verseLabel":"النحل: 127","question":"ما دلالة حذف النون في ﴿وَلَا تَكُ فِي ضَيْقٍ﴾ في النحل، مع إثباتها في ﴿وَلَا تَكُنْ فِي ضَيْقٍ﴾ في النمل؟","answer":"الأصل النحوي يجيز حذف النون هنا للتخفيف، كما يجيز إثباتها في نحو آية النمل. ويذكر المصدر وجهًا بلاغيًا للحذف في النحل: المبالغة في التسلية، كأن المطلوب محو أقل أثر للضيق من النفس. فهذا توجيه لدلالة الحذف، لا حكم بأن الإثبات يضعف النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص719، 720، تحت «دلالة الموقع النحوي لقوله «تك»»، وتتمة شرح حذف النون في صدر ص720","url":""}]},{"id":"s16-206","number":206,"surah":16,"verses":[127],"references":[{"surah":16,"verses":[127]}],"verseLabel":"النحل: 127","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي ضَيْقٍ﴾ لا ذا ضيق؟","answer":"صُوّر الغم والأسف بضيـق المكان، وجُعل ظرفًا يحيط بالنفس. فالتعبير يرسم شدة استيلاء الضيق، ويأتي النهي تسلية للرسول وتحذيرًا من الاستغراق في الحزن بسبب مكرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص720، تحت «نكتة التعبير في قوله «في ضيق»؛ بلاغة الاستعارة في قوله «في ضيق»»","url":""}]},{"id":"s16-207","number":207,"surah":16,"verses":[128],"references":[{"surah":16,"verses":[128]}],"verseLabel":"النحل: 128","question":"ما مناسبة ختام السورة بقوله تعالى: ﴿إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوْا وَالَّذِينَ هُمْ مُحْسِنُونَ﴾؟","answer":"جاءت الخاتمة تعليلًا لما سبق من الأمر بالصبر والنهي عن الحزن والضيق. والمعية معية تأييد ونصر وولاية؛ فتطمئن المتقين المحسنين، ويجمع الوصفان اجتناب الشر والإقبال على الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص721، 722، 723، تحت «نكتة فصل قوله «إن الله مع الذين اتقوا»؛ دلالة دخول «مع» في السياق؛ نكتة عطف قوله «والذين هم محسنون»»","url":""}]},{"id":"s16-241","number":241,"surah":16,"verses":[14],"references":[{"surah":16,"verses":[14]}],"verseLabel":"النحل: 14","question":"ما سر تقديم «مواخر» على «فيه» في قوله: ﴿وَتَرَى الْفُلْكَ مَوَاخِرَ فِيهِ﴾، وقد قُدِّم الجار في فاطر: ﴿فِيهِ مَوَاخِرَ﴾؟","answer":"سياق النحل في وسائط النقل؛ فقد ذكر الأنعام تحمل الأثقال، والخيل والبغال والحمير للركوب، ثم ذكر الفلك وهي واسطة نقل أيضًا، فقدّم «مواخر» لأنها صفة الفلك في جريانها، وهذا ما يناسب سياق الحمل والانتقال. أما سياق فاطر فليس في وسائط النقل، فلم يقتضِ هذا التقديم.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص69.","url":""}]},{"id":"s16-242","number":242,"surah":16,"verses":[34],"references":[{"surah":16,"verses":[34]}],"verseLabel":"النحل: 34","question":"ما سر قوله: ﴿فَأَصَابَهُمْ سَيِّئَاتُ مَا عَمِلُوا﴾، وفي الزمر: ﴿سَيِّئَاتُ مَا كَسَبُوا﴾؟","answer":"وقعت آية النحل بين ألفاظ العمل، كقولهم: ﴿مَا كُنَّا نَعْمَلُ مِن سُوءٍ﴾ والرد: ﴿بِمَا كُنتُمْ تَعْمَلُونَ﴾، ووقعت آية الزمر بين ألفاظ الكسب. ويقوّي ذلك أن لفظ الكسب لم يرد في النحل البتة، وتكرر في الزمر خمس مرات، فوُضعت كل لفظة في موطنها. والتوجيه الأول منقول عن غيره.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص242–243.","url":""}]},{"id":"s16-243","number":243,"surah":16,"verses":[35],"references":[{"surah":16,"verses":[35]}],"verseLabel":"النحل: 35","question":"ما سر قوله في النحل: ﴿لَوْ شَاءَ اللَّهُ مَا عَبَدْنَا مِن دُونِهِ مِن شَيْءٍ نَّحْنُ وَلَا آبَاؤُنَا﴾، وفي الأنعام: ﴿مَا أَشْرَكْنَا وَلَا آبَاؤُنَا﴾؟","answer":"سياق النحل في الرد على الشرك في العبادة والنعي على المعبودات الباطلة، وقد بدأت بقوله: ﴿سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾، فذكر العبادة من دونه صراحة، وزاد «نحن» و«من دونه» توفيةً للمعنى وتوكيدًا. أما سياق الأنعام ففي التحريم والافتراء في الحرث والأنعام، فاكتفى بنفي الإشراك.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص265–269.","url":""}]},{"id":"s16-244","number":244,"surah":16,"verses":[64],"references":[{"surah":16,"verses":[64]}],"verseLabel":"النحل: 64","question":"ما سر ذكر «الهدى والرحمة» في الآية 64، و«الهدى والبشرى» في الآية 102، وجمع الثلاثة في الآية 89 من السورة نفسها؟","answer":"في الآية 64 ذكر غرضًا واحدًا من أغراض إنزال الكتاب، وهو تبيين ما اختلفوا فيه، فذكر الهدى والرحمة. وفي الآية 102 تقدّمها شيء من البشرى للصابرين والعاملين، فذكر الهدى والبشرى. أما الآية 89 فوصفت الكتاب بأنه ﴿تِبْيَانًا لِّكُلِّ شَيْءٍ﴾ فجمعت الأوصاف كلها.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص107–108.","url":""}]},{"id":"s16-245","number":245,"surah":16,"verses":[65],"references":[{"surah":16,"verses":[65]}],"verseLabel":"النحل: 65","question":"ما سر الإفراد في قوله: ﴿إِنَّ فِي ذَلِكَ لَآيَةً لِّقَوْمٍ يَسْمَعُونَ﴾، والجمع في الروم: ﴿لَآيَاتٍ﴾ مع أن المشهد واحد؟","answer":"زاد في الروم ذكر البرق خوفًا وطمعًا فزادت الآيات. ثم إنه قال في النحل: ﴿أَنزَلَ... فَأَحْيَا﴾ بالماضي، وقال في الروم: ﴿يُرِيكُمُ... وَيُنَزِّلُ... فَيُحْيِي﴾ بالمضارع، فتكرر التنزيل والإحياء والرؤية فصارت آيات لا آية واحدة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص78–79.","url":""}]},{"id":"s16-246","number":246,"surah":16,"verses":[66],"references":[{"surah":16,"verses":[66]}],"verseLabel":"النحل: 66","question":"ما سر تذكير الضمير في قوله: ﴿نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ﴾، وتأنيثه في المؤمنون: ﴿مِّمَّا فِي بُطُونِهَا﴾؟","answer":"الكلام في النحل على إسقاء اللبن، واللبن لا يخرج من جميع الأنعام بل من قسم من إناثها، فجاء بضمير المذكر الدال على القلة. أما المؤمنون فعلى منافع الأنعام عامة: ﴿وَلَكُمْ فِيهَا مَنَافِعُ كَثِيرَةٌ﴾، وهي تعم ذكورها وإناثها، فجاء بضمير المؤنث الدال على الكثرة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص179–180.","url":""}]},{"id":"s16-247","number":247,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]}],"verseLabel":"النحل: 72","question":"ما دلالة ذكر الضمير «هم» في قوله: ﴿وَبِنِعْمَتِ اللَّهِ هُمْ يَكْفُرُونَ﴾، وحذفه في العنكبوت: ﴿وَبِنِعْمَةِ اللَّهِ يَكْفُرُونَ﴾؟","answer":"في إسناد الفعل إلى الضمير المتقدم توكيد وتخصيص. وآية النحل في سياق النعم العامة المفصّلة، حتى تُسمّى السورة سورة النعم، فناسب زيادة الإنكار على من يكفر بعد كل تلك النعم. أما العنكبوت ففي قريش خاصة وجوّها الفتن والمحن. ولفظ النعمة ورد في النحل تسع مرات وفي العنكبوت مرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص95–97.","url":""}]},{"id":"s16-248","number":248,"surah":16,"verses":[80],"references":[{"surah":16,"verses":[80]}],"verseLabel":"النحل: 80","question":"ما دلالة لفظ «الإقامة» في قوله: ﴿يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ﴾، دون «الإقام»؟","answer":"خصّ القرآن «الإقام» بإقام الصلاة، كقوله: ﴿وَإِقَامَ الصَّلَاةِ﴾، واستعمل «الإقامة» لما يقابل الظعن والسفر، فجاءت هنا في مقابلة الظعن.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص20.","url":""}]},{"id":"s16-249","number":249,"surah":16,"verses":[120,122],"references":[{"surah":16,"verses":[120,122]}],"verseLabel":"النحل: 120، 122","question":"ما سر قوله في إبراهيم: ﴿وَآتَيْنَاهُ فِي الدُّنْيَا حَسَنَةً﴾، وفي العنكبوت: ﴿وَآتَيْنَاهُ أَجْرَهُ فِي الدُّنْيَا﴾؟","answer":"ما ورد في النحل هو كل ما ورد من خبر إبراهيم فيها، وقد وصفه بصفاته ولم يذكر له عملًا مع قومه، فلم يذكر الأجر لأن الأجر جزاء العمل. أما العنكبوت فذكرت دعوته قومه وصبره حتى قالوا: ﴿اقْتُلُوهُ أَوْ حَرِّقُوهُ﴾، فجزاه ربه وآتاه أجره.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص79–80.","url":""}]},{"id":"s16-250","number":250,"surah":16,"verses":[18],"references":[{"surah":16,"verses":[18]}],"verseLabel":"النحل: 18","question":"ما سر ختم آية النعم في النحل بقوله: ﴿إِنَّ اللَّهَ لَغَفُورٌ رَّحِيمٌ﴾، وختمها في إبراهيم بقوله: ﴿إِنَّ الْإِنسَانَ لَظَلُومٌ كَفَّارٌ﴾؟","answer":"آية إبراهيم في سياق وصف الإنسان وما جُبل عليه من تبديل نعمة الله كفرًا، فخُتمت بصفة الإنسان. وآية النحل في سياق صفات الله وتعداد نعمه وإثبات ألوهيته، فخُتمت بصفة المنعِم سبحانه. ولكل فاصلة مع ذلك انسجامها مع فواصل سورتها، لكن السياق هو الذي اقتضاها. وفي «البرهان» للكرماني نحو هذا التوجيه.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص224–226.","url":""}]},{"id":"s16-251","number":251,"surah":16,"verses":[29],"references":[{"surah":16,"verses":[29]}],"verseLabel":"النحل: 29","question":"ما دلالة اللام في قوله: ﴿فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ﴾، وقد جاء في الزمر وغافر: ﴿فَبِئْسَ﴾ بلا لام؟","answer":"وصف في النحل قومًا أشد جرمًا؛ ضلّوا وأضلّوا، وحملوا أوزارهم كاملة ومن أوزار الذين يضلونهم، فزاد عذابهم، فناسب زيادة اللام لتوكيد العذاب. وجاءت بعدها في أهل الجنة: ﴿وَلَنِعْمَ دَارُ الْمُتَّقِينَ﴾ فقابلت اللامُ اللامَ. أما آيتا الزمر وغافر ففي عامة الكفار.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص129–130.","url":""}]},{"id":"s16-252","number":252,"surah":16,"verses":[31],"references":[{"surah":16,"verses":[31]}],"verseLabel":"النحل: 31","question":"ما سر تقديم «فيها» في قوله: ﴿لَهُمْ فِيهَا مَا يَشَاءُونَ﴾، وتقديم «ما يشاؤون» في سورة ق: ﴿لَهُم مَّا يَشَاءُونَ فِيهَا﴾؟","answer":"لم يذكر في النحل من صفات أهل الجنة إلا أنهم متقون، فقدّم الجنة نفسها. أما في ق فتوسّع في ذكر صفاتهم وتعدادها، فناسب تقديم ما يشاؤون إكرامًا لهم، ثم زاد: ﴿وَلَدَيْنَا مَزِيدٌ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص131.","url":""}]},{"id":"s16-253","number":253,"surah":16,"verses":[35],"references":[{"surah":16,"verses":[35]}],"verseLabel":"النحل: 35","question":"ما دلالة قوله: ﴿كَذَلِكَ فَعَلَ الَّذِينَ مِن قَبْلِهِمْ﴾، وفي الأنعام: ﴿كَذَلِكَ كَذَّبَ الَّذِينَ مِن قَبْلِهِمْ﴾؟","answer":"تردد في الأنعام ذكر افترائهم وكذبهم على الله فيما حرّموا من الحرث والأنعام، فناسب «كذّب». أما النحل فسياقها في الشرك في العبادة وأفعال المشركين، فناسب «فعل».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص269.","url":""}]},{"id":"s16-254","number":254,"surah":16,"verses":[61],"references":[{"surah":16,"verses":[61]}],"verseLabel":"النحل: 61","question":"ما سر قوله: ﴿وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَابَّةٍ﴾، وفي فاطر: ﴿بِمَا كَسَبُوا مَا تَرَكَ عَلَى ظَهْرِهَا﴾؟","answer":"تقدّم آية النحل ذكر وأد البنات: ﴿أَمْ يَدُسُّهُ فِي التُّرَابِ﴾، وهو أشنع الظلم لأنه قتل نفس بريئة بلا جريمة، فناسب التصريح بالظلم. ولم يتقدم في فاطر مثل ذلك، بل ذُكر نفورهم ومكرهم السيئ واكتسابهم، فناسب «بما كسبوا». والتوجيه منقول عن «ملاك التأويل».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص145–147.","url":""}]},{"id":"s16-255","number":255,"surah":16,"verses":[61],"references":[{"surah":16,"verses":[61]}],"verseLabel":"النحل: 61","question":"ما سر تقديم الاستئخار في قوله: ﴿لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ﴾، وتقديم السبق في الحجر: ﴿مَّا تَسْبِقُ مِنْ أُمَّةٍ أَجَلَهَا وَمَا يَسْتَأْخِرُونَ﴾؟","answer":"قدّم التأخير في النحل لأكثر من مناسبة: فقد قال قبله: ﴿وَلَكِن يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُّسَمًّى﴾ فناسب التأخيرُ التأخير؛ ولأن الناس يريدون تأخير الأجل فقدّم ما يسعون إليه؛ ولأن الرغبة في البقاء ومدّ الأجل قد تكون من أسباب الظلم المذكور في أول الآية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص106.","url":""}]},{"id":"s16-256","number":256,"surah":16,"verses":[70],"references":[{"surah":16,"verses":[70]}],"verseLabel":"النحل: 70","question":"ما سر رسم ﴿لِكَيْ لَا يَعْلَمَ بَعْدَ عِلْمٍ شَيْئًا﴾ مفصولة، وفي الحج: ﴿لِكَيْلَا يَعْلَمَ مِن بَعْدِ عِلْمٍ﴾ موصولة؟","answer":"هذا من شؤون رسم المصحف الذي لا يُقاس عليه، ويبدو مع ذلك أن له ارتباطًا بالمعنى، والله أعلم. فـ«من» في الحج تفيد ابتداء الغاية، أي إن ذهاب العلم موصول بالعلم بلا فاصل، فوُصلت «كي» بـ«لا». وأما ﴿بَعْدَ عِلْمٍ﴾ في النحل فتحتمل الاتصال وتحتمل المهلة، فناسبها الفصل.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص109–112.","url":""}]},{"id":"s16-257","number":257,"surah":16,"verses":[79],"references":[{"surah":16,"verses":[79]}],"verseLabel":"النحل: 79","question":"ما سر قوله: ﴿مَا يُمْسِكُهُنَّ إِلَّا اللَّهُ﴾، وفي الملك: ﴿مَا يُمْسِكُهُنَّ إِلَّا الرَّحْمَنُ﴾؟","answer":"لفظ «الرحمن» لم يرد في النحل على طولها، وورد في الملك أربع مرات، ولفظ الجلالة ورد في النحل أربعًا وثمانين مرة. وسياق النحل في التوحيد والنعي على الشرك، وسياق الملك في مظاهر الرحمة. وذكر في الملك صفّ الطير وقبضها وهي حال راحة لها فناسبت الرحمة، وفي «ملاك التأويل» نحو هذا.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص112–115.","url":""}]},{"id":"s16-258","number":258,"surah":16,"verses":[114],"references":[{"surah":16,"verses":[114]}],"verseLabel":"النحل: 114","question":"ما سر الأمر بشكر النعمة في قوله: ﴿وَاشْكُرُوا نِعْمَتَ اللَّهِ﴾، والأمر بشكر الله في البقرة: ﴿وَاشْكُرُوا لِلَّهِ﴾؟","answer":"سياق آية البقرة في الكلام على الله وعلى ما يتخذه الكفار من أنداد، فناسب الأمر بشكر الله. وسياق آية النحل في الكلام على النعم، وقد ضرب قبلها مثل القرية التي كفرت بأنعم الله، فناسب الأمر بشكر النعمة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص27.","url":""}]},{"id":"s16-259","number":259,"surah":16,"verses":[128],"references":[{"surah":16,"verses":[128]}],"verseLabel":"النحل: 128","question":"ما سر قوله: ﴿إِنَّ اللَّهَ مَعَ الَّذِينَ اتَّقَوا وَالَّذِينَ هُم مُّحْسِنُونَ﴾ بمؤكد واحد، وبالفعل في التقوى والاسم في الإحسان؟","answer":"أكّد في العنكبوت: ﴿وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ﴾ بإنّ واللام لأن السياق في الجهاد فاقتضى توكيد المعية، وسياق النحل في الصبر والمعاقبة بالمثل فاكتفى بمؤكد واحد. وجاء بالتقوى فعلًا لأن من عاقب بالمثل ولم يزد فقد اتقى، ومن زاد على ذلك فليس بمتقٍ، ثم عبّر عن الإحسان بالاسم: ﴿وَالَّذِينَ هُم مُّحْسِنُونَ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص83.","url":""}]},{"id":"s17-1","number":1,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر افتتاح السورة بـ﴿سُبْحَانَ﴾ قبل خبر الإسراء؟","answer":"لتهيئة السامع لخبر عجيب يدل على عظيم القدرة، وتنزيه الله عن العجز عن هذا الحدث الخارق للعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص748، 749، تحت «براعة الاستهلال بذكر التسبيح»","url":""}]},{"id":"s17-2","number":2,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿أَسْرَى بِعَبْدِهِ﴾ لا «سرى بعبده»؟","answer":"من التوجيهات التي يذكرها المصدر أن «أسرى» متعدٍّ، أي أسرى البراقَ بعبده؛ وفي ذلك إيماء إلى عناية الله برسوله. ويذكر أيضًا قول من يجعل «أسرى» و«سرى» بمعنى واحد، فلا ينحصر الفرق في التعدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص750، 751، تحت «سر التعبير بفعل «أسرى»»","url":""}]},{"id":"s17-3","number":3,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿بِعَبْدِهِ﴾ لا «برسوله»؟","answer":"لأن العبودية أعلى مقامات القرب والرفعة، وفي وصفه بها تشريف له مع سد باب الغلو فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص751، تحت «فائدة التعبير بعنوان العبودية دون الرسالة أو النبوة»","url":""}]},{"id":"s17-4","number":4,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر ذكر ﴿لَيْلًا﴾ مع أن الإسراء لا يكون إلا ليلًا؟","answer":"من أغراض ذكره تأكيد وقوع الإسراء ليلًا، ومن دلالة تنكيره أن الرحلة العظيمة وقعت في بعض ليلة، فيظهر ما فيها من خرق للعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص752، تحت «سر التقييد بالظرف «ليلًا»؛ غرض تنكير «ليلًا»»","url":""}]},{"id":"s17-5","number":5,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما دلالة وصف المسجد بـ﴿الْأَقْصَى﴾؟","answer":"هو وصف تفضيل يبين شدة بعده عن المسجد الحرام، فيبرز طول المسافة التي قطعت في بعض ليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص756، 757، تحت «دلالة التعبير بـ«الأقصى»؛ نكتة ذكر مبدأ الإسراء ونهايته»","url":""}]},{"id":"s17-6","number":6,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر التعبير بـ﴿بَارَكْنَا حَوْلَهُ﴾ لا «باركنا فيه»؟","answer":"ليعم الخير المسجد وما حوله؛ فإذا ثبتت البركة لما أحاط به كان ثبوتها فيه من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص759، تحت «بلاغة الكناية والمجاز المرسل»","url":""}]},{"id":"s17-7","number":7,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما دلالة ﴿مِنْ﴾ في قوله تعالى: ﴿لِنُرِيَهُ مِنْ آيَاتِنَا﴾؟","answer":"هي للتبعيض؛ فما أُريه النبي ﷺ بعض آيات الله، وفي ذلك إشارة إلى كثرة آيات قدرته وعظمتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص761، تحت «معنى الحرف «من» ودلالته»","url":""}]},{"id":"s17-8","number":8,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما مناسبة ختام آية الإسراء بقوله تعالى: ﴿إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾؟","answer":"على عود الضمير إلى الله، يبين الختام إحاطته بأقوال عبده وأحواله وعنايته به، ويتضمن وعيدًا للمكذبين. ويذكر المصدر احتمال عود الضمير إلى النبي ﷺ؛ فيكون تقريرًا لتحقق سماعه وإبصاره للآيات وردًّا على من يكذبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص762، تحت «بلاغة التوكيد والتعليل في جملة التذييل»","url":""}]},{"id":"s17-9","number":9,"surah":17,"verses":[2],"references":[{"surah":17,"verses":[2]}],"verseLabel":"الإسراء: 2","question":"ما سر التعبير في قوله تعالى: ﴿آتَيْنَا مُوسَى الْكِتَابَ﴾ بالإيتاء لا الإعطاء؟","answer":"الإيتاء إيصال للمقصود مطلقًا، بخلاف الإعطاء الذي يغلب اتصاله بالعطية والمناولة؛ فناسب إنزال الكتاب وإيصاله إلى موسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص768، تحت «دلالة التعبير بالإيتاء دون الإعطاء»","url":""}]},{"id":"s17-10","number":10,"surah":17,"verses":[2],"references":[{"surah":17,"verses":[2]}],"verseLabel":"الإسراء: 2","question":"ما سر التعبير بـ﴿بَنِي إِسْرَائِيلَ﴾ لا «اليهود»؟","answer":"للتذكير بأصلهم ونسبتهم إلى نبي كريم، وبما يقتضيه ذلك من اتباع الهدى والوفاء بالميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص771، تحت «سر التعبير ببني إسرائيل دون اليهود»","url":""}]},{"id":"s17-11","number":11,"surah":17,"verses":[2],"references":[{"surah":17,"verses":[2]}],"verseLabel":"الإسراء: 2","question":"ما مناسبة قوله تعالى: ﴿أَلَّا تَتَّخِذُوا مِنْ دُونِي وَكِيلًا﴾ بعد ذكر الكتاب؟","answer":"لأن الكتاب هدى إلى إفراد الله بالاعتماد والعبادة، فلا يُتخذ من دونه من يفوض إليه الأمر استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص771، 773، تحت «توجيه القراءات القرآنية في «ألا تتخذوا»؛ سر التعبير بلفظ «وكيلًا»»","url":""}]},{"id":"s17-12","number":12,"surah":17,"verses":[3],"references":[{"surah":17,"verses":[3]}],"verseLabel":"الإسراء: 3","question":"ما دلالة تذكير بني إسرائيل بأنهم ﴿ذُرِّيَّةَ مَنْ حَمَلْنَا مَعَ نُوحٍ﴾؟","answer":"تذكير لهم بنجاة أصولهم مع نوح وبالنعمة عليهم، وحث لهم على الاقتداء بشكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص777، 778، 780، تحت «دلالة النصب في «ذرية»؛ بلاغة فن الإدماج في براعة التعبير؛ توجيه تخصيص صفة الشكور بالذكر»","url":""}]},{"id":"s17-13","number":13,"surah":17,"verses":[3],"references":[{"surah":17,"verses":[3]}],"verseLabel":"الإسراء: 3","question":"ما سر وصف نوح عليه السلام بأنه ﴿عَبْدًا﴾؟","answer":"للتنويه بكمال إخلاصه وخضوعه لله؛ فالعبودية مقام غاية التذلل لمن له غاية الإفضال والإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص780، تحت «دلالة وصف نوح بالعبودية دون الرسالة أو النبوة»","url":""}]},{"id":"s17-14","number":14,"surah":17,"verses":[3],"references":[{"surah":17,"verses":[3]}],"verseLabel":"الإسراء: 3","question":"ما دلالة وصف نوح عليه السلام بـ﴿شَكُورًا﴾ بصيغة «فعول»؟","answer":"تدل صيغة المبالغة على كثرة شكره حتى صار الشكر وصفًا معروفًا ملازمًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص781، تحت «سر اختيار صيغة فعول «شكورًا»»","url":""}]},{"id":"s17-15","number":15,"surah":17,"verses":[4],"references":[{"surah":17,"verses":[4]}],"verseLabel":"الإسراء: 4","question":"ما سر تعدية ﴿قَضَيْنَا﴾ بـ﴿إِلَى﴾ في قوله تعالى: ﴿وَقَضَيْنَا إِلَى بَنِي إِسْرَائِيلَ﴾؟","answer":"ضُمّن القضاء معنى الإيحاء والإبلاغ، فجمع حتم الأمر وإيصاله إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص785، تحت «دلالة تعدية قضى بـ«إلى»»","url":""}]},{"id":"s17-16","number":16,"surah":17,"verses":[4],"references":[{"surah":17,"verses":[4]}],"verseLabel":"الإسراء: 4","question":"ما دلالة توكيد الفعلين في قوله تعالى: ﴿لَتُفْسِدُنَّ﴾ و﴿لَتَعْلُنَّ﴾؟","answer":"اللام جواب لقسم مقدر، وجاءت نون التوكيد الثقيلة لتقرير تحقق الإفساد والعلو المخبَر بهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص787، 789، تحت «نوع اللام في «لتفسدن»؛ دلالة التأكيد في «لتفسدن» مع صيغة المضارع؛ معنى الواو ودلالتها»","url":""}]},{"id":"s17-17","number":17,"surah":17,"verses":[4],"references":[{"surah":17,"verses":[4]}],"verseLabel":"الإسراء: 4","question":"ما دلالة وصف العلو بقوله تعالى: ﴿عُلُوًّا كَبِيرًا﴾؟","answer":"يفخم ما يبلغونه من الاستكبار والتسلط، ويصور اتساع أثره وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص790، تحت «سر وصف العلو بالكبير دون العظيم والكثير»","url":""}]},{"id":"s17-18","number":18,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما دلالة التعبير بالمجيء في قوله تعالى: ﴿جاء وعد أولاهما﴾؟","answer":"يقرر المجيء تحقق الوعد وحصوله عند حلول وقته، فلا يتخلف العقاب الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص794، تحت «دلالة التعبير بالمجيء دون الإتيان»","url":""}]},{"id":"s17-194","number":194,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما بلاغة المجاز في قوله تعالى: ﴿جاء وعد أولاهما﴾؟","answer":"المقصود مجيء وقت الوعد أو العقاب، فحذف المضاف وأقيم الوعد مقامه إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص795، تحت «بلاغة المجاز بحذف المضاف»","url":""}]},{"id":"s17-19","number":19,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما دلالة وصف العباد بقوله تعالى: ﴿أُولِي بَأْسٍ شَدِيدٍ﴾؟","answer":"البأس قوة يظهر أثرها في الحرب والبطش، ووصفه بالشديد يصور قوة العقوبة المسلطة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص798، 799، تحت «سر التعبير بقوله «أولي»؛ دلالة التعبير بالبأس دون القوة»","url":""}]},{"id":"s17-20","number":20,"surah":17,"verses":[5],"references":[{"surah":17,"verses":[5]}],"verseLabel":"الإسراء: 5","question":"ما دلالة التعبير بالفعل «جاسوا» ماضيًا، وما دلالة التعبير بكلمة «خلال»، وما النكتة البلاغية في التعبير بالديار دون البلاد أو البيوت؟","answer":"الجوس تتبع وتخلل باستقصاء، و﴿خلال الديار﴾ يصور دخولهم بين المساكن وانتشارهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص799، 800، تحت «دلالة التعبير بالفعل «جاسوا» ماضيًا؛ دلالة التعبير بكلمة «خلال»؛ نكتة التعبير بالديار دون البلاد أو البيوت»","url":""}]},{"id":"s17-21","number":21,"surah":17,"verses":[6],"references":[{"surah":17,"verses":[6]}],"verseLabel":"الإسراء: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿رَدَدْنَا لَكُمُ الْكَرَّةَ عَلَيْهِمْ﴾ لا «الغلبة»؟","answer":"الكرة تتضمن الرجوع وتكرر الغلبة، فتُصوّر عودة القوة بعد الانكسار، وتتابع النصر؛ فهي أبلغ هنا من مجرد ذكر غلبة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص14، تحت «دلالة التعبير بالكرة دون الغلبة»","url":""}]},{"id":"s17-22","number":22,"surah":17,"verses":[6],"references":[{"surah":17,"verses":[6]}],"verseLabel":"الإسراء: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿وَأَمْدَدْنَاكُمْ بِأَمْوَالٍ وَبَنِينَ﴾؟","answer":"الإمداد زيادة متتابعة، وذكر البنين لأنهم موضع القوة والنصرة في ذلك السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص15، 16، تحت «دلالة التعبير بـ«أمددناكم»؛ دلالة التعبير بالبنين دون الأولاد»","url":""}]},{"id":"s17-23","number":23,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما الفرق بين الإحسان الأول والثاني في قوله: ﴿إن أحسنتم أحسنتم لأنفسكم﴾؟","answer":"الإحسان الأول فعل الطاعات، والثاني جزاؤها وثمرتها العائدة إلى أصحابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص23، تحت «الفرق بين الإحسان الأول والآخر»","url":""}]},{"id":"s17-195","number":195,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما دلالة اللام في قوله تعالى: ﴿أحسنتم لأنفسكم﴾؟","answer":"تبين اللام رجوع منفعة الإحسان إلى صاحبه، كما تعود إليه عاقبة الإساءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص23، تحت «معنى اللام ودلالتها»","url":""}]},{"id":"s17-24","number":24,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير في الإساءة ﴿فَلَهَا﴾ ولم يقل «فلأنفسكم»؟","answer":"عاد الضمير إلى الأنفس المذكورة، فحصل الإيجاز من غير لبس. ومن لطائف المقابلة التصريح بذكر الأنفس في مقام الإحسان والتنويه، والاكتفاء بضميرها في مقام الإساءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص26، تحت «سر التعبير بالإضمار دون الإظهار»","url":""}]},{"id":"s17-25","number":25,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿وَعْدُ الْآخِرَةِ﴾ لا «الثانية»؟","answer":"لأن «الآخرة» تقابل الأولى وتوحي بأنها نهاية الكرتين وعاقبتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص28، تحت «نكتة التعبير بالآخرة دون الثانية في مقابلة الأولى»","url":""}]},{"id":"s17-26","number":26,"surah":17,"verses":[7],"references":[{"surah":17,"verses":[7]}],"verseLabel":"الإسراء: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿لِيَسُوءُوا وُجُوهَكُمْ﴾؟","answer":"جعلت الإساءة واقعة على الوجوه لأنها أظهر موضع للعزة والسرور، فيظهر عليها الذل والحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص30، تحت «توجيه تخصيص الوجوه بالمساءة بالذكر»","url":""}]},{"id":"s17-27","number":27,"surah":17,"verses":[8],"references":[{"surah":17,"verses":[8]}],"verseLabel":"الإسراء: 8","question":"ما مناسبة قوله تعالى: ﴿عسى ربكم أن يرحمكم﴾ لما قبله؟","answer":"بعد ذكر العقوبة فتح لهم باب الرجاء في رحمة الله إن رجعوا إلى الطاعة، فلا يقنطوا من الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص35، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s17-196","number":196,"surah":17,"verses":[8],"references":[{"surah":17,"verses":[8]}],"verseLabel":"الإسراء: 8","question":"ما سرّ التعبير باسم الرب في قوله: ﴿عسى ربكم أن يرحمكم﴾؟","answer":"يذكرهم اسم الرب بعناية الله وتربيته وإحسانه، فيقوي الرجاء في رحمته بعد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص37، تحت «سر التعبير باسم الله الرب»","url":""}]},{"id":"s17-28","number":28,"surah":17,"verses":[8],"references":[{"surah":17,"verses":[8]}],"verseLabel":"الإسراء: 8","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ عُدْتُمْ عُدْنَا﴾ بهذه المقابلة القصيرة؟","answer":"قابل عودهم إلى الإفساد بعودة العقاب؛ فالجملة تجمع الترهيب مع الرجاء السابق في رحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص38، 39، تحت «دلالة الواو في «وإن»؛ دلالة حذف متعلق العود»","url":""}]},{"id":"s17-29","number":29,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما سرّ التعبير بقوله تعالى: ﴿يَهْدِي لِلَّتِي هِيَ أَقْوَمُ﴾ ولم يذكر الموصوف؟","answer":"ليعم الطريقة والملة والحال والخصلة التي هي أشد استقامة في كل شأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص48، تحت «بلاغة حذف الموصوف في «للتي هي أقوم»»","url":""}]},{"id":"s17-30","number":30,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما دلالة صيغة التفضيل ﴿أقوم﴾ في وصف هداية القرآن؟","answer":"تدل على أن القرآن يهدي إلى الطريق الأعدل والأشد استقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص48، تحت «دلالة التعبير بأفعل التفضيل»","url":""}]},{"id":"s17-197","number":197,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما دلالة حذف المفضّل عليه في قوله تعالى: ﴿للتي هي أقوم﴾؟","answer":"يوسع الحذف التفضيل، فهداية القرآن أقوم من كل طريق يخالفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص49، تحت «دلالة حذف المفضل عليه»","url":""}]},{"id":"s17-31","number":31,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما دلالة الجمع بين هداية القرآن وبشارته للمؤمنين؟","answer":"عطف البشارة يبيّن مزية أخرى للقرآن مع هدايته: فهو يسرّ المؤمنين بوعد الأجر، ويقوّي رجاءهم ويواسيهم فيما يلقونه من أذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص49، 50، تحت «دلالة الواو في «ويبشر»؛ سر التعبير بالبشارة في «ويبشر»»","url":""}]},{"id":"s17-32","number":32,"surah":17,"verses":[10],"references":[{"surah":17,"verses":[10]}],"verseLabel":"الإسراء: 10","question":"ما سر تخصيص عدم الإيمان بـ﴿الْآخِرَةِ﴾ في هذا الوعيد؟","answer":"من وجوه تخصيصه أن إنكار الآخرة سبب للتمادي في الكفر والإجرام، وأن ذكرها يناسب ما في السياق من وعد بالأجر ووعيد بالعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص58، 59، تحت «سر التنصيص على عدم الإيمان باليوم الآخر»","url":""}]},{"id":"s17-33","number":33,"surah":17,"verses":[11],"references":[{"surah":17,"verses":[11]}],"verseLabel":"الإسراء: 11","question":"ما سرّ التعبير بقوله تعالى: ﴿وَيَدْعُ الْإِنْسَانُ بِالشَّرِّ دُعَاءَهُ بِالْخَيْرِ﴾؟","answer":"يصور حال الإنسان حين يعجل ولا يتأمل العواقب، فيدعو على نفسه أو أهله بالشر عند الضجر كما يدعو بالخير؛ وفي ذلك تنبيه إلى التثبت فيما يطلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص64، 65، تحت «دلالة التعبير بالمضارع «ويدع»؛ دلالة اللام في «الإنسان»»","url":""}]},{"id":"s17-34","number":34,"surah":17,"verses":[11],"references":[{"surah":17,"verses":[11]}],"verseLabel":"الإسراء: 11","question":"ما سر وصف الإنسان بـ﴿عَجُولًا﴾ لا «سريعًا»؟","answer":"العجلة طلب الشيء قبل أوانه من غير روية، أما السرعة فقد تكون محمودة بعد التثبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص67، تحت «سر اختيار وصف عجولًا»","url":""}]},{"id":"s17-35","number":35,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بقوله تعالى: ﴿فَمَحَوْنَا آيَةَ اللَّيْلِ﴾ لا «أزلناها»؟","answer":"المحو يركّز على ذهاب الأثر أو الوصف، بخلاف الإزالة التي أصلها تنحية الشيء عن مكانه. ومن توجيهاته في الآية ذهاب أثر الضوء وإظلام الليل، فيناسب مقابلة آية الليل بآية النهار المبصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص76، تحت «سر التعبير بالمحو دون الإزالة»","url":""}]},{"id":"s17-36","number":36,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بلفظ ﴿الابتغاء﴾؟","answer":"الابتغاء طلب شديد يجمع السعي والاهتمام بتحصيل المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص79، تحت «سر التعبير بلفظ الابتغاء»","url":""}]},{"id":"s17-198","number":198,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما دلالة تنكير ﴿فضلًا﴾ في قوله: ﴿لتبتغوا فضلًا من ربكم﴾؟","answer":"يعظم التنكير ما ييسره الله من الرزق وينبه إلى سعة وجوهه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص79، تحت «دلالة تنكير «فضلًا»»","url":""}]},{"id":"s17-37","number":37,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سر تعليل آية النهار دون التصريح بعلة آية الليل؟","answer":"اكتُفي بما يفهم من المقابلة: النهار للإبصار والابتغاء، والليل للسكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص79، تحت «بلاغة الاكتفاء في التعليل لآية النهار دون آية الليل»","url":""}]},{"id":"s17-38","number":38,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما سرّ التعبير بلفظ ﴿التفصيل﴾؟","answer":"التفصيل بيان تام للجزئيات والدقائق، فهو أخص من مطلق البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص81، تحت «سر التعبير بلفظ التفصيل»","url":""}]},{"id":"s17-199","number":199,"surah":17,"verses":[12],"references":[{"surah":17,"verses":[12]}],"verseLabel":"الإسراء: 12","question":"ما دلالة تأكيد الفعل بالمصدر في قوله: ﴿فصلناه تفصيلًا﴾؟","answer":"يقرر المصدر تمام الإيضاح وإحكامه واستيفاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص81، تحت «دلالة التعبير بالمصدر «تفصيلًا»»","url":""}]},{"id":"s17-39","number":39,"surah":17,"verses":[13],"references":[{"surah":17,"verses":[13]}],"verseLabel":"الإسراء: 13","question":"ما سرّ التعبير بالطائر عن عمل الإنسان؟","answer":"استعير الطائر للعمل والمصير الملازم لصاحبه؛ لأنهم كانوا يتفاءلون ويتشاءمون بالطير.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص87، تحت «سر التعبير بالطائر عن العمل»","url":""}]},{"id":"s17-200","number":200,"surah":17,"verses":[13],"references":[{"surah":17,"verses":[13]}],"verseLabel":"الإسراء: 13","question":"ما بلاغة الكناية في قوله تعالى: ﴿في عنقه﴾؟","answer":"العنق كناية عما لا يفارق صاحبه، فلا مهرب للإنسان من مسؤولية اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص88، تحت «بلاغة الكناية في التعبير بالعنق»","url":""}]},{"id":"s17-40","number":40,"surah":17,"verses":[13],"references":[{"surah":17,"verses":[13]}],"verseLabel":"الإسراء: 13","question":"ما سرّ التعبير بقوله تعالى: ﴿فِي عُنُقِهِ﴾ لا «على عنقه»؟","answer":"«في» أشد في تصوير اللزوم والتداخل، كأن العمل مطوق ثابت لا موضوع يمكن نزعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص87، تحت «دلالة التعبير بالحرف «في»»","url":""}]},{"id":"s17-41","number":41,"surah":17,"verses":[14],"references":[{"surah":17,"verses":[14]}],"verseLabel":"الإسراء: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿اقْرَأْ كِتَابَكَ﴾ لا «اتل كتابك»؟","answer":"القراءة أعم من التلاوة، والمراد هنا معرفة ما أُثبت في صحيفة الأعمال والإقرار به؛ أما التلاوة ففي أصلها معنى الاتباع، وليس المقام مقام اتباع ما في الصحيفة والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص95، تحت «سر التعبير بلفظ القراءة دون التلاوة»","url":""}]},{"id":"s17-42","number":42,"surah":17,"verses":[14],"references":[{"surah":17,"verses":[14]}],"verseLabel":"الإسراء: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿كَفَى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ حَسِيبًا﴾؟","answer":"لأن السجل يبلغ من الوضوح أن صاحبه يحاسب نفسه بنفسه ولا يحتاج إلى شاهد أبلغ منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص96، 97، تحت «معنى الباء في «بنفسك»؛ سر اختيار التعبير بـ«حسيبًا»»","url":""}]},{"id":"s17-43","number":43,"surah":17,"verses":[15],"references":[{"surah":17,"verses":[15]}],"verseLabel":"الإسراء: 15","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى﴾؟","answer":"صوّر الذنب حملًا ثقيلًا، وقرر عدل المسؤولية الفردية فلا تنقل تبعة نفس إلى غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص105، 106، تحت «بلاغة العطف في «ولا تزر وازرة وزر أخرى»؛ سر التعبير عن الإثم بالوزر»","url":""}]},{"id":"s17-44","number":44,"surah":17,"verses":[15],"references":[{"surah":17,"verses":[15]}],"verseLabel":"الإسراء: 15","question":"ما سر التصريح بنفي التعذيب قبل بعثة الرسول دون ذكر الإثابة؟","answer":"لأن المقام مقام إقامة الحجة وقطع أعذار المكذبين، فناسب التصريح بنفي تعذيبهم قبل بعثة الرسول، وليس السياق سياق وعد بالإثابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص107، تحت «بلاغة الاكتفاء في التصريح بالتعذيب دون الإثابة»","url":""}]},{"id":"s17-45","number":45,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما سرّ التعبير بقوله تعالى: ﴿إِذَا أَرَدْنَا أَنْ نُهْلِكَ قَرْيَةً﴾ بـ«إذا»؟","answer":"«إذا» تدل في أصلها على تحقق ما تدخل عليه؛ فجاءت هنا لتأكيد الوعيد وتحقيقه عند وقوع موجباته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص114، تحت «دلالة التعبير بـ«إذا»»","url":""}]},{"id":"s17-46","number":46,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما سر تخصيص ﴿مُتْرَفِيهَا﴾ بالذكر؟","answer":"لأنهم أسرع إلى الفجور وأقدر على أسبابه، ولأنهم قادة يتبعهم غيرهم؛ فذكرهم يبرز أثر فساد القيادة في شيوع الفسق. وليس في ذلك أن من لم يفسق يحمل ذنب غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص117، تحت «سر تخصيص المترفين دون غيرهم»","url":""}]},{"id":"s17-47","number":47,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما سرّ التعبير بقوله تعالى: ﴿فَفَسَقُوا فِيهَا﴾ لا «عليها»؟","answer":"«في» تصور تغلغل الفسق في كيان القرية وانتشاره داخلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص118، 119، تحت «سر التعبير بالظرفية في «فيها»»","url":""}]},{"id":"s17-48","number":48,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"لماذا عبّر بالتدمير دون الإهلاك؟","answer":"التدمير أبلغ في استئصال البنية وآثار العمران من مجرد الإهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص120، تحت «سر التعبير بالتدمير دون الإهلاك»","url":""}]},{"id":"s17-201","number":201,"surah":17,"verses":[16],"references":[{"surah":17,"verses":[16]}],"verseLabel":"الإسراء: 16","question":"ما دلالة المصدر في قوله تعالى: ﴿فدمرناها تدميرًا﴾؟","answer":"يؤكد المصدر تمام التدمير وشموله وقوة وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص120، تحت «دلالة التعبير بالمصدر «تدميرًا»»","url":""}]},{"id":"s17-49","number":49,"surah":17,"verses":[18],"references":[{"surah":17,"verses":[18]}],"verseLabel":"الإسراء: 18","question":"ما سر تسمية الدنيا ﴿الْعَاجِلَةَ﴾ في هذا السياق؟","answer":"ليفضح قصر نظر طالبها: اختار ما يعجل وينفد وترك ما يبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص133، 134، تحت «سر اصطفاء التعبير بـ«العاجلة»»","url":""}]},{"id":"s17-50","number":50,"surah":17,"verses":[18],"references":[{"surah":17,"verses":[18]}],"verseLabel":"الإسراء: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿عَجَّلْنَا لَهُ فِيهَا مَا نَشَاءُ لِمَنْ نُرِيدُ﴾؟","answer":"قُيّد العطاء من جهتين: مقداره بما يشاؤه الله، ومن يناله بمن يريده؛ فلا يحصل كل طالب للدنيا على مطلوبه، ولا يحصل من أُعطي على كل ما أراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص135، تحت «فائدة تقييد فعل التعجيل باسمين موصولين»","url":""}]},{"id":"s17-51","number":51,"surah":17,"verses":[18],"references":[{"surah":17,"verses":[18]}],"verseLabel":"الإسراء: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿ثُمَّ جَعَلْنَا لَهُ جَهَنَّمَ﴾؟","answer":"تفيد «ثم» ترتيب العاقبة وتراخيها بعد ما يعجّل لطالب الدنيا من متاع؛ فينتقل السياق من العطاء في العاجلة إلى المصير الذي ينتظره.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص137، تحت «دلالة استعمال حرف التراخي «ثم»»","url":""}]},{"id":"s17-52","number":52,"surah":17,"verses":[19],"references":[{"surah":17,"verses":[19]}],"verseLabel":"الإسراء: 19","question":"ما سرّ التعبير بقوله تعالى: ﴿وَسَعَى لَهَا سَعْيَهَا﴾؟","answer":"الإضافة تفيد السعي اللائق بالآخرة قدرًا ونوعًا، لا أي حركة يدعيها صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص146، تحت «براعة إضافة السعي إلى ضمير الآخرة»","url":""}]},{"id":"s17-53","number":53,"surah":17,"verses":[19],"references":[{"surah":17,"verses":[19]}],"verseLabel":"الإسراء: 19","question":"ما سر تقييد السعي للآخرة بقوله تعالى: ﴿وَهُوَ مُؤْمِنٌ﴾؟","answer":"لأن العمل لا يثمر ثواب الآخرة بلا أصل يوجهه إلى الله ويصدق بوعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص147، تحت «فائدة التقييد بجملة الحال»","url":""}]},{"id":"s17-54","number":54,"surah":17,"verses":[20],"references":[{"surah":17,"verses":[20]}],"verseLabel":"الإسراء: 20","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلًّا نُمِدُّ هَؤُلَاءِ وَهَؤُلَاءِ﴾؟","answer":"قدّم «كلا» لإفادة العموم: عطاء الربوبية يصل إلى طالب الدنيا وطالب الآخرة في دار الابتلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص151، تحت «غرض تقديم المفعول»","url":""}]},{"id":"s17-55","number":55,"surah":17,"verses":[20],"references":[{"surah":17,"verses":[20]}],"verseLabel":"الإسراء: 20","question":"ما غرض إضافة العطاء إلى الرب في قوله: ﴿عطاء ربك﴾؟","answer":"تشعر الإضافة بسعة عطاء الرب وتدبيره وإنعامه على الخلق بحسب حكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص155، تحت «غرض إضافة العطاء إلى لفظ الربوبية»","url":""}]},{"id":"s17-202","number":202,"surah":17,"verses":[20],"references":[{"surah":17,"verses":[20]}],"verseLabel":"الإسراء: 20","question":"ما دلالة التعبير بالكون المنفي في قوله تعالى: ﴿وما كان عطاء ربك محظورًا﴾؟","answer":"ينفي أن يكون عطاء الرب الدنيوي محبوسًا عن الخلق؛ فيصيب المؤمن والكافر بحسب المشيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص156، تحت «دلالة التعبير بالكون المنفي»","url":""}]},{"id":"s17-56","number":56,"surah":17,"verses":[21],"references":[{"surah":17,"verses":[21]}],"verseLabel":"الإسراء: 21","question":"ما سرّ التعبير بقوله تعالى: ﴿انْظُرْ كَيْفَ فَضَّلْنَا بَعْضَهُمْ عَلَى بَعْضٍ﴾؟","answer":"وجّه إلى تفاوت الدنيا المشاهد ليقاس عليه تفاوت الآخرة الأعظم والأبقى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص160، تحت «غرض الأمر بالنظر»","url":""}]},{"id":"s17-57","number":57,"surah":17,"verses":[22],"references":[{"surah":17,"verses":[22]}],"verseLabel":"الإسراء: 22","question":"ما سرّ تقديم ﴿مَعَ اللَّهِ﴾ في النهي عن الشرك؟","answer":"لتشنيع مجرد الجمع بين الله وغيره في العبادة، قبل النظر في ماهية الشريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص166، تحت «غرض تقديم قوله «مع الله»»","url":""}]},{"id":"s17-58","number":58,"surah":17,"verses":[22],"references":[{"surah":17,"verses":[22]}],"verseLabel":"الإسراء: 22","question":"ما دلالة الجمع بين ﴿مَذْمُومًا مَخْذُولًا﴾ في عاقبة الشرك؟","answer":"يستحق المشرك الذم إذ يشرك بخالقه المنعم عليه، ويقع في الخذلان لأنه يتخذ إلهًا لا يملك له نصرًا ولا نفعًا؛ فجُمعت خسارته في الرأي والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص168، تحت «توجيه تخصيص الذم والخذلان بالذكر»","url":""}]},{"id":"s17-59","number":59,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿وَقَضَى رَبُّكَ﴾؟","answer":"القضاء يدل على الأمر المحكم الذي لا يقبل التردد، و«ربك» تلطف يربط التكليف بالتربية والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص173، 174، تحت «دلالة اختيار لفظة «قضى»؛ مناسبة اختيار الربوبية دون الألوهية»","url":""}]},{"id":"s17-60","number":60,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سر عطف الإحسان إلى الوالدين على الأمر بتوحيد الله؟","answer":"لأنهما السبب الظاهر في الوجود والتربية بعد فضل الخالق، فجاء شكرهما عقب توحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص176، تحت «مناسبة عطف بر الوالدين على توحيد الله»","url":""}]},{"id":"s17-61","number":61,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"لماذا خُصّت حالة الكبر في الوصية بالوالدين؟","answer":"لأن الكبر زمن اشتداد حاجتهما وضعفهما، فيلزم الولد مزيد الرعاية والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص178، تحت «توجيه تخصيص حالة الكبر بالذكر»","url":""}]},{"id":"s17-203","number":203,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما غرض تقديم ﴿عندك﴾ في قوله: ﴿إما يبلغن عندك الكبر﴾؟","answer":"يجعل رعايتهما مسؤولية حاضرة في بيت الولد وتحت عنايته المباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص180، تحت «غرض تقديم الظرف»","url":""}]},{"id":"s17-62","number":62,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سر البدء بالنهي عن كلمة ﴿أُفٍّ﴾ في الوصية بالوالدين؟","answer":"نهى عن أدنى صوت تضجر ليكون ما فوقه من الإيذاء أولى بالتحريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص183، تحت «غرض النهي عن التأفف»","url":""}]},{"id":"s17-63","number":63,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سرّ التعبير بقوله تعالى: ﴿قَوْلًا كَرِيمًا﴾؟","answer":"لم يطلب ترك الأذى فقط، بل كلامًا يكرم الوالدين ويشعرهما بالمكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص185، تحت «دلالة التعبير بالمفعول المطلق، وتقييده بالصفة»","url":""}]},{"id":"s17-64","number":64,"surah":17,"verses":[24],"references":[{"surah":17,"verses":[24]}],"verseLabel":"الإسراء: 24","question":"ما بلاغة الاستعارة في قوله: ﴿واخفض لهما جناح الذل﴾؟","answer":"شبه لين الجانب والحماية بخفض الطائر جناحه لمن يضمه ويرعاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص189، تحت «بلاغة الاستعارة المكنية التمثيلية»","url":""}]},{"id":"s17-204","number":204,"surah":17,"verses":[24],"references":[{"surah":17,"verses":[24]}],"verseLabel":"الإسراء: 24","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من الرحمة﴾؟","answer":"تبين أن هذا التواضع للوالدين ناشئ من الرحمة والمحبة، لا من المهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص191، تحت «معنى حرف «من» ودلالته»","url":""}]},{"id":"s17-65","number":65,"surah":17,"verses":[24],"references":[{"surah":17,"verses":[24]}],"verseLabel":"الإسراء: 24","question":"ما سر الدعاء للوالدين بـ﴿رَبِّ ارْحَمْهُمَا﴾؟","answer":"اسم الرب يستحضر التربية التي تلقاها منهما، فيسأل ربه أن يجازيهما برحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص193، تحت «سر اصطفاء لفظ الربوبية»","url":""}]},{"id":"s17-66","number":66,"surah":17,"verses":[25],"references":[{"surah":17,"verses":[25]}],"verseLabel":"الإسراء: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿رَبُّكُمْ أَعْلَمُ بِمَا فِي نُفُوسِكُمْ﴾ لا «بنفوسكم»؟","answer":"«في» تتناول ما يستقر ويجول داخل النفس من قصد خفي لا يطلع عليه الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص199، تحت «نكتة إيثار حرف الظرفية دون الباء»","url":""}]},{"id":"s17-67","number":67,"surah":17,"verses":[25],"references":[{"surah":17,"verses":[25]}],"verseLabel":"الإسراء: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿لِلْأَوَّابِينَ غَفُورًا﴾؟","answer":"لأن البر قد تقع فيه هفوة، ففتح المغفرة لمن يكثر الرجوع إلى الله وإصلاح التقصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص201، تحت «نكتة المبالغة في استعمال صيغة «فعّال»»","url":""}]},{"id":"s17-68","number":68,"surah":17,"verses":[26],"references":[{"surah":17,"verses":[26]}],"verseLabel":"الإسراء: 26","question":"ما دلالة ترتيب ذي القربى والمسكين وابن السبيل في الأمر بالإحسان؟","answer":"يضم الترتيب أصناف المستحقين بدءًا بالأقرب: ذي القرابة، ثم المسكين المحتاج، ثم ابن السبيل الذي بَعُد عن أهله وماله؛ فيبيّن مراتب العناية بأصحاب الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص205، تحت «نكتة ترتيب المذكورين بالإحسان إليهم»","url":""}]},{"id":"s17-69","number":69,"surah":17,"verses":[27],"references":[{"surah":17,"verses":[27]}],"verseLabel":"الإسراء: 27","question":"ما سر وصف المبذرين بأنهم ﴿إِخْوَانَ الشَّيَاطِينِ﴾؟","answer":"لأنهم شابهوهم في إفساد النعمة وصرفها في غير وجهها، فالأخوة أخوة طريقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص211، تحت «بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s17-70","number":70,"surah":17,"verses":[27],"references":[{"surah":17,"verses":[27]}],"verseLabel":"الإسراء: 27","question":"ما سرّ التعبير بقوله تعالى: ﴿وَكَانَ الشَّيْطَانُ لِرَبِّهِ كَفُورًا﴾؟","answer":"يربط التبذير بجذره الباطني: كفران النعمة وعدم وضعها فيما أراد المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص213، تحت «دلالة التعبير بصيغة المبالغة»","url":""}]},{"id":"s17-71","number":71,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما دلالة التعبير بـ﴿تُعْرِضَنَّ عَنْهُمُ﴾ في حال عدم القدرة على العطاء؟","answer":"من توجيهاته أنه مجاز عن عدم النفع لعدم القدرة على العطاء، لا عن صدّ المحتاج جفاءً. ويذكر المصدر أيضًا حمله على الإعراض حياءً حين لا يجد المعطي ما يعطيه؛ لذلك أُمر بالقول اللين الذي يجبر خاطر السائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص217، تحت «معنى الإعراض بين الحقيقة والمجاز»","url":""}]},{"id":"s17-72","number":72,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"لماذا عبّر عن الرزق بالرحمة في قوله: ﴿رحمة من ربك﴾؟","answer":"سمي الرزق رحمة ليظل المعطي راجيًا فضل الله لا مالكًا مستقلًا للعطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص220، تحت «دلالة التعبير عن الرزق بالرحمة مجازًا مرسلًا»","url":""}]},{"id":"s17-205","number":205,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما سرّ إضافة الرحمة إلى الرب في قوله: ﴿رحمة من ربك﴾؟","answer":"تستحضر الإضافة عناية الرب وتدبيره وإحسانه بالنبي وبالسائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص221، تحت «سر إضافة الرحمة إلى الرب»","url":""}]},{"id":"s17-73","number":73,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما سرّ التعبير بقوله تعالى: ﴿قَوْلًا مَيْسُورًا﴾ لا «معروفًا»؟","answer":"الميسور كلام سهل لطيف يخفف الحرج ويعد بالخير، فكأنه عطاء ميسر حين تعذر المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص226، تحت «علة وصف القول بالميسور دون المعروف»","url":""}]},{"id":"s17-74","number":74,"surah":17,"verses":[29],"references":[{"surah":17,"verses":[29]}],"verseLabel":"الإسراء: 29","question":"ما سر تصوير البخل بيد مغلولة إلى العنق؟","answer":"يجسد شدة الإمساك بصورة يد لا تستطيع الامتداد أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص235، 236، تحت «براعة انتقاء مفردة «مغلولة» دون مقبوضة؛ براعة الاستعارة التمثيلية لحال الشحيح»","url":""}]},{"id":"s17-75","number":75,"surah":17,"verses":[29],"references":[{"surah":17,"verses":[29]}],"verseLabel":"الإسراء: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَبْسُطْهَا كُلَّ الْبَسْطِ﴾؟","answer":"لم ينه عن البسط بل عن استغراقه، فدل على الاقتصاد بين البخل والإسراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص240، تحت «نكتة التقييد بـ«كل» النائب عن المفعول المطلق، مضافًا إلى المصدر»","url":""}]},{"id":"s17-76","number":76,"surah":17,"verses":[30],"references":[{"surah":17,"verses":[30]}],"verseLabel":"الإسراء: 30","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ... وَيَقْدِرُ﴾ بعد الأمر بالاعتدال؟","answer":"ليعلّم أن تفاوت الرزق بتدبير خبير، فلا يحمل الضيق على بخل ولا السعة على إسراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص249، تحت «بلاغة تذييل جمل الأوامر السابقة بهذه الآية»","url":""}]},{"id":"s17-77","number":77,"surah":17,"verses":[30],"references":[{"surah":17,"verses":[30]}],"verseLabel":"الإسراء: 30","question":"ما سرّ تقديم ﴿بِعِبَادِهِ﴾ في ﴿كَانَ بِعِبَادِهِ خَبِيرًا بَصِيرًا﴾؟","answer":"يفيد الاهتمام بالعباد والتشويق إلى الخبر عن إحاطة علم الله بهم؛ فبسط الرزق وتقديره يجريان على علم بأحوالهم وما يصلحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص253، تحت «سر تقديم شبه الجملة «بعباده» على الخبر»","url":""}]},{"id":"s17-78","number":78,"surah":17,"verses":[31],"references":[{"surah":17,"verses":[31]}],"verseLabel":"الإسراء: 31","question":"ما سرّ التعبير هنا بـ﴿خَشْيَةَ إِمْلَاقٍ﴾ وفي الأنعام ﴿مِنْ إِمْلَاقٍ﴾؟","answer":"هنا الفقر متوقع فقدم رزق الأولاد: ﴿نحن نرزقهم وإياكم﴾؛ وهناك الفقر واقع فقدم رزق الآباء: ﴿نحن نرزقكم وإياهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص261، 262، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s17-79","number":79,"surah":17,"verses":[31],"references":[{"surah":17,"verses":[31]}],"verseLabel":"الإسراء: 31","question":"ما دلالة وصف قتل الأولاد بأنه ﴿خِطْئًا كَبِيرًا﴾؟","answer":"«خِطئًا» في هذه القراءة إثم، ووصفه بالكبير يعظّم الجريمة وينفّر منها. وجاء التصريح بشدة قبحها لإبطال استحسانها في نفوس من اعتادها خوفًا من الفقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص264، 265، تحت «توجيه القراءات في قوله «خطئًا»؛ نكتة وصف «خطئًا» بـ«كبيرًا»»","url":""}]},{"id":"s17-80","number":80,"surah":17,"verses":[32],"references":[{"surah":17,"verses":[32]}],"verseLabel":"الإسراء: 32","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَقْرَبُوا الزِّنَا﴾ لا «ولا تزنوا»؟","answer":"ليحرم الفعل وكل الطرق والمقدمات التي تقرب إليه، فيسد الباب قبل الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص270، تحت «بلاغة إيثار «ولا تقربوا» في النهي عن الزنى دون ولا تزنوا»","url":""}]},{"id":"s17-81","number":81,"surah":17,"verses":[32],"references":[{"surah":17,"verses":[32]}],"verseLabel":"الإسراء: 32","question":"ما سرّ التعبير بقوله تعالى: ﴿إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا﴾؟","answer":"جمع قبح الفعل في ذاته وقبح الطريق الذي يفضي إليه من اختلاط الأنساب وفساد المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص272، 273، 274، تحت «سر التعبير بلفظ «فاحشة» دون غيره؛ دلالة كلمة «وساء» ووجه التعبير بها عن قبح الزنى؛ بلاغة الاستعارة في التعبير عن الطريق بالسبيل»","url":""}]},{"id":"s17-82","number":82,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿النَّفْسَ الَّتِي حَرَّمَ اللَّهُ﴾؟","answer":"أظهر اسم الجلالة ليعظم حرمة النفس؛ فالاعتداء عليها انتهاك لما حرمه الله نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص280، تحت «سر التعبير باسم الجلالة دون غيره»","url":""}]},{"id":"s17-83","number":83,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿فَقَدْ جَعَلْنَا لِوَلِيِّهِ سُلْطَانًا﴾؟","answer":"يجمع لفظ السلطان معنى الحجة والحق الذي أثبته الله لولي المقتول في القصاص أو الدية أو العفو. ويبين المصدر أن استيفاء القصاص يكون بإشراف ولي الأمر، فلا يعني السلطان إطلاق يد الولي في القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص286، 287، تحت «سر التعبير بالمصدر «سلطانًا»؛ بلاغة الإجمال في اختيار مفردة «سلطانًا»»","url":""}]},{"id":"s17-84","number":84,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما دلالة النهي عن الإسراف في القتل بعد إثبات الحق لولي المقتول؟","answer":"حتى لا يتحول إنصاف المظلوم إلى ظلم جديد بتجاوز القاتل إلى غيره أو التمثيل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص288، تحت «دلالة النهي عن الإسراف في القتل»","url":""}]},{"id":"s17-85","number":85,"surah":17,"verses":[34],"references":[{"surah":17,"verses":[34]}],"verseLabel":"الإسراء: 34","question":"ما سر التعبير بـ﴿وَلَا تَقْرَبُوا﴾ في شأن مال اليتيم؟","answer":"النهي عن القربان يبالغ في حماية مال اليتيم ويحذر من التصرف فيه بغير حق؛ والاستثناء ﴿إِلَّا بِالَّتِي هِيَ أَحْسَنُ﴾ يوجّه إلى حفظه واستثماره لمصلحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص295، 296، تحت «بلاغة التعبير بالنهي عن قربان مال اليتيم»","url":""}]},{"id":"s17-86","number":86,"surah":17,"verses":[34],"references":[{"surah":17,"verses":[34]}],"verseLabel":"الإسراء: 34","question":"ما سر حذف متعلق ﴿مَسْئُولًا﴾ في قوله تعالى: ﴿إِنَّ الْعَهْدَ كَانَ مَسْئُولًا﴾؟","answer":"حُذف متعلق السؤال اكتفاءً بدلالة الحال؛ فالسياق يبيّن أن السؤال عن الوفاء بالعهد أو نقضه، فلا حاجة إلى التصريح به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص304، تحت «سر حذف متعلق «مسؤولًا»»","url":""}]},{"id":"s17-87","number":87,"surah":17,"verses":[35],"references":[{"surah":17,"verses":[35]}],"verseLabel":"الإسراء: 35","question":"ما سرّ التعبير بقوله تعالى: ﴿وَزِنُوا بِالْقِسْطَاسِ الْمُسْتَقِيمِ﴾؟","answer":"القسطاس هو الميزان، ويحتمل معنى العدل؛ ووصفه بالمستقيم يؤكد ضرورة سلامة معيار الوزن والتحري فيه حتى يتحقق الإنصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص311، 312، تحت «دلالة الباء في «بالقسطاس»؛ علة الاكتفاء بوصف القسطاس بالمستقيم؛ بلاغة التصريح بالوصف مع اشتمال الموصوف عليه»","url":""}]},{"id":"s17-88","number":88,"surah":17,"verses":[35],"references":[{"surah":17,"verses":[35]}],"verseLabel":"الإسراء: 35","question":"ما سرّ التعبير بقوله تعالى: ﴿ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾؟","answer":"العدل خير في الحال، وأحسن عاقبةً ومرجعًا في الثقة والرزق والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص314، 315، تحت «دلالة مجيء «وأحسن تأويلًا» بعد «ذلك خير»؛ معنى التأويل ودلالة صيغة التفعيل»","url":""}]},{"id":"s17-89","number":89,"surah":17,"verses":[36],"references":[{"surah":17,"verses":[36]}],"verseLabel":"الإسراء: 36","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِ عِلْمٌ﴾؟","answer":"«تقف» تتبع الأثر؛ فالنهي يشمل اتباع الظن في القول والحكم والسلوك بلا علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص319، 320، 321، تحت «بلاغة المجاز المرسل في قوله «ولا تقف»؛ سر التعبير بـ«ما» دون غيرها؛ سر تنكير «علم»»","url":""}]},{"id":"s17-90","number":90,"surah":17,"verses":[36],"references":[{"surah":17,"verses":[36]}],"verseLabel":"الإسراء: 36","question":"ما سر تخصيص ﴿السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ﴾ بالذكر في المسؤولية؟","answer":"جمع منافذ المعرفة الظاهرة وباطن الفهم، ليحمّل الإنسان مسؤولية طريق العلم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص323، تحت «نكتة تخصيص هذه الأعضاء بالذكر»","url":""}]},{"id":"s17-91","number":91,"surah":17,"verses":[36],"references":[{"surah":17,"verses":[36]}],"verseLabel":"الإسراء: 36","question":"ما سرّ التعبير بقوله تعالى: ﴿الْفُؤَادَ﴾ لا «القلب»؟","answer":"الفؤاد يستحضر القلب في حال التوقد والإدراك، وهو الأنسب لمقام التثبت والشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص324، تحت «لطيف الإشارة بذكر الفؤاد دون القلب»","url":""}]},{"id":"s17-92","number":92,"surah":17,"verses":[37],"references":[{"surah":17,"verses":[37]},{"surah":31,"verses":[18]}],"verseLabel":"الإسراء: 37؛ لقمان: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا﴾ لا «فرحًا»؟","answer":"في الإسراء، المرح فرح يتجاوز إلى البطر والخيلاء، أما الفرح فقد يكون محمودًا. وفي لقمان أيضًا تصوّر مشية المرح التبختر والكبر، فيكون النهي عنها نهيًا عن التكبر بصوره؛ ويذكّر ذكر الأرض الإنسان بأصله وحدوده فيحمله على التواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص333، تحت «سر التعبير بالمرح دون الفرح»","url":""}]},{"id":"s17-93","number":93,"surah":17,"verses":[37],"references":[{"surah":17,"verses":[37]}],"verseLabel":"الإسراء: 37","question":"ما دلالة مواجهة المتكبر بقوله: ﴿لن تخرق الأرض﴾؟","answer":"تحطم العبارة وهمه؛ فلن يشق الأرض بقوة خطوه مهما تكبر وتبختر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص335، تحت «دلالة التعبير بالخرق»","url":""}]},{"id":"s17-206","number":206,"surah":17,"verses":[37],"references":[{"surah":17,"verses":[37]}],"verseLabel":"الإسراء: 37","question":"ما دلالة ذكر قوله «ولن تبلغ الجبال طولًا»؟","answer":"تضع كبره أمام ضخامة الجبال، فلن يبلغها طولًا مهما انتفخ وتعاظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص336، تحت «دلالة ذكر قوله «ولن تبلغ الجبال طولًا»»","url":""}]},{"id":"s17-94","number":94,"surah":17,"verses":[38],"references":[{"surah":17,"verses":[38]}],"verseLabel":"الإسراء: 38","question":"ما سر إفراد اسم الإشارة ﴿ذَلِكَ﴾ بعد تعدد الوصايا؟","answer":"جُمعت الخصال في اسم إشارة مفرد لإبراز وحدتها وتكاملها، واستوائها في وجوب الانقياد لحكم الله فيها؛ فلا ينتقي المرء بعض الوصايا ويترك بعضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص344، تحت «بلاغة العدول عن الجمع إلى الإفراد في «ذلك»»","url":""}]},{"id":"s17-95","number":95,"surah":17,"verses":[38],"references":[{"surah":17,"verses":[38]}],"verseLabel":"الإسراء: 38","question":"ما سرّ تقديم ﴿عِنْدَ رَبِّكَ﴾ على ﴿مَكْرُوهًا﴾؟","answer":"قدّم الظرف للاهتمام بكون هذه الأفعال مكروهة عند الله، فيشتد التنفير منها؛ وذكر الرب يذكّر بقبح مقابلة إحسان المنعم بمعصيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص346، 347، تحت «بلاغة تقديم «عند ربك» على «مكروهًا»؛ فائدة التعبير بالربوبية في «عند ربك»»","url":""}]},{"id":"s17-96","number":96,"surah":17,"verses":[39],"references":[{"surah":17,"verses":[39]}],"verseLabel":"الإسراء: 39","question":"ما سر وصف هذه الوصايا بأنها ﴿مِنَ الْحِكْمَةِ﴾؟","answer":"لإحكام هذه التكاليف وكمالها، وموافقة العقل لصحتها، واشتراك الشرائع في أصولها؛ فهي تجمع التوحيد والطاعات والتوجه إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص353، تحت «نكتة كون التكاليف المشار إليها من الحكمة»","url":""}]},{"id":"s17-97","number":97,"surah":17,"verses":[39],"references":[{"surah":17,"verses":[39]}],"verseLabel":"الإسراء: 39","question":"ما سر تكرار النهي عن الشرك في ختام سلسلة الوصايا؟","answer":"ليطوق الأحكام بالتوحيد أولًا وآخرًا، فكل الأخلاق بين أصلها وعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص354، تحت «نكتة تكرار النهي عن اتخاذ إله مع الله»","url":""}]},{"id":"s17-98","number":98,"surah":17,"verses":[39],"references":[{"surah":17,"verses":[39]}],"verseLabel":"الإسراء: 39","question":"ما سر اختلاف الخاتمتين: ﴿مَذْمُومًا مَخْذُولًا﴾ و﴿مَلُومًا مَدْحُورًا﴾؟","answer":"الأولى حال المشرك في الدنيا بين الذم والخذلان، والثانية عاقبته في جهنم بين اللوم والطرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص356، تحت «الموازنة بين الآيتين 39 و22 من السورة»","url":""}]},{"id":"s17-99","number":99,"surah":17,"verses":[40],"references":[{"surah":17,"verses":[40]}],"verseLabel":"الإسراء: 40","question":"ما سرّ التعبير بقوله تعالى: ﴿أَفَأَصْفَاكُمْ رَبُّكُمْ بِالْبَنِينَ﴾؟","answer":"الاستفهام يفضح تناقضهم: زعموا لأنفسهم ما يحبون ونسبوا إلى الله ما يكرهون.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص362، 363، 364، تحت «غرض التعبير بالاستفهام «أفأصفاكم»؛ سر التقييد بقوله «بالبنين»»","url":""}]},{"id":"s17-100","number":100,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما سرّ التعبير بقوله تعالى: ﴿صَرَّفْنَا فِي هَذَا الْقُرْآنِ﴾؟","answer":"التصريف تنويع الحجج والأمثال والأساليب حتى تتفتح للحق طرق متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص373، تحت «معنى التصريف ودلالته في سياق الآية»","url":""}]},{"id":"s17-101","number":101,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما سر حذف مفعول ﴿صَرَّفْنَا﴾ في هذه الآية؟","answer":"لإفادة العموم؛ فيشمل التصريف ما يسوقه القرآن لإبطال أقوالهم من أدلة ومواعظ وأمثال وترغيب وترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص374، 375، تحت «غرض حذف المفعول به من الفعل «صرفنا»»","url":""}]},{"id":"s17-102","number":102,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما دلالة القصر في قوله: ﴿وما يزيدهم إلا نفورًا﴾؟","answer":"يقصر أثر عنادهم عند سماع القرآن على ازدياد النفور، فيكشف أن الخلل في إرادتهم لا في وضوح الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص376، تحت «غرض التعبير بأسلوب القصر»","url":""}]},{"id":"s17-207","number":207,"surah":17,"verses":[41],"references":[{"surah":17,"verses":[41]}],"verseLabel":"الإسراء: 41","question":"ما دلالة المضارع في قوله: ﴿يزيدهم﴾؟","answer":"يصوّر تجدد نفورهم كلما تجدد سماع البيان، لا نفورًا وقع مرة وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص377، تحت «دلالة التعبير بالمضارع «يزيدهم»»","url":""}]},{"id":"s17-103","number":103,"surah":17,"verses":[42],"references":[{"surah":17,"verses":[42]}],"verseLabel":"الإسراء: 42","question":"ما دلالة الشرط في قوله: ﴿لو كان معه آلهة كما يقولون لابتغوا إلى ذي العرش سبيلًا﴾؟","answer":"يفرض زعمهم جدلًا ثم يلزمهم ببطلانه: فلو وُجدت آلهة لظهر افتقارها إلى الله أو طلبها مغالبته، وكلا الوجهين يهدم دعوى الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص380، تحت «غرض التعبير بأسلوب الشرط»","url":""}]},{"id":"s17-208","number":208,"surah":17,"verses":[42],"references":[{"surah":17,"verses":[42]}],"verseLabel":"الإسراء: 42","question":"ما دلالة وصف الله بـ﴿ذي العرش﴾ في الرد على المشركين؟","answer":"يستحضر كمال ملك الله وسلطانه في مقابل عجز ما يعبدون وافتقاره إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص383، تحت «إيثار التعبير بالمجرور مضافًا «ذي العرش»»","url":""}]},{"id":"s17-104","number":104,"surah":17,"verses":[43],"references":[{"surah":17,"verses":[43]}],"verseLabel":"الإسراء: 43","question":"ما سرّ التعبير بقوله تعالى: ﴿عُلُوًّا كَبِيرًا﴾ بعد ﴿سُبْحَانَهُ وَتَعَالَى﴾؟","answer":"المصدر يؤكد تنزه الله وعلوه الحقيقي، ووصفه بالكبير يبالغ في بيان براءته مما نسبوه إليه من شريك أو ولد؛ فهو كمال لا تلحقه دعاواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص389، تحت «دلالة التعبير بالمفعول المطلق «علوًا»؛ سر وصف المفعول المطلق بلفظ «كبيرًا»»","url":""}]},{"id":"s17-105","number":105,"surah":17,"verses":[44],"references":[{"surah":17,"verses":[44]}],"verseLabel":"الإسراء: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ﴾؟","answer":"النفي والاستثناء يستغرقان كل موجود، فيتحول الكون كله إلى شاهد توحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص397، تحت «سر التعبير بأسلوب الاستغراق في «وإن من شيء»»","url":""}]},{"id":"s17-106","number":106,"surah":17,"verses":[44],"references":[{"surah":17,"verses":[44]}],"verseLabel":"الإسراء: 44","question":"ما سرّ التعبير بقوله تعالى: ﴿لَا تَفْقَهُونَ تَسْبِيحَهُمْ﴾ لا «لا تسمعون»؟","answer":"الفقه فهم المعنى، فلا يلزم من عدم فهم التسبيح نفي وقوعه. ويذكر المصدر أن الاستدراك يدفع توهم أن تسبيح الكائنات يماثل كلام الإنسان الذي يدركه السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص399، 401، تحت «دلالة العطف في «ولكن لا تفقهون»؛ الفقه والعلم»","url":""}]},{"id":"s17-107","number":107,"surah":17,"verses":[44],"references":[{"surah":17,"verses":[44]}],"verseLabel":"الإسراء: 44","question":"ما سر ختام آية تسبيح الكائنات بقوله تعالى: ﴿حَلِيمًا غَفُورًا﴾؟","answer":"مع أن الكون يسبحه والإنسان يقصر أو يشرك، يمهله بحلمه ويفتح له المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص400، تحت «نكتة الاقتران بين الاسمين الجليلين»","url":""}]},{"id":"s17-108","number":108,"surah":17,"verses":[45],"references":[{"surah":17,"verses":[45]}],"verseLabel":"الإسراء: 45","question":"ما دلالة وصف الحجاب بـ﴿مَسْتُورًا﴾ عند قراءة القرآن؟","answer":"من توجيهاته أن «مستورًا» بمعنى ساتر، إسنادًا للوصف على سبيل المجاز؛ ومن توجيهاته أنه حجاب خفي لا تدركه الأبصار. والسياق يصور الحاجز الذي يحول دون انتفاع المكذبين بالقرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص408، 409، تحت «بلاغة المجاز العقلي في الحجاب المستور»","url":""}]},{"id":"s17-109","number":109,"surah":17,"verses":[46],"references":[{"surah":17,"verses":[46]},{"surah":18,"verses":[57]}],"verseLabel":"الإسراء: 46؛ الكهف: 57","question":"ما سرّ التعبير بقوله تعالى: ﴿عَلَى قُلُوبِهِمْ أَكِنَّةً﴾ و﴿فِي آذَانِهِمْ وَقْرًا﴾؟","answer":"في الإسراء والكهف، تصور «على» الأكنة مستعلية على القلوب متمكنة منها، كالأغطية الحاجبة للفهم. وتصور «في» الوقر مستقرًا في الآذان، فلا ينتفع أصحابها بالسماع؛ فيجتمع حجب الفهم وثقل السمع في تصوير الإعراض عن القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص416، تحت «نكتة حرف الظرفية «في» مقابل حرف الاستعلاء «على»»","url":""}]},{"id":"s17-110","number":110,"surah":17,"verses":[46],"references":[{"surah":17,"verses":[46]}],"verseLabel":"الإسراء: 46","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَّوْا عَلَى أَدْبَارِهِمْ نُفُورًا﴾؟","answer":"«على أدبارهم» كناية عن شدة الإعراض عن القرآن والتوحيد، و«نفورًا» يزيد تصوير هذا الصدود وتأكيده؛ فليس موقفهم مجرد ترك للاستماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص420، 421، تحت «سر تقييد الفعل «ولوا» بالجار والمجرور؛ سر تقييد الفعل بـ«نفورًا»»","url":""}]},{"id":"s17-111","number":111,"surah":17,"verses":[47],"references":[{"surah":17,"verses":[47]}],"verseLabel":"الإسراء: 47","question":"ما سرّ التعبير بقوله تعالى: ﴿نَحْنُ أَعْلَمُ بِمَا يَسْتَمِعُونَ بِهِ﴾؟","answer":"يكشف أن استماعهم لم يكن طلب هدى بل ترصدًا واستهزاء، والله أعلم بدافع السماع الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص424، 425، 426، 427، تحت «نكتة التعبير باسم الموصول «ما»؛ معنى الباء في «به» ودلالتها؛ سر تقييد الفعل بالحال المؤولة»","url":""}]},{"id":"s17-112","number":112,"surah":17,"verses":[47],"references":[{"surah":17,"verses":[47]}],"verseLabel":"الإسراء: 47","question":"ما سر الإخبار عنهم بالمصدر في قوله تعالى: ﴿وَإِذْ هُمْ نَجْوَى﴾؟","answer":"النجوى تناجيهم وتآمرهم، ووصفهم بالمصدر مبالغة في كثرة التناجي حتى كأنهم صاروا نجوى. والجملة الاسمية تصور ثباتهم عليه، مع إحاطة علم الله باستماعهم وتناجيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص429، تحت «دلالة التعبير بالمسند مصدرًا»","url":""}]},{"id":"s17-113","number":113,"surah":17,"verses":[48],"references":[{"surah":17,"verses":[48]},{"surah":25,"verses":[9]}],"verseLabel":"الإسراء: 48؛ الفرقان: 9","question":"ما دلالة الاستفهام بـ﴿كيف﴾ في قوله: ﴿انظر كيف ضربوا لك الأمثال﴾؟","answer":"يدعو إلى التعجب من طرائق افترائهم المتناقضة على الرسول، لا إلى السؤال عن هيئة مجهولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص436، تحت «غرض الاستفهام بـ«كيف»»","url":""}]},{"id":"s17-209","number":209,"surah":17,"verses":[48],"references":[{"surah":17,"verses":[48]},{"surah":25,"verses":[9]}],"verseLabel":"الإسراء: 48؛ الفرقان: 9","question":"ما دلالة تعريف ﴿الأمثال﴾ في قوله: ﴿ضربوا لك الأمثال﴾؟","answer":"يشير إلى الأوصاف والاتهامات المعروفة التي كرروها في حق الرسول، فيستحضر بطلانها وتناقضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص437، تحت «سر تعريف المفعول «الأمثال» بأل»","url":""}]},{"id":"s17-210","number":210,"surah":17,"verses":[48],"references":[{"surah":17,"verses":[48]},{"surah":25,"verses":[9]}],"verseLabel":"الإسراء: 48؛ الفرقان: 9","question":"ما دلالة تنكير ﴿سبيلًا﴾ في قوله: ﴿فلا يستطيعون سبيلًا﴾؟","answer":"يعمم نفي كل طريق يبلغون به إلى حجة مستقيمة أو غرض صحيح، بعد أن أضلّتهم أمثالهم الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج37، ص522، تحت «غرض تنكير سبيلًا»","url":""}]},{"id":"s17-114","number":114,"surah":17,"verses":[49],"references":[{"surah":17,"verses":[49]}],"verseLabel":"الإسراء: 49","question":"ما دلالة الجمع بين ﴿عِظَامًا وَرُفَاتًا﴾ في اعتراض منكري البعث؟","answer":"جمعوا ذكر العظام وما يتفتت ويبلى من بقايا الجسد، ليؤكدوا ما يرونه من فناء الأجسام ويتخذوه ذريعة لاستبعاد البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص445، تحت «دلالة العطف في لفظ «ورفاتًا»»","url":""}]},{"id":"s17-115","number":115,"surah":17,"verses":[50],"references":[{"surah":17,"verses":[50]}],"verseLabel":"الإسراء: 50","question":"ما دلالة الرد على منكري البعث بقوله تعالى: ﴿كُونُوا حِجَارَةً أَوْ حَدِيدًا﴾؟","answer":"حتى لو تحولوا في وهمهم إلى أصلب ما يعرفون، فلن يعجز الخالق عن إعادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص455، 456، 457، تحت «بلاغة التعبير بالأمر «كونوا» رغم عجزهم؛ نكتة تنكير الحجارة والحديد»","url":""}]},{"id":"s17-116","number":116,"surah":17,"verses":[51],"references":[{"surah":17,"verses":[51]}],"verseLabel":"الإسراء: 51","question":"ما سرّ التعبير بقوله تعالى: ﴿أَوْ خَلْقًا مِمَّا يَكْبُرُ فِي صُدُورِكُمْ﴾؟","answer":"عمم إلى أي خلق يرونه أشد امتناعًا، فيقطع كل مهرب يتخيله المنكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص459، 460، 461، تحت «نكتة تنكير «خلقًا»؛ نكتة التعبير بالاسم الموصول «ما»؛ نكتة إيثار الصدور على القلوب»","url":""}]},{"id":"s17-117","number":117,"surah":17,"verses":[52],"references":[{"surah":17,"verses":[52]}],"verseLabel":"الإسراء: 52","question":"ما دلالة تصوير البعث بقوله تعالى: ﴿يَوْمَ يَدْعُوكُمْ فَتَسْتَجِيبُونَ بِحَمْدِهِ﴾؟","answer":"صوّر البعث دعوةً من الله تعقبها استجابة لا يملكون التخلف عنها؛ و﴿بحمده﴾ تحتمل أنهم يبعثون حامدين، أو مستجيبين لأمره وطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص473، 474، 475، تحت «معنى «يدعوكم» بين الحقيقة والمجاز؛ معنى الفاء في قوله «فتستجيبون»؛ معاني الحمد في قوله «بحمده»»","url":""}]},{"id":"s17-118","number":118,"surah":17,"verses":[52],"references":[{"surah":17,"verses":[52]}],"verseLabel":"الإسراء: 52","question":"ما دلالة استقصارهم اللبث بقولهم إنه لم يكن ﴿إِلَّا قَلِيلًا﴾؟","answer":"يصور القصر استقصارهم زمن اللبث عند البعث؛ فمدة الحياة الدنيا تبدو قليلة في مقابلة الآخرة. ويذكر المصدر أن تقديرهم قد يكون خاطئًا يعقبه الندم على تفويت العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص476، 477، تحت «نكتة التعبير بـ«تظنون»؛ بلاغة القصر في «إن لبثتم إلا قليلًا»؛ نكتة تنكير «قليلًا»»","url":""}]},{"id":"s17-119","number":119,"surah":17,"verses":[53],"references":[{"surah":17,"verses":[53]}],"verseLabel":"الإسراء: 53","question":"ما سرّ التعبير بقوله تعالى: ﴿يَقُولُوا الَّتِي هِيَ أَحْسَنُ﴾ ولم يقل «قولًا حسنًا»؟","answer":"أمر باختيار الأحسن من البدائل، لأن كلمة صحيحة بعبارة خشنة قد تفتح باب النزاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص485، تحت «فائدة التعبير بصيغة التفضيل»","url":""}]},{"id":"s17-120","number":120,"surah":17,"verses":[53],"references":[{"surah":17,"verses":[53]}],"verseLabel":"الإسراء: 53","question":"ما سر تعليل الأمر بأحسن القول بأن ﴿الشَّيْطَانَ يَنْزَغُ بَيْنَهُمْ﴾؟","answer":"لأن الشيطان يستثمر الكلمة المحتملة ويحول الخلاف الصغير إلى عداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص485، 486، 487، تحت «نكتة فصل «إن الشيطان ينزغ بينهم»؛ نكتة التعبير بـ«ينزغ» مادة وصيغة؛ بلاغة الاستعارة في التعبير بالنزغ»","url":""}]},{"id":"s17-121","number":121,"surah":17,"verses":[54],"references":[{"surah":17,"verses":[54]}],"verseLabel":"الإسراء: 54","question":"ما سرّ التعبير بقوله تعالى: ﴿رَبُّكُمْ أَعْلَمُ بِكُمْ﴾ بعد الأمر بأحسن القول؟","answer":"ليمنع المؤمن من تزكية نفسه والحكم النهائي على غيره؛ فمصائر العباد إلى علم ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص494، تحت «نكتة فصل الآية عن سابقاتها»","url":""}]},{"id":"s17-122","number":122,"surah":17,"verses":[55],"references":[{"surah":17,"verses":[55]}],"verseLabel":"الإسراء: 55","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَى بَعْضٍ﴾؟","answer":"ليرد اعتراضهم على اختيار محمد؛ فالتفضيل بين الرسل سنة ربانية لا حق للمقترحين فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص512، 513، 514، تحت «معنى الواو في «ولقد»؛ معنى «قد» ونكتة دخولها على «فضلنا»؛ علة تفضيل بعض الأنبياء دون تعيين»","url":""}]},{"id":"s17-123","number":123,"surah":17,"verses":[55],"references":[{"surah":17,"verses":[55]}],"verseLabel":"الإسراء: 55","question":"ما سر تخصيص داود بإيتاء الزبور في سياق تفضيل الأنبياء؟","answer":"من وجوه تخصيصه التنبيه إلى أن التفضيل بالوحي والعلم والدين، لا بالملك والمال؛ فذُكر كتابه مع ما كان له من ملك عظيم. وفيه أيضًا رد على من يحصر إنزال الكتب في موسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص516، تحت «سر النص على داود دون الأنبياء»","url":""}]},{"id":"s17-124","number":124,"surah":17,"verses":[56],"references":[{"surah":17,"verses":[56]}],"verseLabel":"الإسراء: 56","question":"ما سرّ التعبير بقوله تعالى: ﴿فَلَا يَمْلِكُونَ كَشْفَ الضُّرِّ عَنْكُمْ وَلَا تَحْوِيلًا﴾؟","answer":"نفى قدرتهم على إزالة الضر وعلى نقله إلى جهة أخرى، فاستوعب وجهي الخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص529، 530، تحت «معنى الواو في «ولا تحويلًا»؛ نكتة تنكير «تحويلًا»؛ علة تقديم كشف الضر على تحويله»","url":""}]},{"id":"s17-125","number":125,"surah":17,"verses":[57],"references":[{"surah":17,"verses":[57]}],"verseLabel":"الإسراء: 57","question":"ما دلالة وصف الذين يدعوهم المشركون بأنهم ﴿يَبْتَغُونَ إِلَى رَبِّهِمُ الْوَسِيلَةَ﴾؟","answer":"من يعبدونهم هم أنفسهم عباد يطلبون القرب من الله، فكيف يُجعل المحتاج إلهًا؟","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص535، تحت «غرض الاستهلال باسم الإشارة البعيد»","url":""}]},{"id":"s17-126","number":126,"surah":17,"verses":[58],"references":[{"surah":17,"verses":[58]}],"verseLabel":"الإسراء: 58","question":"ما سرّ التعبير بقوله تعالى: ﴿وَإِنْ مِنْ قَرْيَةٍ إِلَّا نَحْنُ مُهْلِكُوهَا﴾؟","answer":"الأسلوب يقرر حتمية ما توعد الله به القرى. ويذكر المصدر وجهين: عموم القرى، فيكون إهلاك الصالحة بالموت وفناء العمران، ومعاقبة الظالمة بالعذاب؛ أو تقدير وصف «الظالمة»، فيختص الوعيد بالقرى المكذبة، وهو الوجه الذي يرجحه المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص550، تحت «بلاغة القصر ونوعه»","url":""}]},{"id":"s17-127","number":127,"surah":17,"verses":[58],"references":[{"surah":17,"verses":[58]}],"verseLabel":"الإسراء: 58","question":"ما دلالة تنكير ﴿قَرْيَةٍ﴾ في قوله تعالى: ﴿وَإِنْ مِنْ قَرْيَةٍ﴾؟","answer":"التنكير في سياق النفي، مع «من» المؤكدة للاستغراق، يفيد شمول الحكم لأفراد الجنس المقصود. ويختلف نطاقه بحسب التفسير: جميع القرى، أو جميع القرى الظالمة على تقدير هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص548، 549، 550، تحت «معنى «من» في «من قرية»؛ نكتة تنكير «قرية»»","url":""}]},{"id":"s17-128","number":128,"surah":17,"verses":[59],"references":[{"surah":17,"verses":[59]}],"verseLabel":"الإسراء: 59","question":"ما سر وصف الناقة بأنها ﴿مُبْصِرَةً﴾؟","answer":"أي آية واضحة تُبصر الناس بالحق، أو ذات علامة ظاهرة لا تلتبس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص570، 571، تحت «بلاغة استعارة لفظ «مبصرة» للناقة؛ بلاغة المجاز العقلي في إضافة الإبصار إلى الناقة»","url":""}]},{"id":"s17-129","number":129,"surah":17,"verses":[59],"references":[{"surah":17,"verses":[59]}],"verseLabel":"الإسراء: 59","question":"ما سرّ التعبير بقوله تعالى: ﴿وَمَا نُرْسِلُ بِالْآيَاتِ إِلَّا تَخْوِيفًا﴾؟","answer":"من توجيهاته أن الآيات المقترحة إنذار بما يعقب تكذيبها من العذاب، لا استجابة لمجرد التعنت. ويذكر المصدر أيضًا معنى حمل الناس على الاعتبار والتصديق خوفًا من عقوبة التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص574، تحت «نكتة ذكر التخويف في مقام إرسال الآيات»","url":""}]},{"id":"s17-130","number":130,"surah":17,"verses":[60],"references":[{"surah":17,"verses":[60]}],"verseLabel":"الإسراء: 60","question":"ما دلالة وصف الرؤيا بأنها ﴿فتنة للناس﴾؟","answer":"لأن الخبر الخارق يكشف المصدق من المكابر، فصار امتحانًا يميز مواقف الناس من الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص588، تحت «سر التعبير بقوله «فتنة»»","url":""}]},{"id":"s17-211","number":211,"surah":17,"verses":[60],"references":[{"surah":17,"verses":[60]}],"verseLabel":"الإسراء: 60","question":"لماذا أُسندت الفتنة إلى الشجرة الملعونة؟","answer":"لأن خبرها الغيبي صار سببًا لامتحان الناس؛ فصدّقه المؤمن وسخر منه المكابر، فنُسبت الفتنة إليها باعتبار أثر خبرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص590، تحت «دلالة إسناد الفتنة إلى الشجرة»","url":""}]},{"id":"s17-131","number":131,"surah":17,"verses":[61],"references":[{"surah":17,"verses":[61]}],"verseLabel":"الإسراء: 61","question":"ما دلالة قول إبليس: ﴿أَأَسْجُدُ لِمَنْ خَلَقْتَ طِينًا﴾؟","answer":"الاستفهام إنكار واستكبار، وذكر الطين يبرز العلة التي توهمها إبليس للامتناع: احتقار أصل آدم المادي. ومن التوجيهات إعراب «طينًا» حالًا، أي خلقته من هذا الجنس؛ فليس المقصود تقرير صحة قياس إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص606، 607، تحت «دلالة الاستفهام الإنكاري في قوله «أأسجد»؛ دلالة التقييد بالحال «طينًا»؛ سر التعبير بقوله «طينًا»»","url":""}]},{"id":"s17-132","number":132,"surah":17,"verses":[62],"references":[{"surah":17,"verses":[62]}],"verseLabel":"الإسراء: 62","question":"ما دلالة قول إبليس: ﴿لَأَحْتَنِكَنَّ ذُرِّيَّتَهُ﴾؟","answer":"الاحتناك أخذ الدابة بحنكها وقيادها؛ فصوّر طمعه في الاستيلاء على أكثر البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص619، 620، 621، تحت «براعة الاستعارة في قوله «لأحتنكن»؛ سر التعبير بقوله «لأحتنكن»»","url":""}]},{"id":"s17-133","number":133,"surah":17,"verses":[63],"references":[{"surah":17,"verses":[63]}],"verseLabel":"الإسراء: 63","question":"ما دلالة الرد على إبليس بقوله تعالى: ﴿اذْهَبْ﴾؟","answer":"أمر إهانة وتهديد: امض في اختيارك، وسترى أنت وأتباعك الجزاء الموفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص627، 628، تحت «دلالة فعل الأمر «اذهب» بين المجاز والحقيقة»","url":""}]},{"id":"s17-134","number":134,"surah":17,"verses":[64],"references":[{"surah":17,"verses":[64]}],"verseLabel":"الإسراء: 64","question":"ما سرّ التعبير بقوله تعالى: ﴿وَاسْتَفْزِزْ مَنِ اسْتَطَعْتَ مِنْهُمْ بِصَوْتِكَ﴾؟","answer":"الاستفزاز استخفاف يزعج الإنسان من موضعه، والصوت يشمل كل دعوة تثيره إلى المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص637، 638، 639، تحت «إيثار لفظ «استفزز» دون غيره؛ بلاغة المجاز في تخصيص الاستفزاز بصوت إبليس؛ بلاغة المجاز المرسل في التعبير بالصوت عن النداء»","url":""}]},{"id":"s17-135","number":135,"surah":17,"verses":[64],"references":[{"surah":17,"verses":[64]}],"verseLabel":"الإسراء: 64","question":"ما سرّ التعبير بقوله تعالى: ﴿وَأَجْلِبْ عَلَيْهِمْ بِخَيْلِكَ وَرَجِلِكَ﴾؟","answer":"يصور جمع أعوان الإغواء ووسائله بصورة جيش يحشد فرسانه ومشاته؛ فيستحضر كثرة المداخل التي يهاجم بها الشيطان الإنسان وتكاملها في إضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص644، تحت «بلاغة الاستعارة في تمثيل صراع إبليس مع البشر»","url":""}]},{"id":"s17-136","number":136,"surah":17,"verses":[64],"references":[{"surah":17,"verses":[64]}],"verseLabel":"الإسراء: 64","question":"ما سر وصف وعد الشيطان بأنه ﴿غُرُورًا﴾؟","answer":"لأنه يزين منفعة عاجلة ويخفي خسارتها، فحقيقته خداع لا وعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص650، تحت «علة إيثار لفظ «غرورًا»»","url":""}]},{"id":"s17-137","number":137,"surah":17,"verses":[65],"references":[{"surah":17,"verses":[65]}],"verseLabel":"الإسراء: 65","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ﴾؟","answer":"يطَمئن عباد الله أن الشيطان يوسوس ولا يملك إجبار القلب الذي احتمى بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص656، تحت «فائدة نفي سلطان إبليس على عباد الله المؤمنين»","url":""}]},{"id":"s17-138","number":138,"surah":17,"verses":[66],"references":[{"surah":17,"verses":[66]}],"verseLabel":"الإسراء: 66","question":"ما سرّ التعبير بقوله تعالى: ﴿يُزْجِي لَكُمُ الْفُلْكَ﴾؟","answer":"الإزجاء سوق الشيء برفق؛ يصور السفن الضخمة منقادة بتدبير الله فوق البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص665، تحت «سر انتخاب لفظ الإزجاء دون غيره»","url":""}]},{"id":"s17-139","number":139,"surah":17,"verses":[67],"references":[{"surah":17,"verses":[67]}],"verseLabel":"الإسراء: 67","question":"ما سرّ التعبير بقوله تعالى: ﴿ضَلَّ مَنْ تَدْعُونَ إِلَّا إِيَّاهُ﴾ عند ضر البحر؟","answer":"غاب عن وعيهم كل معبود وبقي الله وحده؛ فالشدّة تكشف التوحيد الكامن تحت الوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص677، 678، تحت «دلالة الفعل الماضي «ضل»؛ بلاغة حذف متعلق الفعل «ضل»؛ بلاغة الاستثناء في الآية»","url":""}]},{"id":"s17-140","number":140,"surah":17,"verses":[67],"references":[{"surah":17,"verses":[67]}],"verseLabel":"الإسراء: 67","question":"ما دلالة التعبير بالماضي في قوله: ﴿وكان الإنسان كفورًا﴾؟","answer":"يشير إلى رسوخ هذا الخلق وتكرره في تاريخ الإنسان، لا إلى موقف طارئ بعد نجاة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص683، تحت «بلاغة التعبير بفعل الكون ماضيًا»","url":""}]},{"id":"s17-212","number":212,"surah":17,"verses":[67],"references":[{"surah":17,"verses":[67]}],"verseLabel":"الإسراء: 67","question":"ما دلالة صيغة المبالغة ﴿كفورًا﴾؟","answer":"تصوّر كثرة كفران الإنسان للنعم وشدة عودته إلى الإعراض بعد النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص684، تحت «بلاغة صيغة المبالغة في «كفورًا»»","url":""}]},{"id":"s17-141","number":141,"surah":17,"verses":[68],"references":[{"surah":17,"verses":[68]}],"verseLabel":"الإسراء: 68","question":"ما سر التخويف بالخسف في البر بعد النجاة من البحر؟","answer":"ليبيّن أن الأمان ليس في المكان؛ من نجاهم في البحر قادر أن يأخذهم في اليابسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص691، 692، 695، تحت «بلاغة الاستفهام في «أفأمنتم»؛ بلاغة الكناية في الآية»","url":""}]},{"id":"s17-142","number":142,"surah":17,"verses":[69],"references":[{"surah":17,"verses":[69]}],"verseLabel":"الإسراء: 69","question":"ما سرّ التعبير بقوله تعالى: ﴿قَاصِفًا مِنَ الرِّيحِ﴾؟","answer":"القاصف ريح شديدة تكسر ما تمر به، فتلائم مشهد السفن المحطمة والغرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص707، 708، 716، تحت «دلالة وصف الريح بـ«قاصفًا» بالتذكير؛ القاصف والعاصف»","url":""}]},{"id":"s17-143","number":143,"surah":17,"verses":[70],"references":[{"surah":17,"verses":[70]}],"verseLabel":"الإسراء: 70","question":"ما معنى تكريم بني آدم في قوله: ﴿ولقد كرمنا بني آدم﴾؟","answer":"هو تفضيل عام بما وهبهم الله من العقل والنطق وحسن الصورة والتسخير، فيشمل أصل النوع الإنساني.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص721، تحت «معنى التكريم في الآية»","url":""}]},{"id":"s17-213","number":213,"surah":17,"verses":[70],"references":[{"surah":17,"verses":[70]}],"verseLabel":"الإسراء: 70","question":"ما دلالة حذف وجوه التكريم في قوله: ﴿ولقد كرمنا بني آدم﴾؟","answer":"يفتح الحذف المعنى لتعدد صور التكريم وكثرتها، فلا يحصرها في نعمة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص722، تحت «دلالة حذف أوجه التكريم»","url":""}]},{"id":"s17-144","number":144,"surah":17,"verses":[70],"references":[{"surah":17,"verses":[70]}],"verseLabel":"الإسراء: 70","question":"ما دلالة الجمع بين الحمل في البر والبحر؟","answer":"لاستيعاب وجهي التنقل المعروفين وإظهار تسخير البيئتين المتباينتين للإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص723، 724، تحت «دلالة الواو «وحملناهم»؛ دلالة إسناد «وحملناهم» إلى نا؛ معنى حرف الجر «في»»","url":""}]},{"id":"s17-145","number":145,"surah":17,"verses":[71],"references":[{"surah":17,"verses":[71]}],"verseLabel":"الإسراء: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿نَدْعُو كُلَّ أُنَاسٍ بِإِمَامِهِمْ﴾؟","answer":"الإمام ما يُؤتم به، وفيه توجيهات منها نبي الأمة أو كتابها أو من اقتدت به في الخير والشر، وقيل كتاب الأعمال. وإضافته إليهم تربط كل جماعة بما انتسبت إليه أو بما يشهد عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص735، تحت «فائدة الإضافة في «بإمامهم»»","url":""}]},{"id":"s17-146","number":146,"surah":17,"verses":[71],"references":[{"surah":17,"verses":[71]}],"verseLabel":"الإسراء: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَا يُظْلَمُونَ فَتِيلًا﴾؟","answer":"الفتيل خيط دقيق في شق النواة؛ اختير لتصوير انتفاء أدنى قدر من الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص740، 741، تحت «دلالة الإفراد في «فتيلًا»؛ بلاغة نيابة «فتيلًا» عن المفعول المطلق؛ بلاغة الكناية في «ولا يظلمون فتيلًا»»","url":""}]},{"id":"s17-147","number":147,"surah":17,"verses":[72],"references":[{"surah":17,"verses":[72]}],"verseLabel":"الإسراء: 72","question":"ما دلالة ربط عمى الآخرة بعمى الدنيا؟","answer":"يربط الشرط بين الإعراض عن دلائل الهدى في الدنيا وعاقبته في الآخرة. ومن توجيهات العمى الثاني عمى البصيرة، فيكون المعرض هناك أشد حيرة وأبعد عن طريق النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص748، 750، 751، تحت «فائدة اسم الشرط «من»؛ معنى الفاء في «فهو» ودلالتها؛ دلالة الاختلاف في «أعمى» الثانية»","url":""}]},{"id":"s17-148","number":148,"surah":17,"verses":[73],"references":[{"surah":17,"verses":[73]}],"verseLabel":"الإسراء: 73","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيَفْتِنُونَكَ عَنِ الَّذِي أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"عُدّي فعل الفتنة بـ«عن» لتضمينه معنى الصرف؛ فجمع التعبير بين محاولة اختباره وفتنته ومحاولة إبعاده عن الوحي. والموصول يستحضر أن الذي يريدون صرفه عنه وحي من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص762، 763، 768، تحت «أثر تعدية الفعل بحرف الجر «عن»؛ سر التعبير بالاسم الموصول؛ الفتن والصرف»","url":""}]},{"id":"s17-149","number":149,"surah":17,"verses":[74],"references":[{"surah":17,"verses":[74]}],"verseLabel":"الإسراء: 74","question":"ما دلالة ﴿لولا﴾ في قوله: ﴿ولولا أن ثبتناك﴾؟","answer":"تفيد أن الركون امتنع بسبب تثبيت الله، فتقرر عصمته وعناية الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص771، تحت «معنى لولا وبلاغة أسلوب الشرط»","url":""}]},{"id":"s17-214","number":214,"surah":17,"verses":[74],"references":[{"surah":17,"verses":[74]}],"verseLabel":"الإسراء: 74","question":"ما دلالة إسناد التثبيت إلى ضمير العظمة في قوله: ﴿ثبتناك﴾؟","answer":"يظهر أن الثبات فضل من الله وقوة عنايته برسوله، لا اعتمادًا على قدرة بشرية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص772، تحت «بلاغة إسناد الفعل إلى ضمير العظمة»","url":""}]},{"id":"s17-150","number":150,"surah":17,"verses":[75],"references":[{"surah":17,"verses":[75]}],"verseLabel":"الإسراء: 75","question":"ما دلالة مضاعفة العذاب على فرض الركون في قوله تعالى: ﴿ضِعْفَ الْحَيَاةِ وَضِعْفَ الْمَمَاتِ﴾؟","answer":"هذا وعيد على فرض الركون، مع أن الآية السابقة أثبتت التثبيت والعصمة منه. ومضاعفة الجزاء تناسب عظم المنزلة والمسؤولية وما قد يترتب على الاقتداء بصاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص779، 780، 781، 782، تحت «دلالة حذف الموصوف في الآية»","url":""}]},{"id":"s17-151","number":151,"surah":17,"verses":[76],"references":[{"surah":17,"verses":[76]}],"verseLabel":"الإسراء: 76","question":"ما سرّ التعبير بقوله تعالى: ﴿لَيَسْتَفِزُّونَكَ مِنَ الْأَرْضِ﴾؟","answer":"الاستفزاز إزعاج بعنف وخفة، فيصور محاولتهم اقتلاعه من وطنه لا مجرد إخراجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص791، تحت «علة إيثار فعل الإخراج»","url":""}]},{"id":"s17-152","number":152,"surah":17,"verses":[77],"references":[{"surah":17,"verses":[77]}],"verseLabel":"الإسراء: 77","question":"ما سرّ التعبير بقوله تعالى: ﴿سُنَّةَ مَنْ قَدْ أَرْسَلْنَا قَبْلَكَ﴾؟","answer":"يثبت أن إخراج الرسل يعقبه هلاك المكذبين، وأن ما يواجهه ليس حادثًا بلا نظير.","sources":[{"label":"موسوعة التفسير البلاغي، ج28، ص799، تحت «دلالة التعبير بالمصدر المؤكد «سنة»»","url":""}]},{"id":"s17-153","number":153,"surah":17,"verses":[78],"references":[{"surah":17,"verses":[78]}],"verseLabel":"الإسراء: 78","question":"ما دلالة ربط إقامة الصلاة بـ﴿دُلُوكِ الشَّمْسِ﴾؟","answer":"الدلوك ميل الشمس، ومن تفسيراته زوالها عن وسط السماء ومن تفسيراته غروبها. وربط إقامة الصلاة بهذه العلامة المشهودة يحدد وقتها، ثم يمتد البيان إلى غسق الليل ويخص الفجر بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص14، تحت «دلالة إضافة الدلوك إلى الشمس»","url":""}]},{"id":"s17-154","number":154,"surah":17,"verses":[78],"references":[{"surah":17,"verses":[78]}],"verseLabel":"الإسراء: 78","question":"ما سر تسمية صلاة الفجر ﴿قُرْآنَ الْفَجْرِ﴾؟","answer":"سميت الصلاة بجزء منها، وهو القراءة، تنويهًا بشأنها فيها؛ إذ تطول قراءة الفجر ويُجهر بها، فيظهر هذا الركن ويشهده المصلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص16، تحت «بلاغة المجاز المرسل في «وقرآن الفجر»»","url":""}]},{"id":"s17-155","number":155,"surah":17,"verses":[78],"references":[{"surah":17,"verses":[78]}],"verseLabel":"الإسراء: 78","question":"ما دلالة وصف قرآن الفجر بأنه ﴿مَشْهُودًا﴾؟","answer":"من معاني كونه مشهودًا اجتماع ملائكة الليل وملائكة النهار لشهوده؛ وفي وصفه بذلك تنويه بفضله وحث على العناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص18، تحت «بلاغة الكناية في لفظ مشهودًا»","url":""}]},{"id":"s17-156","number":156,"surah":17,"verses":[79],"references":[{"surah":17,"verses":[79]}],"verseLabel":"الإسراء: 79","question":"ما سر إيثار لفظ ﴿نافلة﴾ في قيام الليل؟","answer":"النافلة زيادة، فالتعبير ينوه بما خُص به النبي من زيادة في وظيفة العبادة والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص23، تحت «إيثار لفظ نافلة دون تهجدًا»","url":""}]},{"id":"s17-215","number":215,"surah":17,"verses":[79],"references":[{"surah":17,"verses":[79]}],"verseLabel":"الإسراء: 79","question":"ما سر إيثار البعث في قوله: ﴿عسى أن يبعثك ربك مقامًا محمودًا﴾؟","answer":"يناسب المقام المحمود الذي يظهر يوم القيامة؛ فالبعث انتقال إلى المقام الذي يحمده فيه الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص24، تحت «إيثار لفظ البعث دون غيره»","url":""}]},{"id":"s17-157","number":157,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما دلالة إضافة المدخل والمخرج إلى الصدق؟","answer":"تجعل الصدق ملازمًا لبدايات الانتقال ونهاياته، فلا يكون دخول ولا خروج إلا بحق وعاقبة محمودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص34، تحت «فائدة إضافة المدخل والمخرج إلى الصدق»","url":""}]},{"id":"s17-216","number":216,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما سر تقديم ﴿مدخل صدق﴾ على ﴿مخرج صدق﴾؟","answer":"يرتب الدعاء على ما يستقبل من الدخول ثم ما يعقبه من الخروج، ويطلب صلاح الحال في الوجهتين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص35، تحت «سر تقديم الإدخال على الإخراج»","url":""}]},{"id":"s17-158","number":158,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما دلالة تنكير ﴿سلطانًا﴾ في الدعاء؟","answer":"يفيد طلب سلطان عظيم كافٍ لما يواجهه الرسول، من حجة أو قدرة يؤيد الله بها الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص36، تحت «إيثار لفظ سلطانًا منكّرًا»","url":""}]},{"id":"s17-217","number":217,"surah":17,"verses":[80],"references":[{"surah":17,"verses":[80]}],"verseLabel":"الإسراء: 80","question":"ما سر وصف السلطان بأنه ﴿نصيرًا﴾؟","answer":"يبين أن الغرض منه نصرة الحق وإظهار الدين، لا مجرد العلو والتمكن.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص36، تحت «سر وصف السلطان بالنصير»","url":""}]},{"id":"s17-159","number":159,"surah":17,"verses":[81],"references":[{"surah":17,"verses":[81]}],"verseLabel":"الإسراء: 81","question":"ما سر التعبير بـ﴿زهق الباطل﴾ في مقابل ﴿جاء الحق﴾؟","answer":"يقابل ظهور الحق وثباته بذهاب الباطل واضمحلاله، ويصوّر زواله كزهوق الروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص40، تحت «سر التعبير بالفعل زهق مقابلًا للفعل جاء»","url":""}]},{"id":"s17-218","number":218,"surah":17,"verses":[81],"references":[{"surah":17,"verses":[81]}],"verseLabel":"الإسراء: 81","question":"ما دلالة التذييل: ﴿إن الباطل كان زهوقًا﴾؟","answer":"يقرر أن الزوال طبيعة الباطل مهما طال ظهوره، فيحوّل المشهد الخاص إلى قاعدة عامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص43، تحت «فن التذييل»","url":""}]},{"id":"s17-160","number":160,"surah":17,"verses":[82],"references":[{"surah":17,"verses":[82]}],"verseLabel":"الإسراء: 82","question":"ما دلالة وصف القرآن بأنه ﴿شفاء﴾؟","answer":"يزيل عن المؤمنين أمراض الشبهات وضلال العقائد وفساد الأعمال والأخلاق، فشبّه أثره في القلوب بأثر الدواء في الأبدان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص49، تحت «بلاغة المجاز في لفظ شفاء»","url":""}]},{"id":"s17-219","number":219,"surah":17,"verses":[82],"references":[{"surah":17,"verses":[82]}],"verseLabel":"الإسراء: 82","question":"كيف أُسندت زيادة الخسار إلى القرآن مع أنه هداية؟","answer":"نُسبت الزيادة إليه لأنه سبب ظهور عناد الظالمين عند سماعه، أما منشأ الخسار الحقيقي فهو إعراضهم وكفرهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص52، تحت «بلاغة المجاز العقلي في إسناد الزيادة إلى القرآن»","url":""}]},{"id":"s17-161","number":161,"surah":17,"verses":[83],"references":[{"surah":17,"verses":[83]}],"verseLabel":"الإسراء: 83","question":"ما سرّ التعبير بقوله تعالى: ﴿نَأَى بِجَانِبِهِ﴾ لا «ابتعد»؟","answer":"يصوّر الإعراض بحركة الجنب المتكبر، كأنه يصرف نفسه كلها عن المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص61، تحت «إيثار التعبير بنأي الجانب»","url":""}]},{"id":"s17-162","number":162,"surah":17,"verses":[83],"references":[{"surah":17,"verses":[83]}],"verseLabel":"الإسراء: 83","question":"ما دلالة التعبير بـ﴿يَئُوسًا﴾ عند مس الشر؟","answer":"صيغة «يئوس» تبالغ في وصف القنوط؛ ويقابل السياق يأسه عند مس الشر بإعراضه عند النعمة، فيكشف اختلال موقفه في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص65، تحت «نكتة إيثار المصدر يئوسًا وتنكيره»","url":""}]},{"id":"s17-163","number":163,"surah":17,"verses":[84],"references":[{"surah":17,"verses":[84]}],"verseLabel":"الإسراء: 84","question":"ما سرّ التعبير بقوله تعالى: ﴿كُلٌّ يَعْمَلُ عَلَى شَاكِلَتِهِ﴾؟","answer":"الشاكلة الهيئة والطبع والطريقة؛ فالعمل يخرج كاشفًا للبنية الداخلية لصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص70، 71، 74، تحت «بلاغة المجاز في «شاكلته»؛ الشاكلة والمثل والنظير»","url":""}]},{"id":"s17-164","number":164,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة الجواب عن الروح بأنها ﴿من أمر ربي﴾؟","answer":"يرد السائلين من طلب الإحاطة بسر الروح إلى أصل كافٍ: هي من شأن الله وتكوينه الذي لا يحيطون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص81، تحت «معنى من وسر تخصيص الأمر بالذكر»","url":""}]},{"id":"s17-220","number":220,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة إيثار وصف الربوبية في قوله: ﴿من أمر ربي﴾؟","answer":"يستحضر تدبير الله وتربيته وخلقه، ويصل أمر الروح مباشرة بسلطان الرب الذي انفرد بسرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص82، تحت «إيثار الربوبية دون غيرها»","url":""}]},{"id":"s17-165","number":165,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة تعريف ﴿العلم﴾ في قوله: ﴿وما أوتيتم من العلم إلا قليلًا﴾؟","answer":"يستغرق جنس العلم المتاح للبشر، فيبين أن مجموعه محدود أمام علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص83، تحت «دلالة تعريف العلم»","url":""}]},{"id":"s17-221","number":221,"surah":17,"verses":[85],"references":[{"surah":17,"verses":[85]}],"verseLabel":"الإسراء: 85","question":"ما دلالة تنكير ﴿قليلًا﴾ في قوله: ﴿إلا قليلًا﴾؟","answer":"يزيد في تصوير ضآلة ما أوتيه البشر من العلم، فلا يحيطون بكل أسرار الخلق ومنها الروح.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص84، تحت «وجه تنكير قليلًا»","url":""}]},{"id":"s17-166","number":166,"surah":17,"verses":[86],"references":[{"surah":17,"verses":[86]}],"verseLabel":"الإسراء: 86","question":"ما سرّ التعبير بقوله تعالى: ﴿لَنَذْهَبَنَّ بِالَّذِي أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"ذكّر أن بقاء القرآن فضل متجدد؛ فالذي أنزله قادر على رفعه ولا يستبقيه أحد سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص90، تحت «وجه تعدية الفعل بالباء في لنذهبن بالذي»","url":""}]},{"id":"s17-167","number":167,"surah":17,"verses":[87],"references":[{"surah":17,"verses":[87]}],"verseLabel":"الإسراء: 87","question":"ما دلالة الاستثناء في قوله تعالى: ﴿إِلَّا رَحْمَةً مِنْ رَبِّكَ﴾؟","answer":"من توجيه الاستثناء: لكن رحمة من ربك أبقت الوحي ولم تذهب به. فبعد بيان القدرة على رفعه، يذكّر التعبير بفضل الله ورحمته في إنزاله وإبقائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص95، تحت «دلالة الاستثناء بين الانقطاع والاتصال»","url":""}]},{"id":"s17-168","number":168,"surah":17,"verses":[88],"references":[{"surah":17,"verses":[88]}],"verseLabel":"الإسراء: 88","question":"ما دلالة الجمع بين الإنس والجن في تحدي الإتيان بمثل القرآن؟","answer":"ليستوعب جميع العقلاء القادرين على البيان، ثم ينفي قدرتهم ولو تعاونوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص103، تحت «فائدة اجتماع الثقلين في السياق المحكم»","url":""}]},{"id":"s17-169","number":169,"surah":17,"verses":[88],"references":[{"surah":17,"verses":[88]}],"verseLabel":"الإسراء: 88","question":"ما سرّ التعبير بقوله تعالى: ﴿وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا﴾؟","answer":"حتى لا ينسب عجزهم إلى التفرق؛ فالمساندة القصوى لا تنتج مثل القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص108، تحت «سر التعبير بأداة لو»","url":""}]},{"id":"s17-170","number":170,"surah":17,"verses":[89],"references":[{"surah":17,"verses":[89]}],"verseLabel":"الإسراء: 89","question":"ما سرّ التعبير بقوله تعالى: ﴿صَرَّفْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِنْ كُلِّ مَثَلٍ﴾؟","answer":"نوّع البيان ووجّهه للناس ليقطع عذر من يطلب صورة أخرى للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص115، تحت «بلاغة الكناية في جملة صرفنا»","url":""}]},{"id":"s17-171","number":171,"surah":17,"verses":[90,91,92,93],"references":[{"surah":17,"verses":[90,91,92,93]}],"verseLabel":"الإسراء: 90-93","question":"ما دلالة قول المشركين: ﴿لن نؤمن لك﴾؟","answer":"تفيد ﴿لن﴾ إصرارهم على نفي الإيمان في المستقبل، فتفضح أن مطالبهم تعنت لا طلب برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص124، تحت «سر إيثار النفي بلن في السياق»","url":""}]},{"id":"s17-222","number":222,"surah":17,"verses":[90,91,92,93],"references":[{"surah":17,"verses":[90,91,92,93]}],"verseLabel":"الإسراء: 90-93","question":"ما دلالة تقييد الكتاب بقولهم: ﴿كتابًا نقرؤه﴾؟","answer":"اشترطوا كتابًا ماديًا ينزل عليهم ويباشرون قراءته، فزادوا في التحكم بعد قيام آية القرآن القائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص147، تحت «سر تقييد الكتاب بالصفة نقرؤه»","url":""}]},{"id":"s17-172","number":172,"surah":17,"verses":[93],"references":[{"surah":17,"verses":[93]}],"verseLabel":"الإسراء: 93","question":"ما دلالة القصر في قوله: ﴿هل كنت إلا بشرًا رسولًا﴾؟","answer":"يقصر شأنه على البشرية والرسالة: فهو مبلغ عن الله لا مالك لخزائن القدرة ولا منفذ لأهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص150، تحت «بلاغة التعبير بأسلوب القصر»","url":""}]},{"id":"s17-223","number":223,"surah":17,"verses":[93],"references":[{"surah":17,"verses":[93]}],"verseLabel":"الإسراء: 93","question":"ما دلالة الجمع بين ﴿بشرًا﴾ و﴿رسولًا﴾؟","answer":"يقرر أن البشرية لا تنافي الرسالة، لكنها تحدد وظيفة الرسول بالبلاغ ولا تجعله قادرًا على الخوارق باختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص150، تحت «وجه الجمع بين اللفظين بشرًا رسولًا»","url":""}]},{"id":"s17-173","number":173,"surah":17,"verses":[94],"references":[{"surah":17,"verses":[94]}],"verseLabel":"الإسراء: 94","question":"ما دلالة اعتراضهم بقولهم: ﴿أَبَعَثَ اللَّهُ بَشَرًا رَسُولًا﴾؟","answer":"يصور الاستفهام استنكارهم اجتماع البشرية والرسالة، وهو اعتقاد حجبهم عن الإيمان. وترد الآية التالية بأن مجانسة الرسول لمن أرسل إليهم تحقق الألفة وإمكان التلقي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص157، تحت «الغرض من الاستفهام بالهمزة»","url":""}]},{"id":"s17-174","number":174,"surah":17,"verses":[95],"references":[{"surah":17,"verses":[95]}],"verseLabel":"الإسراء: 95","question":"ما دلالة افتراض ملائكة يمشون في الأرض في بيان حكمة بشرية الرسول؟","answer":"يفترض التعبير ملائكة مستقرين في الأرض، فيناسبهم رسول من جنسهم كما يناسب البشرَ رسول بشري؛ فالمجانسة تحقق الألفة والتفاهم والتلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص163، تحت «سر التقييد بالوصف بجملة يمشون»","url":""}]},{"id":"s17-175","number":175,"surah":17,"verses":[96],"references":[{"surah":17,"verses":[96]}],"verseLabel":"الإسراء: 96","question":"ما دلالة وصف الله بأنه ﴿شهيد﴾ في قوله: ﴿كفى بالله شهيدًا بيني وبينكم﴾؟","answer":"يفيد كفاية علم الله وشهادته للرسول، وفيها تسلية له ووعيد للمكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص168، تحت «بلاغة الكناية في لفظ الشهيد»","url":""}]},{"id":"s17-224","number":224,"surah":17,"verses":[96],"references":[{"surah":17,"verses":[96]}],"verseLabel":"الإسراء: 96","question":"ما دلالة الجمع بين ﴿خبيرًا بصيرًا﴾ في تعليل شهادة الله؟","answer":"يجمع إحاطته ببواطن أحوال العباد وظواهرها، فتقوم شهادته على علم كامل لا يخفى عليه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص172، تحت «سر التعبير بالاسمين خبيرًا بصيرًا في الفاصلة»","url":""}]},{"id":"s17-176","number":176,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"ما دلالة حشر المكذبين ﴿عُمْيًا وَبُكْمًا وَصُمًّا﴾؟","answer":"جزاء مناسب لتعطيلهم وسائل الهداية في الدنيا، وحال تزيدهم ذلًا وحيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص191، تحت «العمى والبكم والصمم بين الحقيقة والاستعارة»","url":""}]},{"id":"s17-177","number":177,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"ما دلالة ﴿كلما﴾ في قوله: ﴿كلما خبت زدناهم سعيرًا﴾؟","answer":"تربط كل خبو بتجدد السعير، فتثبت دوام العذاب وتقطع رجاء انتهائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص194، تحت «براعة استعمال لفظ كلما في إثبات دوام العذاب»","url":""}]},{"id":"s17-225","number":225,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"لماذا أُوقعت زيادة السعير على أهل النار لا على النار؟","answer":"يوجه التعبير النظر إلى أثر الزيادة في المعذبين أنفسهم، فالمقصود ازدياد ما يلقونه من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص195، تحت «سر إيقاع الفعل على أهل النار لا على النار»","url":""}]},{"id":"s17-226","number":226,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"ما الفرق الذي يصوره لفظ ﴿خبت﴾ في قوله: ﴿كلما خبت﴾؟","answer":"الخبو سكون اللهب وضعفه لا انطفاؤه التام؛ فإذا خف سعيرها جُدد عليهم أشد منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص196، تحت «خبت وانطفأت»","url":""}]},{"id":"s17-178","number":178,"surah":17,"verses":[99],"references":[{"surah":17,"verses":[99]}],"verseLabel":"الإسراء: 99","question":"ما دلالة الاستدلال بخلق السماوات والأرض على بعث البشر؟","answer":"من قدر على الأعظم ابتداءً لا يعجز عن إعادة الأصغر بعد موته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص208، تحت «غرض الاستفهام في جملة أولم يروا»","url":""}]},{"id":"s17-179","number":179,"surah":17,"verses":[100],"references":[{"surah":17,"verses":[100]}],"verseLabel":"الإسراء: 100","question":"ما دلالة وصف الإنسان بأنه ﴿قَتُورًا﴾ بعد افتراض امتلاكه خزائن الرحمة؟","answer":"«قتورًا» يفيد المبالغة في التضييق والإمساك. ويبلغ التصوير غايته بافتراض امتلاك خزائن رحمة الله ثم الإمساك خوف النفاد؛ فتفضح المفارقة شدة الشح وسوء تصور سعة الرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص232، تحت «القتر والبخل»","url":""}]},{"id":"s17-180","number":180,"surah":17,"verses":[101],"references":[{"surah":17,"verses":[101]}],"verseLabel":"الإسراء: 101","question":"ما دلالة إبهام آيات موسى ثم تخصيصها بالعدد ﴿تسع آيات﴾؟","answer":"يجمع العدد الآيات الكثيرة في لفظ موجز ويستحضر تمامها، مع ترك تفصيلها لما هو معروف من قصتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص237، تحت «غرض إبهام الآيات والتخصيص بالعدد تسع»","url":""}]},{"id":"s17-227","number":227,"surah":17,"verses":[101],"references":[{"surah":17,"verses":[101]}],"verseLabel":"الإسراء: 101","question":"ما دلالة وصف آيات موسى بأنها ﴿بينات﴾؟","answer":"يبرز وضوح دلالتها على صدق موسى، ويبين أن جحود فرعون لم يكن لنقص البرهان بل للعناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص237، تحت «نكتة وصف الآيات بالبينات»","url":""}]},{"id":"s17-181","number":181,"surah":17,"verses":[102],"references":[{"surah":17,"verses":[102]}],"verseLabel":"الإسراء: 102","question":"ما دلالة وصف موسى لفرعون بأنه ﴿مَثْبُورًا﴾؟","answer":"المثبور الهالك المبعد عن الخير. قابل موسى اتهام فرعون له بأنه «مسحور» بوصف فرعون بأنه «مثبور»، تهديدًا بعاقبة عناده مع ظهور الآيات؛ فاجتمعت المقابلة في اللفظ والرد على باطل الاتهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص250، تحت «دلالة التعبير باسم المفعول مثبورًا»","url":""}]},{"id":"s17-182","number":182,"surah":17,"verses":[103],"references":[{"surah":17,"verses":[103]}],"verseLabel":"الإسراء: 103","question":"ما دلالة قول الله عن فرعون: ﴿فأراد أن يستفزهم من الأرض﴾؟","answer":"الاستفزاز إزعاج بعنف وخفة، فيصور محاولته اقتلاع بني إسرائيل من الأرض لا مجرد إخراج هادئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص253، تحت «نكتة استعمال لفظ يستفزهم»","url":""}]},{"id":"s17-228","number":228,"surah":17,"verses":[103],"references":[{"surah":17,"verses":[103]}],"verseLabel":"الإسراء: 103","question":"ما دلالة تعقيب إرادة فرعون بقوله: ﴿فأغرقناه ومن معه﴾؟","answer":"يقابل تدبيره لاقتلاع المؤمنين باقتلاعه هو وجنده، فارتد مكره عليه جزاءً من جنس قصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص255، تحت «براعة استعمال الفاء في الجزاء بالمقابلة»","url":""}]},{"id":"s17-183","number":183,"surah":17,"verses":[104],"references":[{"surah":17,"verses":[104]}],"verseLabel":"الإسراء: 104","question":"ما دلالة الأمر لبني إسرائيل: ﴿اسكنوا الأرض﴾ بعد هلاك فرعون؟","answer":"ينقلهم من الاستضعاف والتشريد إلى الاستقرار والتمكن، فيظهر تمام انقلاب الحال بعد النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص261، تحت «نكتة الأمر في الفعل اسكنوا»","url":""}]},{"id":"s17-229","number":229,"surah":17,"verses":[104],"references":[{"surah":17,"verses":[104]}],"verseLabel":"الإسراء: 104","question":"ما سر اختلاف الأمر بالسكن هنا عن الأمر بالدخول في موضع آخر؟","answer":"ناسب السكن مقام الاستقرار بعد زوال فرعون، أما الدخول فيتجه إلى ابتداء الانتقال إلى الأرض؛ فلكل تعبير سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص261، تحت «توجيه المتشابه اللفظي بين الأمر بالسكن والدخول»","url":""}]},{"id":"s17-230","number":230,"surah":17,"verses":[104],"references":[{"surah":17,"verses":[104]}],"verseLabel":"الإسراء: 104","question":"ما دلالة إطلاق ﴿وعد الآخرة﴾ بعد أمر بني إسرائيل بالسكن؟","answer":"يذكّر بأن استقرار الدنيا مؤقت، وأن الجمع النهائي والحساب يقعان عند مجيء وعد الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص263، تحت «فائدة الإطلاق في لفظ الآخرة»","url":""}]},{"id":"s17-184","number":184,"surah":17,"verses":[105],"references":[{"surah":17,"verses":[105]}],"verseLabel":"الإسراء: 105","question":"ما سر تكرار ﴿بِالْحَقِّ﴾ في قوله تعالى: ﴿وَبِالْحَقِّ أَنْزَلْنَاهُ وَبِالْحَقِّ نَزَلَ﴾؟","answer":"من وجوه التفريق أن الأول يقرر إنزاله بالحكمة والغاية الحق، والثاني يقرر اشتماله على الحق وسلامة وصوله من التغيير. ويذكر المصدر أيضًا وجه التأكيد؛ فتكرار اللفظ يثبت إحاطة الحق بإنزاله ونزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص270، تحت «معنى بالحق وسر تكرار لفظه»","url":""}]},{"id":"s17-185","number":185,"surah":17,"verses":[106],"references":[{"surah":17,"verses":[106]}],"verseLabel":"الإسراء: 106","question":"ما دلالة إيثار استعمال لفظ مكث في قوله تعالى: ﴿لِتَقْرَأَهُ عَلَى النَّاسِ عَلَى مُكْثٍ﴾؟","answer":"يدل المكث على التمهل والتثبت، ويلائم نزول القرآن مفرقًا ومراعاة أحوال الناس، ليتيسر تلقيه وحفظه وفهمه والعمل به مع تجدد الوقائع.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص290، تحت «إيثار استعمال لفظ مكث»","url":""}]},{"id":"s17-186","number":186,"surah":17,"verses":[107],"references":[{"surah":17,"verses":[107]}],"verseLabel":"الإسراء: 107","question":"ما سرّ التعبير بقوله تعالى: ﴿آمِنُوا بِهِ أَوْ لَا تُؤْمِنُوا﴾؟","answer":"الأمر هنا يفيد التهديد والتوبيخ، وفيه تسوية من جهة أن إيمانهم أو إعراضهم لا يغير حقيقة القرآن ولا يضر إلا المعرض نفسه. ثم يستشهد السياق بخشوع أهل العلم تعريضًا بجهل المكذبين وتسلية للنبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص299، تحت «بلاغة الأمر في قوله آمنوا به أو لا تؤمنوا»","url":""}]},{"id":"s17-187","number":187,"surah":17,"verses":[107],"references":[{"surah":17,"verses":[107]}],"verseLabel":"الإسراء: 107","question":"ما سر إيثار ﴿يخرون﴾ بدل يسجدون في وصف أهل العلم؟","answer":"يصور سرعة سقوطهم للسجود وشدة استجابتهم للقرآن، كأن الخشوع يسوقهم إلى الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص305، تحت «إيثار استخدام لفظ يخرون بدل يسجدون ويسقطون»","url":""}]},{"id":"s17-231","number":231,"surah":17,"verses":[107],"references":[{"surah":17,"verses":[107]}],"verseLabel":"الإسراء: 107","question":"ما سر إيثار ﴿الأذقان﴾ بدل الوجوه في تصوير سجودهم؟","answer":"يبالغ في تصوير تطامن الوجوه إلى الأرض؛ فالذقن أول ما يحاذيها عند الانحناء الشديد للسجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص308، تحت «نكتة إيثار لفظ الأذقان بدلًا من الوجوه»","url":""}]},{"id":"s17-188","number":188,"surah":17,"verses":[109],"references":[{"surah":17,"verses":[109]}],"verseLabel":"الإسراء: 109","question":"ما سر تكرار الخرور في قوله تعالى: ﴿وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ﴾؟","answer":"من توجيهات التكرار أنه خرور واحد أعيد للاهتمام بحالي السجود والبكاء، وهو الوجه المنقول عن ابن عاشور. ويذكر المصدر أيضًا حمله على اختلاف الحالين أو سببهما؛ فالتكرار يبرز عمق التأثر وتعدد مظاهر الخشوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص327، تحت «سر تكرار جملة ويخرون للأذقان»","url":""}]},{"id":"s17-189","number":189,"surah":17,"verses":[110],"references":[{"surah":17,"verses":[110]}],"verseLabel":"الإسراء: 110","question":"ما سر اختصاص اسمي ﴿الله﴾ و﴿الرحمن﴾ بالذكر؟","answer":"ليرد توهم المشركين تعدد المسمى بتعدد الاسم، ويقرر أن الاسمين وسائر الأسماء الحسنى لمسمى واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص340، تحت «سر اختصاص اسم الله واسم الرحمن بالذكر»","url":""}]},{"id":"s17-232","number":232,"surah":17,"verses":[110],"references":[{"surah":17,"verses":[110]}],"verseLabel":"الإسراء: 110","question":"ما سر تكرار ﴿ادعوا﴾ في قوله: ﴿ادعوا الله أو ادعوا الرحمن﴾؟","answer":"يسوّي بين الدعاء بالاسمين ويؤكد صحة التوجه بأي منهما، فلا يتعلق الحكم بلفظ واحد دون الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص342، تحت «سر تكرار ادعوا»","url":""}]},{"id":"s17-190","number":190,"surah":17,"verses":[110],"references":[{"surah":17,"verses":[110]}],"verseLabel":"الإسراء: 110","question":"ما دلالة الجمع بين النهي عن شدة الجهر والنهي عن شدة المخافتة؟","answer":"نُهي عن شدة الجهر حتى لا يثير ذلك المشركين ويزيد تصلبهم، وعن شدة الإسرار حتى يسمع المتهيئون للاهتداء؛ فطُلب طريق وسط يحقق المقصودين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص348، تحت «دلالة النهي في قوله ولا تجهر»","url":""}]},{"id":"s17-191","number":191,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سر افتتاح سورة الإسراء بالتسبيح وختامها بالحمد والتكبير؟","answer":"افتتحت السورة بتسبيح الله عند ذكر تكريم رسوله بالإسراء، وختمت بما يستدعيه ذلك من الحمد والتكبير. فيرد الختام على المطلع، وتنتظم أذكار التنزيه والثناء والتعظيم في أول السورة وآخرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص379، تحت «بلاغة رد العجز على الصدر بين ختام سورة الإسراء ومطلعها»","url":""}]},{"id":"s17-192","number":192,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سر وصف الله بالاسم الموصول في قوله: ﴿الحمد لله الذي لم يتخذ ولدًا﴾؟","answer":"يجعل صفات التنزيه الآتية صلةً معلومة تفسر استحقاقه الحمد الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص369، تحت «سر الوصف باسم الموصول»","url":""}]},{"id":"s17-233","number":233,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سر تقديم نفي الولد على نفي الشريك والولي؟","answer":"بدأ بأشد دعاوى المشركين مساسًا بالتوحيد، ثم أتبعها بنفي المشاركة في الملك ونفي الحاجة إلى النصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص370، تحت «سر تقديم جملة لم يتخذ ولدًا على ما بعدها»","url":""}]},{"id":"s17-234","number":234,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما دلالة قيد ﴿من الذل﴾ في نفي الولي؟","answer":"ينفي اتخاذ ولي ينشأ عن ضعف أو احتياج، أما ولاية الله لعباده المؤمنين فهي فضل ورحمة لا افتقارًا إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص376، تحت «فائدة قيد الجار والمجرور من الذل»","url":""}]},{"id":"s17-193","number":193,"surah":17,"verses":[111],"references":[{"surah":17,"verses":[111]}],"verseLabel":"الإسراء: 111","question":"ما سرّ التعبير بـ﴿وَكَبِّرْهُ تَكْبِيرًا﴾؟","answer":"أُكد الأمر بالمصدر للمبالغة في تعظيم الله وتنزيهه عن كل ما لا يليق بكماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص378، تحت «فائدة التعبير بالمصدر والإتيان به من جنس المأمور به»","url":""}]},{"id":"s17-235","number":235,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما سر الإشارة بـ«هذا» الدالة على القريب في قوله: ﴿إِنَّ هَٰذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ﴾، وبـ«ذلك» في البقرة: ﴿ذَٰلِكَ الْكِتَابُ﴾؟","answer":"أشار في البقرة بـ«ذلك» ليدل على علوّ الكتاب وبُعده عن الريب وأنه بعيد المنال عن أن يُؤتى بمثله. أما في الإسراء فالكلام في هداية الناس ومعرفتهم به وبأحكامه، فانبغى أن يكون قريبًا منهم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص7.","url":""}]},{"id":"s17-236","number":236,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما دلالة التعبير بالإعراض في قوله: ﴿وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ابْتِغَاءَ رَحْمَةٍ مِّن رَّبِّكَ﴾ دون التولّي؟","answer":"الإعراض أخفّ من التولّي، فالتولّي فيه إدبار، ولو لم يكن معه إدبار فهو أشد من الإعراض. ولما كان المعرَض عنهم ذوي القربى والمساكين وابن السبيل جاء باللفظ الأخفّ، وأتبعه بقوله: ﴿فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص247.","url":""}]},{"id":"s17-237","number":237,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما سر زيادة قوله: ﴿فَلَا يُسْرِف فِّي الْقَتْلِ﴾ في الإسراء، والاقتصار في الأنعام على النهي عن قتل النفس؟","answer":"النهي عن الإسراف في القتل متناسق مع النهي عن التبذير في الأموال الذي سبقه في السورة، ثم إن هذا التبسّط ملائم لسياق التفصيل في الإسراء، كما أن الإيجاز ملائم لسياق الأنعام.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص285.","url":""}]},{"id":"s17-238","number":238,"surah":17,"verses":[34],"references":[{"surah":17,"verses":[34]}],"verseLabel":"الإسراء: 34","question":"ما سر تقديم الفعل في قوله: ﴿وَأَوْفُوا بِالْعَهْدِ﴾، وتقديم الجار والمجرور في الأنعام: ﴿وَبِعَهْدِ اللَّهِ أَوْفُوا﴾؟","answer":"التقديم في الأنعام للاهتمام والعناية، لأنه أضاف العهد إلى الله فازداد تفخيمًا وكان أدعى إلى تقديمه. ولم يُضف العهد في آية الإسراء إلى الله.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص287.","url":""}]},{"id":"s17-239","number":239,"surah":17,"verses":[34,35],"references":[{"surah":17,"verses":[34,35]}],"verseLabel":"الإسراء: 34، 35","question":"ما سر تقديم الوفاء بالعهد على إيفاء الكيل في الإسراء، وعكسه في الأنعام؟","answer":"مرّ في الأنعام ذكر المفتقرين: ﴿مِّنْ إِمْلَاقٍ﴾، والفقراء أدعى إلى التطفيف لحاجتهم إلى المال، فقدّم الكيل والميزان. ومرّ في الإسراء ذكر الموسرين، فقدّم العهد، فوُضع كل تعبير في مكانه الأليق به.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص286.","url":""}]},{"id":"s17-240","number":240,"surah":17,"verses":[35],"references":[{"surah":17,"verses":[35]}],"verseLabel":"الإسراء: 35","question":"ما فائدة التقييد في قوله: ﴿وَأَوْفُوا الْكَيْلَ إِذَا كِلْتُمْ﴾؟","answer":"هذه الزيادة متناسبة مع سياق التفصيل في الإسراء، ومعناها: أوفوا وقت الكيل نفسه ولا تؤخّروا شيئًا من الحق بأن يُكال بنقصان ثم يُوفى بعد. وهذا التوجيه منقول عن «البحر المحيط».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص286.","url":""}]},{"id":"s17-241","number":241,"surah":17,"verses":[49],"references":[{"surah":17,"verses":[49]}],"verseLabel":"الإسراء: 49","question":"ما سر قولهم في الإسراء: ﴿أَئِذَا كُنَّا عِظَامًا وَرُفَاتًا﴾، وفي المؤمنون وغيرها: ﴿أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا﴾؟","answer":"الرفات هو الفتات والحطام، فإذا بلي صار ترابًا، فالتراب والعظام أدلّ على البلى وبعثهما أغرب في عقول المنكرين. ولم يُذكر في الإسراء من إنكارهم غير هاتين الآيتين، أما حيث ذُكر التراب والعظام فقد اشتدّ العجب والاستبعاد، كإضافتهم الآباء الأولين.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص117–118.","url":""}]},{"id":"s17-242","number":242,"surah":17,"verses":[62],"references":[{"surah":17,"verses":[62]}],"verseLabel":"الإسراء: 62","question":"ما سر حذف الياء في قوله: ﴿لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ الْقِيَامَةِ﴾، وإثباتها في المنافقون: ﴿لَوْلَا أَخَّرْتَنِي﴾؟","answer":"تردّد فعل التأخير مرتين في سورة المنافقون، وذُكر مرة واحدة في الإسراء، فزاد الياء في موطن الزيادة وحذفها في موطن الاجتزاء بالكسرة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص88.","url":""}]},{"id":"s17-243","number":243,"surah":17,"verses":[83],"references":[{"surah":17,"verses":[83]}],"verseLabel":"الإسراء: 83","question":"ما سر إسناد الإنعام إلى الله وترك إسناد الشر إليه في قوله: ﴿وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ... وَإِذَا مَسَّهُ الشَّرُّ كَانَ يَئُوسًا﴾؟","answer":"القرآن يُسند الفعل إلى الله في مقام الخير والتفضل، ولا يذكر نفسه في الشر والسوء تنزيهًا له عن إرادة السوء، ففي النعمة أظهر نفسه فقال: «أنعمنا»، وفي الشر قال: «مسّه الشر» ولم يقل: «مسسناه بالشر».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص320.","url":""}]},{"id":"s17-244","number":244,"surah":17,"verses":[93],"references":[{"surah":17,"verses":[93]}],"verseLabel":"الإسراء: 93","question":"ما دلالة تعدية الإيمان باللام في قولهم: ﴿وَلَن نُّؤْمِنَ لِرُقِيِّكَ﴾؟","answer":"الإيمان بالله لا يُعدّى إلا بالباء، فإذا عُدّي باللام فهو لغير الله ومعناه التصديق، وأكثر ما يكون مع الأشخاص كقوله: ﴿لَن نُّؤْمِنَ لَكَ﴾. وجاء هنا مع غير الشخص وهو نادر، أي لن نصدّق برقيّك.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص75.","url":""}]},{"id":"s17-245","number":245,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر افتتاح السورة بالمصدر ﴿سُبْحَانَ﴾ دون الفعل؟","answer":"جاء بالمصدر من غير ذكر فاعل ولا زمن للإطلاق، أي إنه سبحانه أهل التسبيح ومستحقه سواء سبّحه أحد أم لا. وقد طبع هذا الافتتاح السورةَ بجوّ التسبيح، كقوله: ﴿وَإِن مِّن شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ﴾، وهو أعظم إطلاق في التسبيح يناسب الإطلاق في أولها. وقد حُفّت السورة بتسبيح في أول النحل وتحميد في أول الكهف.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص203–204.","url":""}]},{"id":"s17-246","number":246,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما دلالة التعبير بقوله: ﴿بِعَبْدِهِ﴾ دون اسم النبي ﷺ أو وصفه بالرسالة؟","answer":"ليدلّ على أن أعظم الخلق عبدٌ لله فلا يُدّعى له فوق مقام العبودية، وعلى أن العبودية أعلى مقام للخلق. ولما ذُكر موسى عند المناجاة باسمه خرّ صعقًا، ولما ذُكر محمد ﷺ بالعبودية عُرج به. وفي إضافته إلى ضميره تشريف آخر وحفظ، فإن السيد يحمي عبده.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص204–205.","url":""}]},{"id":"s17-247","number":247,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر قوله: ﴿بَارَكْنَا حَوْلَهُ﴾ بإسناد المباركة إلى نفسه، وبـ«حوله» دون «ما حوله»؟","answer":"أسند المباركة إلى ذاته ولم يقل: «بورك حوله» للدلالة على عظم هذه المباركة، وأطلقها لتشمل البركة الروحية بإرسال الرسل والمادية بالخير والرزق. وقال «حوله» لا «ما حوله» لئلا تقتصر البركة على أشياء معينة تزول بزوالها، فالظرفية ملازمة للمسجد والبركة ملازمة للظرفية.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص206–207.","url":""}]},{"id":"s17-248","number":248,"surah":17,"verses":[1],"references":[{"surah":17,"verses":[1]}],"verseLabel":"الإسراء: 1","question":"ما سر الالتفات إلى التكلم في قوله: ﴿بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا﴾ بعد الغيبة، وما دلالة «مِن»؟","answer":"كان المظنون «بارك حوله ليريه»، فالتفت ليدل على أن المتكلم هو الله وليس إخبارًا عنه. واللام في «لنريه» تدل على أن أفعاله معلّلة وأن للرحلة غاية. وقال «من آياتنا» ليدل على أنه أراه بعض آياته، كقوله: ﴿لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى﴾، وأضافها إلى نفسه للدلالة على عظمها.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص207–208.","url":""}]},{"id":"s17-249","number":249,"surah":17,"verses":[23],"references":[{"surah":17,"verses":[23]}],"verseLabel":"الإسراء: 23","question":"ما سر التبسّط في الإحسان إلى الوالدين في الإسراء: ﴿فَلَا تَقُل لَّهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا﴾، والاقتصار في الأنعام على ﴿وَبِالْوَالِدَيْنِ إِحْسَانًا﴾؟","answer":"بُنيت الوصايا في الأنعام على الإيجاز والاختصار، وفي الإسراء على التوضيح والتفصيل، فتبسّط في ذكر إحسان معاملتهما وترك الإساءة إليهما والدعاء لهما. وكذلك فصّل في التوحيد، فنهى عن الشرك ثم أمر بتخصيص الله بالعبادة: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص280–282.","url":""}]},{"id":"s17-250","number":250,"surah":17,"verses":[31],"references":[{"surah":17,"verses":[31]}],"verseLabel":"الإسراء: 31","question":"ما سر تقديم رزق الأبناء في قوله: ﴿خَشْيَةَ إِمْلَاقٍ نَّحْنُ نَرْزُقُهُمْ وَإِيَّاكُمْ﴾، وتقديم رزق الآباء في الأنعام: ﴿مِّنْ إِمْلَاقٍ نَّحْنُ نَرْزُقُكُمْ وَإِيَّاهُمْ﴾؟","answer":"الخطاب في الأنعام للفقراء الذين نزل بهم الإملاق، فبدأ بوعدهم بالرزق. وفي الإسراء للموسرين الذين يخشون الفقر من كُلَف الأولاد، فبدأ بضمان رزق الأولاد ليأمنوا ما خافوه. ووُضعت الآية في سياق الموسرين، فقد سبقها الأمر بإيتاء ذي القربى والنهي عن التبذير. وفي «البحر المحيط» نحو هذا التوجيه.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص64، ص282–283.","url":""}]},{"id":"s17-251","number":251,"surah":17,"verses":[31],"references":[{"surah":17,"verses":[31]}],"verseLabel":"الإسراء: 31","question":"ما سر زيادة قوله: ﴿إِنَّ قَتْلَهُمْ كَانَ خِطْئًا كَبِيرًا﴾ في الإسراء دون الأنعام؟","answer":"قتل الموسرين أولادهم خشيةَ فقرٍ لم يقع أعظم جرمًا من قتل المفتقرين الذين ليس عندهم ما يعولون به أولادهم، وكلاهما مرتكب كبيرة، لكن هذا أشدّ، فوَصفه بأنه خطأ كبير.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص284.","url":""}]},{"id":"s17-252","number":252,"surah":17,"verses":[32],"references":[{"surah":17,"verses":[32]}],"verseLabel":"الإسراء: 32","question":"ما سر توسيط النهي عن الزنى: ﴿وَلَا تَقْرَبُوا الزِّنَىٰ﴾ بين النهي عن قتل الأولاد والنهي عن قتل النفس؟","answer":"الزنى داعٍ إلى قتل الأولاد غير الشرعيين أو نبذهم للتخلص منهم، فتدرّج التعبير من قتل الأولاد بسبب الفقر إلى قتلهم بسبب الفاحشة إلى قتل النفس عمومًا. وفي «روح المعاني» أن الزنى تضييع للأنساب، ومن لم يثبت نسبه ميتٌ حكمًا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص284–285.","url":""}]},{"id":"s17-253","number":253,"surah":17,"verses":[89],"references":[{"surah":17,"verses":[89]}],"verseLabel":"الإسراء: 89","question":"ما سر تقديم «للناس» في قوله: ﴿وَلَقَدْ صَرَّفْنَا لِلنَّاسِ فِي هَٰذَا الْقُرْآنِ﴾، وتأخيره في الكهف، وما سر الختم بـ﴿كُفُورًا﴾؟","answer":"تقدّم في الإسراء الكلام على الإنسان ونعم الله عليه، وبُدئت السورة بالكلام على الناس قبل القرآن، فناسب تقديم الناس؛ وبُدئت الكهف بالكلام على الكتاب. والكفور جحد النعم، فناسب تقدّم ذكر النعمة والرحمة، أما الكهف فخُتمت بالجدل لما فيها من المحاورات.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص70–71.","url":""}]},{"id":"s17-254","number":254,"surah":17,"verses":[97],"references":[{"surah":17,"verses":[97]}],"verseLabel":"الإسراء: 97","question":"ما سر حذف الياء في قوله: ﴿وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ﴾، وإثباتها في الأعراف: ﴿فَهُوَ الْمُهْتَدِي﴾؟","answer":"تردّد لفظ الهداية في الأعراف سبع عشرة مرة، أكثر مما في الإسراء والكهف مجتمعتين (ثماني مرات في الإسراء وست في الكهف)، فلما زادت ألفاظ الهداية في الأعراف زاد لفظ «المهتدي»، واجتزأ بالكسرة في الإسراء.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص87–88.","url":""}]},{"id":"s18-1","number":1,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما دلالة افتتاح سورة الكهف بالجملة الخبرية ﴿الْحَمْدُ لِلَّهِ﴾؟","answer":"تثبت الجملة الحمد لله ثبوتًا مستقرًا دائمًا، وتؤدي في الوقت نفسه معنى إنشاء الثناء عليه. وافتتاح السورة بها يلفت إلى أن إنزال الكتاب من أعظم النعم التي يستحق الله عليها الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص399، تحت «بلاغة الجملة الخبرية ودلالتها في قوله ﴿الْحَمْدُ لِلَّهِ﴾»","url":""}]},{"id":"s18-213","number":213,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما سر تقديم لفظ ﴿الْحَمْدُ﴾ على اسم الله في افتتاح سورة الكهف؟","answer":"قُدِّم الحمد لأن المقام مقام ثناء على نعمة إنزال القرآن، فبدأ بما هو موضع العناية في السياق، ثم ذُكر المستحق له وهو الله جل جلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص400، تحت «بلاغة تقديم لفظ الحمد على الاسم الجليل»","url":""}]},{"id":"s18-214","number":214,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما دلالة وصف الله بالاسم الموصول في قوله: ﴿الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ﴾؟","answer":"تربط صلة الموصول استحقاق الله للحمد بإنزال الكتاب، فتُعظِّم نعمة القرآن وتذكّر بالمنعم بها، وتبين أن هذه النعمة سبب ظاهر للحمد والثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص401-402، تحت «نكتة التعبير بالموصول في قوله تعالى: ﴿الَّذِي﴾»","url":""}]},{"id":"s18-2","number":2,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما سرّ التعبير بـ﴿عَلَى عَبْدِهِ﴾ دون «على رسوله»؟","answer":"وصفه بالعبودية تنويهٌ بمنزلته ورفعٌ لقدره بإنزال الكتاب عليه، مع تقرير أنه مهما علت منزلته فهو عبد لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص404، تحت «إيثار لفظ العبودية في قوله عبده»","url":""}]},{"id":"s18-3","number":3,"surah":18,"verses":[1],"references":[{"surah":18,"verses":[1]}],"verseLabel":"الكهف: 1","question":"ما سرّ تقديم نفي العوج في ﴿وَلَمْ يَجْعَلْ لَهُ عِوَجًا﴾ على وصف الكتاب بـ﴿قَيِّمًا﴾؟","answer":"نُفي عنه الخلل والميل أولًا، ثم أُثبت له كمال الاستقامة والاعتدال؛ فجمع سلامته من النقص وثبوت الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص414، تحت «فائدة ذكر قيمًا عقيب قوله ولم يجعل له عوجًا»","url":""}]},{"id":"s18-4","number":4,"surah":18,"verses":[1,2],"references":[{"surah":18,"verses":[1,2]}],"verseLabel":"الكهف: 1-2","question":"ما دلالة الجمع بين نفي العوج ووصف الكتاب بأنه ﴿قَيِّمًا﴾؟","answer":"لأن نفي العوج يثبت خلوه من الخلل والتناقض، ووصفه بالقيم يثبت استقامته وقيامه بمصالح العباد؛ فليس الوصفان تكرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص415، تحت «دلالة الطباق بين العوج المنفي والقيم المثبت»","url":""}]},{"id":"s18-5","number":5,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما دلالة وصف البأس بأنه ﴿شَدِيدًا﴾؟","answer":"لتهويل الوعيد وبيان عظم هذا البأس وقوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص419، تحت «نكتة وصف البأس بالشدة»","url":""}]},{"id":"s18-215","number":215,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما سرّ التعبير بـ﴿مِنْ لَدُنْهُ﴾ في وصف البأس؟","answer":"ليدل على أن البأس صادر من عند الله، ولفظ ﴿لدن﴾ أخص في معنى القرب والصدور من ﴿عند﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص421، تحت «سر إيثار لفظ لدنه»","url":""}]},{"id":"s18-6","number":6,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما سرّ تقديم الإنذار على البشارة؟","answer":"لأن المقام مقام إنذار المعاندين، ودفع المفسدة مقدّم على جلب المصلحة؛ فكان الإنذار هو الغرض الأهم في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص418، تحت «نكتة تقديم الإنذار على التبشير»","url":""}]},{"id":"s18-7","number":7,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما دلالة وصف أجر المؤمنين بأنه ﴿حَسَنًا﴾؟","answer":"وصف الأجر بالحسن يجمع ما فيه من البهجة والنفع والخلو من القبح، والمراد به نعيم الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص428، تحت «نكتة وصف الأجر بالحسن في قوله أجرًا حسنًا»","url":""}]},{"id":"s18-8","number":8,"surah":18,"verses":[3],"references":[{"surah":18,"verses":[3]}],"verseLabel":"الكهف: 3","question":"ما سرّ التعبير عن أهل الجنة بأنهم ﴿مَاكِثِينَ فِيهِ﴾؟","answer":"ليدل على استقرارهم وإقامتهم في النعيم من غير انتقال عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص428، تحت «إيثار لفظ ماكثين دون غيره من مرادفاته»","url":""}]},{"id":"s18-216","number":216,"surah":18,"verses":[3],"references":[{"surah":18,"verses":[3]}],"verseLabel":"الكهف: 3","question":"ما دلالة تقييد مكث أهل الجنة بقوله ﴿أَبَدًا﴾؟","answer":"يفيد دوام مكثهم في النعيم بلا انتهاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص430، تحت «فائدة الظرف أبدًا»","url":""}]},{"id":"s18-9","number":9,"surah":18,"verses":[4],"references":[{"surah":18,"verses":[4]}],"verseLabel":"الكهف: 4","question":"ما سر تخصيص القائلين ﴿اتَّخَذَ اللَّهُ وَلَدًا﴾ بإنذار بعد الإنذار العام؟","answer":"للتنبيه على فظاعة هذه المقالة وعظم استحقاقها للوعيد؛ فعُطف الخاص على العام اهتمامًا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص436، تحت «نكتة تخصيص الذين قالوا اتخذ الله ولدًا بالإنذار»","url":""}]},{"id":"s18-10","number":10,"surah":18,"verses":[5],"references":[{"surah":18,"verses":[5]}],"verseLabel":"الكهف: 5","question":"ما سرّ التعبير بـ﴿كَبُرَتْ كَلِمَةً﴾ دون «عظمت»؟","answer":"اختير ﴿كبرت﴾ للدلالة على عظم الذنب وشدة قبح المقالة، وجاءت الصيغة للتعجب من شناعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص447، تحت «إيثار لفظ كبرت على ما يقاربه من ألفاظ»","url":""}]},{"id":"s18-11","number":11,"surah":18,"verses":[5],"references":[{"surah":18,"verses":[5]}],"verseLabel":"الكهف: 5","question":"ما سرّ التعبير بـ﴿تَخْرُجُ مِنْ أَفْوَاهِهِمْ﴾؟","answer":"للدلالة على أنها مقولة لا مصدر لها إلا التلفظ بالأفواه، ولا تقوم على علم أو حقيقة يعقلها العقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص448، تحت «إيثار لفظ تخرج دون ما يقاربه»","url":""}]},{"id":"s18-12","number":12,"surah":18,"verses":[5],"references":[{"surah":18,"verses":[5]}],"verseLabel":"الكهف: 5","question":"ما دلالة حصر قولهم في الكذب بقوله تعالى: ﴿إِنْ يَقُولُونَ إِلَّا كَذِبًا﴾؟","answer":"لنفي كل وصف عن مقالتهم إلا الكذب، مع تأكيد النفي بأسلوب النفي والاستثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص450، تحت «بلاغة القصر في حصر قولهم بالكذب»","url":""}]},{"id":"s18-13","number":13,"surah":18,"verses":[6],"references":[{"surah":18,"verses":[6]}],"verseLabel":"الكهف: 6","question":"ما سرّ التعبير بـ﴿فَلَعَلَّكَ بَاخِعٌ نَفْسَكَ﴾؟","answer":"البخع بلوغ الحزن بالنفس إلى الهلاك؛ والتعبير يصور شدة حرص النبي ﷺ على إيمانهم، وفيه تسلية ونهي عن استهلاك النفس حزنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص456، تحت «سر إيثار باخع على هيئة اسم الفاعل»","url":""}]},{"id":"s18-14","number":14,"surah":18,"verses":[6],"references":[{"surah":18,"verses":[6]}],"verseLabel":"الكهف: 6","question":"ما سرّ إطلاق ﴿هَذَا الْحَدِيثِ﴾ على القرآن؟","answer":"الحديث كلام وخبر، ومن توجيهات إطلاقه على القرآن تجدد نزوله واشتماله على الأخبار والقصص. واسم الإشارة القريب يستحضر وضوحه وحضوره في الأسماع، فيزيد التعجيب من إعراضهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص459، تحت «نكتة إطلاق لفظ الحديث على القرآن»","url":""}]},{"id":"s18-15","number":15,"surah":18,"verses":[7],"references":[{"surah":18,"verses":[7]}],"verseLabel":"الكهف: 7","question":"ما سرّ التعبير بـ﴿زِينَةً لَهَا﴾ دون «زينة لكم»؟","answer":"جُعل ما على الأرض زينةً للأرض نفسها، فيجمع التعبير الامتنان بجمال المخلوقات والتنبيه إلى أنها موضع ابتلاء زائل، لا ملك ثابت للإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص467، تحت «فائدة التقييد بشبه الجملة لها»","url":""}]},{"id":"s18-16","number":16,"surah":18,"verses":[8],"references":[{"surah":18,"verses":[8]}],"verseLabel":"الكهف: 8","question":"ما سرّ التعبير بـ﴿صَعِيدًا جُرُزًا﴾؟","answer":"يصوّر انقلاب زينة الأرض إلى أرض مستوية جافة أجرد لا نبات فيها؛ فتكتمل صورة فناء الحياة وزينتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص475، تحت «إيثار لفظ صعيدًا جرزًا»","url":""}]},{"id":"s18-17","number":17,"surah":18,"verses":[9],"references":[{"surah":18,"verses":[9]}],"verseLabel":"الكهف: 9","question":"ما سرّ التعبير بـ﴿أَمْ حَسِبْتَ﴾ دون «أفظننت»؟","answer":"لأن الحسبان هنا أدنى درجة من الظن وليس اعتقادًا راجحًا؛ فناسب إنكار أدنى توهم أن أصحاب الكهف غاية العجب، كما أن لفظ الحسبان يلائم ما في القصة من حساب مدة لبثهم وعددهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص482، تحت «سر إيثار الحسبان دون الظن»","url":""}]},{"id":"s18-18","number":18,"surah":18,"verses":[9],"references":[{"surah":18,"verses":[9]}],"verseLabel":"الكهف: 9","question":"ما سرّ تقديم ﴿مِنْ آيَاتِنَا﴾ على ﴿عَجَبًا﴾؟","answer":"لأن الأهم نفي أن تكون قصتهم بالقياس إلى آيات الله هي العجب البالغ؛ فقُدّم تعلقها بآيات الله قبل وصفها بالعجب، وفي ذلك ردّ تهويل السائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص485، تحت «سر تقديم الجار والمجرور على عجبًا»","url":""}]},{"id":"s18-19","number":19,"surah":18,"verses":[9],"references":[{"surah":18,"verses":[9]}],"verseLabel":"الكهف: 9","question":"ما دلالة الجمع بين ﴿الْكَهْفِ وَالرَّقِيمِ﴾ في التعريف بأصحاب القصة؟","answer":"يقترن أصحاب القصة بالكهف الذي لازموه وبالرقيم الذي تعددت الأقوال فيه: فقيل لوح كتب فيه خبرهم، وقيل اسم موضع. ويناقش المصدر أيضًا هل أصحاب الكهف والرقيم طائفة واحدة أم طائفتان؛ لذلك لا يصح الجزم بوجه واحد على أنه المعنى الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص483، 484، تحت «دلالة والرقيم ومعنى العطف»","url":""}]},{"id":"s18-20","number":20,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما سر إظهار لفظ ﴿الْفِتْيَةُ﴾ بدل الإضمار؟","answer":"للتنبيه على حداثة سنهم وقوة إيمانهم مع الشباب، وفي إظهار الاسم عناية بموضع العبرة في حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص490، 491، تحت «نكتة الإظهار في مقام الإضمار والتعبير بالفتية»","url":""}]},{"id":"s18-21","number":21,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما دلالة حذف حرف النداء في دعاء الفتية: ﴿رَبَّنَا آتِنَا﴾؟","answer":"حذف حرف النداء يصور قربهم من ربهم واستبطانهم عظمته؛ فلا يحتاجون إلى أداة تنبيه في مناجاته. أما مبادرتهم بالدعاء عقب الإيواء إلى الكهف فتظهرها الفاء في ﴿فَقَالُوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص492، تحت «بلاغة الحذف في ربنا آتنا»","url":""}]},{"id":"s18-22","number":22,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما سرّ التعبير بـ﴿مِنْ لَدُنْكَ رَحْمَةً﴾؟","answer":"طلبوا رحمة خاصة من عند الله تعظم حاجتهم إليها، وتقديم ﴿مِنْ لَدُنْكَ﴾ يبرز اختصاصها به وقوة رغبتهم فيها. و«لدن» تؤكد صدورها من عنده، مع تنكير الرحمة للتعظيم والتنوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص493، تحت «نكتة إيثار التعبير بلَدُنك على عندك»","url":""}]},{"id":"s18-23","number":23,"surah":18,"verses":[10],"references":[{"surah":18,"verses":[10]}],"verseLabel":"الكهف: 10","question":"ما سرّ تقديم ﴿لَنَا﴾ في ﴿وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا﴾؟","answer":"للاهتمام بحاجتهم إلى المطلوب وإبراز أنه المرغوب لهم قبل بيان الأمر الذي يطلبون تهيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص496، تحت «سر تقديم لنا على من أمرنا»","url":""}]},{"id":"s18-24","number":24,"surah":18,"verses":[11],"references":[{"surah":18,"verses":[11]}],"verseLabel":"الكهف: 11","question":"ما سرّ التعبير بـ﴿فَضَرَبْنَا عَلَى آذَانِهِمْ﴾ بدل «أنمناهم»؟","answer":"هو كناية عن إلقاء نوم ثقيل حُجب معه السمع؛ وخصت الآذان لأن السمع هو الطريق المعتاد لتنبه النائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص501، تحت «بلاغة الكناية في الضرب على الآذان»","url":""}]},{"id":"s18-25","number":25,"surah":18,"verses":[11],"references":[{"surah":18,"verses":[11]}],"verseLabel":"الكهف: 11","question":"ما سرّ التعبير بـ﴿سِنِينَ عَدَدًا﴾؟","answer":"من توجيهات «عددًا» أنه وصف للسنين يفيد كثرتها وطول اللبث، مع إجمال المقدار هنا. ويذكر المصدر أيضًا وجه التقليل بالنظر إلى قدرة الله؛ فالتكثير تفسير معتبر وليس الوجه الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص504، تحت «دلالة التعبير بلفظ عددًا»","url":""}]},{"id":"s18-26","number":26,"surah":18,"verses":[12],"references":[{"surah":18,"verses":[12]}],"verseLabel":"الكهف: 12","question":"ما سرّ التعبير بـ﴿ثُمَّ بَعَثْنَاهُمْ﴾؟","answer":"استُعمل البعث في إيقاظهم بعد سكون النوم الطويل؛ فهو تحريك وإقامة من حال الرقاد، وأسند إلى ضمير العظمة لعجيب القدرة الظاهرة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص507، تحت «جمال الاستعارة في التعبير عن الإيقاظ بالبعث»","url":""}]},{"id":"s18-27","number":27,"surah":18,"verses":[12],"references":[{"surah":18,"verses":[12]}],"verseLabel":"الكهف: 12","question":"ما سرّ التعبير بـ﴿أَيُّ الْحِزْبَيْنِ أَحْصَى﴾؟","answer":"المعنى ظهور ما يعلمه الله في الواقع، لا حدوث علم بعد جهل. و«أحصى» تحتمل فعلًا ماضيًا بمعنى ضبط العدد، واسم تفضيل بمعنى أشد ضبطًا؛ فالسياق يميز إصابة التقدير من القول المبني على التخمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص509، تحت «بلاغة الكناية في لفظ العلم»","url":""}]},{"id":"s18-28","number":28,"surah":18,"verses":[13],"references":[{"surah":18,"verses":[13]}],"verseLabel":"الكهف: 13","question":"ما سرّ التعبير بـ﴿نَحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُمْ بِالْحَقِّ﴾؟","answer":"لقصر القصص الحق على خبر الله ونفي التخمينات؛ فالمقصود بيان الصدق ومواضع العبرة من القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص518، تحت «سر تقييد القص بقوله بالحق»","url":""}]},{"id":"s18-29","number":29,"surah":18,"verses":[13],"references":[{"surah":18,"verses":[13]}],"verseLabel":"الكهف: 13","question":"ما سرّ التعبير بـ﴿إِنَّهُمْ فِتْيَةٌ آمَنُوا﴾؟","answer":"افتتحت الجملة بـ﴿إن﴾ للاهتمام بخبرهم، ووصفوا بالفتية تعريفًا بحالهم، ثم ذُكرت زيادة هداهم بما وهبهم الله من التوفيق والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص518، تحت «نكتة تصدير الجملة بأداة التوكيد»","url":""}]},{"id":"s18-30","number":30,"surah":18,"verses":[14],"references":[{"surah":18,"verses":[14]}],"verseLabel":"الكهف: 14","question":"ما سرّ التعبير بـ﴿وَرَبَطْنَا عَلَى قُلُوبِهِمْ﴾؟","answer":"الربط استعارة لتثبيت إيمانهم وإزالة التردد والاضطراب عن قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص525، تحت «جمال الاستعارة وربطنا»","url":""}]},{"id":"s18-31","number":31,"surah":18,"verses":[14],"references":[{"surah":18,"verses":[14]}],"verseLabel":"الكهف: 14","question":"ما فائدة الإخبار عن المسند إليه برب السماوات والأرض في قوله تعالى: ﴿رَبُّنَا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"أثبتوا أن ربهم هو رب السماوات والأرض، فجاء الوصف كاشفًا لعموم ربوبيته، وبُني عليه امتناعهم من دعاء غيره إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص527، تحت «فائدة الإخبار عن المسند إليه برب السماوات والأرض»","url":""}]},{"id":"s18-32","number":32,"surah":18,"verses":[15],"references":[{"surah":18,"verses":[15]}],"verseLabel":"الكهف: 15","question":"ما سرّ وصف الشرك بأنه ﴿شَطَطًا﴾؟","answer":"الشطط الإفراط في مخالفة الحق والصواب، واستعير من البعد؛ فدعاء غير الله قول بالغ البعد عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص531، تحت «دلالة لفظ شططًا وبلاغته»","url":""}]},{"id":"s18-33","number":33,"surah":18,"verses":[15],"references":[{"surah":18,"verses":[15]}],"verseLabel":"الكهف: 15","question":"ما دلالة مطالبة قومهم بـ﴿سُلْطَانٍ بَيِّنٍ﴾ على اتخاذ الآلهة؟","answer":"للتبكيت وإظهار أن اتخاذ الآلهة قام بلا حجة؛ فالسلطان هو البرهان، والبين واضح الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص538، تحت «نكتة تنكير سلطان ووصفه ببين»","url":""}]},{"id":"s18-34","number":34,"surah":18,"verses":[16],"references":[{"surah":18,"verses":[16]}],"verseLabel":"الكهف: 16","question":"ما دلالة قول الفتية بعضهم لبعض: ﴿فَأْوُوا إِلَى الْكَهْفِ﴾ بعد اعتزال القوم؟","answer":"كان ذلك نصحًا ومشورة بعد اليأس من رجوع قومهم، فانتقلوا من إعلان المفاصلة إلى اتخاذ الكهف مأوى يحفظ دينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص550، تحت «دلالة الأمر في فعل الإيواء»","url":""}]},{"id":"s18-35","number":35,"surah":18,"verses":[16],"references":[{"surah":18,"verses":[16]}],"verseLabel":"الكهف: 16","question":"ما سرّ التعبير بـ﴿يَنْشُرْ لَكُمْ رَبُّكُمْ مِنْ رَحْمَتِهِ﴾؟","answer":"صوّر سعة الرحمة وبسطها بصورة نشر الثوب المطوي؛ فالكهف وإن ضاق فقد يتسع لهم بلطف الله. وفي صيغة الجزم ثقة بوعده وحسن ظن برعايته لمن لجأ إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص553، تحت «براعة الاستعارة في ينشر لكم»","url":""}]},{"id":"s18-36","number":36,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما مناسبة تفصيل حركة الشمس لما سبق من إيواء الفتية إلى الكهف؟","answer":"جاء التفصيل ليكشف صورة العناية الإلهية بهم بعد دخولهم الكهف؛ فقد وصلهم من الضوء والهواء ما ينفعهم، وصُرف عنهم من حر الشمس ما يؤذي أجسادهم في نومهم الطويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص560، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s18-217","number":217,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما دلالة التعبير بالمضارع في قوله: ﴿وَتَرَى الشَّمْسَ﴾؟","answer":"يستحضر المضارع صورة الشمس وهي تتحرك حول الكهف عند الطلوع والغروب، حتى يبدو المشهد متجددًا حاضرًا يراه السامع بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص566، تحت «نكتة التعبير بالمضارع في قوله تعالى: ﴿وَتَرَى﴾»","url":""}]},{"id":"s18-218","number":218,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما سر التعبير بالفعل ﴿تَزَاوَرُ﴾ عن حركة الشمس عند الكهف؟","answer":"يصوّر الفعل الشمس كأنها تميل وتنحرف عن موضع الفتية، فيجسّد حركة الضوء حول الكهف ويبرز حفظهم من حرها مع انتفاعهم بنورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص567، تحت «وجه التعبير بالفعل ﴿تَزَاوَرُ﴾ دون غيره»","url":""}]},{"id":"s18-37","number":37,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما سرّ الإشارة بالبعيد في قوله ﴿ذَلِكَ مِنْ آيَاتِ اللَّهِ﴾؟","answer":"اسم الإشارة البعيد يعظم ما سبق من عجيب حال الشمس وحفظ الفتية.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص574، تحت «سر التعبير باسم الإشارة ذلك»","url":""}]},{"id":"s18-219","number":219,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما دلالة ﴿مِنْ﴾ في قوله ﴿ذَلِكَ مِنْ آيَاتِ اللَّهِ﴾؟","answer":"تفيد أن هذا المشهد بعض آيات الله، فلا تنحصر دلائل قدرته فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص575، تحت «دلالة من في قوله ذلك من آيات الله»","url":""}]},{"id":"s18-38","number":38,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما سرّ التعبير بـ﴿وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ﴾؟","answer":"لأن هيئتهم كانت تشبه حال اليقظة مع ثبوت رقادهم، فجاء التعبير تعجيبًا من حالهم وبيانًا لعظيم قدرة الله في شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص596، تحت «وجه حسبانهم أيقاظًا مع أنهم رقود»","url":""}]},{"id":"s18-39","number":39,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما سر التعبير بـ﴿وَنُقَلِّبُهُمْ﴾ في وصف حال الفتية أثناء نومهم؟","answer":"التقليب تغيير الجسد من جانب إلى جانب، وهو أخص من مطلق الحركة وأنسب بحال النائم. وصيغة التفعيل والمضارع تستحضر تكرره خلال نومهم، مع إسناده إلى الله لإظهار عنايته بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص598، تحت «علة التعبير بالتقليب دون الحركة»","url":""}]},{"id":"s18-40","number":40,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما دلالة كون كلبهم ﴿بَاسِطًا ذِرَاعَيْهِ بِالْوَصِيدِ﴾؟","answer":"يرسم التعبير الكلب في هيئة الحارس عند مدخل الكهف، وتثبت الجملة الاسمية بقاء تلك الهيئة. ومن توجيه «الوصيد» أنه مدخل الكهف المشبه بالباب أو فناؤه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص601، تحت «دلالة وصف الكلب ببسط ذراعيه»","url":""}]},{"id":"s18-41","number":41,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما دلالة تصوير الخوف من أصحاب الكهف بقوله: ﴿وَلَمُلِئْتَ مِنْهُمْ رُعْبًا﴾؟","answer":"صُورت النفس كوعاء يملؤه الرعب، فدل التعبير على استيلاء الخوف عليها. وذكر الملء بعد الفرار يصور استمرار الرعب حتى بعد الابتعاد عنهم، مع تكرار «منهم» لتأكيد هول المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص606، تحت «بلاغة الاستعارة في ولملئت منهم رعبًا»","url":""}]},{"id":"s18-42","number":42,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ بَعَثْنَاهُمْ﴾؟","answer":"أي كما أنمناهم تلك القرون بعثناهم؛ فالإفاقة آية على عظيم قدرة الله مثل آية إنامتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص617، تحت «علة التعبير بالبعث دون غيره»","url":""}]},{"id":"s18-43","number":43,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما سرّ تسمية محاورة الفتية عن مدة لبثهم ﴿تَسَاؤُلًا﴾؟","answer":"لأن كل واحد منهم طلب من غيره تقدير المدة، فتبادلوا السؤال والرأي.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص619، تحت «سر تسمية المحاورة تساؤلًا»","url":""}]},{"id":"s18-220","number":220,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما دلالة تفويض الفتية علم مدة لبثهم إلى الله؟","answer":"لما لم يبلغوا اليقين تركوا الظن وفوضوا العلم إلى الله، وذلك من كمال إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص624، تحت «نكتة تفويض العلم بمدة لبثهم إلى الله تعالى»","url":""}]},{"id":"s18-44","number":44,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما دلالة التعبير بقوله ربكم أعلم بما لبثتم؟","answer":"لما اختلفوا عدلوا عن القول بالظن إلى تفويض العلم لله، وذلك من كمال إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص623، تحت «دلالة التعبير بقوله ربكم أعلم بما لبثتم»","url":""}]},{"id":"s18-45","number":45,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما سرّ التعبير بـ﴿أَيُّهَا أَزْكَى طَعَامًا﴾؟","answer":"«أزكى» تجمع وجوهًا من طيب الطعام وجودته وطهارته وحلّه؛ فطلبوا ما هو أكثر خيرًا وأنفع وأبعد عن الحرام. وصيغة التفضيل تدل على عنايتهم بالاختيار، لا الاكتفاء بأي طعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص631، تحت «سر التعبير بأزكى دون أفضل»","url":""}]},{"id":"s18-46","number":46,"surah":18,"verses":[20],"references":[{"surah":18,"verses":[20]}],"verseLabel":"الكهف: 20","question":"ما سرّ تخصيص الرجم في قول الفتية ﴿يَرْجُمُوكُمْ﴾؟","answer":"لأنه من أشد العقوبات وأشنعها، فصور ما يخشونه على أجسادهم إن ظهر القوم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص642، تحت «سر ذكر الرجم دون غيره من العقوبات»","url":""}]},{"id":"s18-221","number":221,"surah":18,"verses":[20],"references":[{"surah":18,"verses":[20]}],"verseLabel":"الكهف: 20","question":"ما دلالة ترتيب نفي الفلاح على الرجوع إلى ملة القوم؟","answer":"يبين أن الرجوع الحقيقي إلى الكفر والاستمرار عليه يفضي إلى خسران لا فلاح معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص645، تحت «دلالة ترتيب نفي الفلاح على الإكراه على الرجوع إلى الكفر»","url":""}]},{"id":"s18-47","number":47,"surah":18,"verses":[21],"references":[{"surah":18,"verses":[21]}],"verseLabel":"الكهف: 21","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ أَعْثَرْنَا عَلَيْهِمْ﴾؟","answer":"يشبه إطلاع الناس عليهم بإنامتهم وإيقاظهم في كونه آية على القدرة. ولفظ «أعثرنا» يصور الوصول إلى خبرهم بعد خفائه، لتقوم به العبرة ويظهر صدق البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص651، تحت «بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s18-48","number":48,"surah":18,"verses":[21],"references":[{"surah":18,"verses":[21]}],"verseLabel":"الكهف: 21","question":"ما النكتة البلاغية في ذكر الحق دون الصدق في قوله تعالى: ﴿لِيَعْلَمُوا أَنَّ وَعْدَ اللَّهِ حَقٌّ﴾؟","answer":"جعل العثور عليهم برهانًا مشاهدًا على إحياء الموتى والبعث، فازداد علم القوم بكيفية ما كانوا يؤمنون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص653، تحت «نكتة ذكر الحق دون الصدق»","url":""}]},{"id":"s18-49","number":49,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما سرّ التعبير بـ﴿رَجْمًا بِالْغَيْبِ﴾؟","answer":"استعير الرجم لرمي الكلام من غير روية ولا تثبت، كما يُرمى الحجر نحو ما لا يُعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص671، تحت «بلاغة الاستعارة التصريحية في لفظ رجمًا»","url":""}]},{"id":"s18-50","number":50,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما دلالة العدول إلى قوله: ﴿مَا يَعْلَمُهُمْ إِلَّا قَلِيلٌ﴾ بعد اختلاف الأقوال في عدد الفتية؟","answer":"وجّه التعبير العناية إلى معرفة الفتية وصفاتهم ومواضع العبرة من قصتهم، بدل الاستغراق في تعدادهم. وأثبت أن العلم بهم لقليل ممن أطلعهم الله، فيعلم القارئ الوقوف عند الدليل وترك التخمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص675، تحت «نكتة العدول عن ذكر العدد إلى ذكر الذات»","url":""}]},{"id":"s18-51","number":51,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما سرّ التعبير بـ﴿فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَاءً ظَاهِرًا﴾؟","answer":"المراء الظاهر هو ما كانت حجته واضحة ولا يطول الخوض فيه؛ وما وراء ذلك قليل الجدوى محتاج إلى دليل فلا ينبغي الاشتغال به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص677، تحت «نكتة تقييد المراء بقوله ظاهرًا»","url":""}]},{"id":"s18-52","number":52,"surah":18,"verses":[23,24],"references":[{"surah":18,"verses":[23,24]}],"verseLabel":"الكهف: 23-24","question":"ما دلالة تعليق العزم على الفعل المستقبل بمشيئة الله؟","answer":"لئلا يُجزم بفعل مستقبل دون تقييده بمشيئة الله وإذنه؛ فجاء النهي تعليمًا لأدب الوعد والإخبار عن العزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص684، تحت «غرض النهي في ولا تقولن»","url":""}]},{"id":"s18-53","number":53,"surah":18,"verses":[24],"references":[{"surah":18,"verses":[24]}],"verseLabel":"الكهف: 24","question":"ما وجه البلاغة في الكناية في الأمر بالذكر في قوله تعالى: ﴿وَاذْكُرْ رَبَّكَ إِذَا نَسِيتَ﴾؟","answer":"من توجيهاته أن من نسي ذكر المشيئة يستدركه عندما يتذكر، مع تذكر عظمة الله وامتثال أمره. وحذف مفعول «نسيت» يناسب ظهوره من السياق ويعنى ببيان ما يصنعه الناسي عند التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص687، تحت «بلاغة الكناية في الأمر بالذكر»","url":""}]},{"id":"s18-54","number":54,"surah":18,"verses":[24],"references":[{"surah":18,"verses":[24]}],"verseLabel":"الكهف: 24","question":"ما النكتة البلاغية في استعمال عسى في قوله تعالى: ﴿عَسَى أَنْ يَهْدِيَنِ رَبِّي لِأَقْرَبَ مِنْ هَذَا رَشَدًا﴾؟","answer":"يعلم التعبير رجاء الهداية من الله وطلب الأقرب إلى الرشد. ومن توجيهاته رجاء الانتقال إلى ما هو أهم في الهداية من مجاراة السائلين في القصة، ومن توجيهاته التدارك بما هو أحسن وأكمل مما عزم عليه الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص689، تحت «نكتة استعمال عسى»","url":""}]},{"id":"s18-55","number":55,"surah":18,"verses":[25],"references":[{"surah":18,"verses":[25]}],"verseLabel":"الكهف: 25","question":"ما سرّ التعبير بـ﴿ثَلَاثَ مِائَةٍ سِنِينَ وَازْدَادُوا تِسْعًا﴾؟","answer":"من توجيهات فصل الزيادة بتسع سنوات الإشارة إلى اختلاف الحسابين: ثلاثمائة سنة شمسية تقابل نحو ثلاثمائة وتسع سنين قمرية. فيجمع التعبير أصل المدة والزيادة الناشئة عن اختلاف طريقة الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص692، تحت «المعنى الإجمالي»","url":""}]},{"id":"s18-56","number":56,"surah":18,"verses":[26],"references":[{"surah":18,"verses":[26]}],"verseLabel":"الكهف: 26","question":"ما دلالة قوله ﴿قُلِ اللَّهُ أَعْلَمُ بِمَا لَبِثُوا﴾ بعد ذكر المدة؟","answer":"لقطع المماراة في مدة لبثهم ورد علمها إلى الله؛ وعلى وجه حكاية قول أهل الكتاب يكون تفويضًا للعلم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص694، تحت «علة فصل قوله تعالى قل الله أعلم بما لبثوا»","url":""}]},{"id":"s18-57","number":57,"surah":18,"verses":[26],"references":[{"surah":18,"verses":[26]}],"verseLabel":"الكهف: 26","question":"ما سرّ التعبير بـ﴿أَبْصِرْ بِهِ وَأَسْمِعْ﴾؟","answer":"جاء التعبير بصيغة التعجب ليقرر كمال سمع الله وبصره وإحاطته بالدقيق والجليل، والظاهر والباطن؛ فلا تدرك الخلائق مدى هذا الكمال ولا تحيط به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص697، تحت «غرض التعجب وبلاغته»","url":""}]},{"id":"s18-58","number":58,"surah":18,"verses":[27],"references":[{"surah":18,"verses":[27]}],"verseLabel":"الكهف: 27","question":"ما دلالة قوله ﴿لَا مُبَدِّلَ لِكَلِمَاتِهِ﴾ عقب الأمر بتلاوة الوحي؟","answer":"تقرير وجوب تلاوة الوحي كله كما أُنزل؛ فلا يملك أحد تبديل كلماته، ولا يسوغ إخفاء شيء منه بحذف أو زيادة استجابة لضغط المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص706، تحت «سر التعبير باسم الفاعل مبدل»","url":""}]},{"id":"s18-59","number":59,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿وَاصْبِرْ نَفْسَكَ﴾؟","answer":"أي احبس نفسك وثبّتها مع الذين يدعون ربهم، ولا تفارقهم استجابة لرغبة أهل الكبر؛ فعدّي الصبر إلى النفس لإفادة حبسها على هذه الملازمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص714، تحت «بلاغة الإطناب بذكر قيد نفسك»","url":""}]},{"id":"s18-60","number":60,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿يُرِيدُونَ وَجْهَهُ﴾؟","answer":"يبين القيد إخلاصهم لله؛ فهم يدعونه ويعبدونه ابتغاء رضاه، لا طلبًا لعرض الدنيا. والمضارع يستحضر تجدد هذه الإرادة واستمرارها مع عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص720، تحت «نكتة التقييد بقوله يريدون وجهه»","url":""}]},{"id":"s18-61","number":61,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ﴾؟","answer":"نُسب التجاوز إلى العينين كناية عن ترك مجالستهم؛ أي لا تصرف نظرك عنهم إلى أهل الدنيا طلبًا لزينتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص722، تحت «نكتة المجاز المرسل»","url":""}]},{"id":"s18-62","number":62,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ وصف أمر الغافل بأنه ﴿فُرُطًا﴾؟","answer":"من معاني «فرطًا» الإفراط وتجاوز الحد في الظلم، ومن معانيها التفريط والتضييع فيما يلزم من أمر الدين. و«كان» تدل على تمكن هذا الخلل من حاله، بعد وصفه بالغفلة واتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص730، تحت «بلاغة الاستعارة في قوله أمره فرطًا»","url":""}]},{"id":"s18-63","number":63,"surah":18,"verses":[29],"references":[{"surah":18,"verses":[29]}],"verseLabel":"الكهف: 29","question":"ما وجه البلاغة في الكناية في فليؤمن وفليكفر في قوله تعالى: ﴿فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ﴾؟","answer":"ليس إذنًا بالكفر، بل الأمر للتسوية المكنى بها عن الوعد والوعيد، وقد كشف ما بعدها وخامة عاقبة من يستمر على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص738، تحت «بلاغة الكناية في فليؤمن وفليكفر»","url":""}]},{"id":"s18-64","number":64,"surah":18,"verses":[29],"references":[{"surah":18,"verses":[29]}],"verseLabel":"الكهف: 29","question":"ما دلالة إحاطة سرادق النار بالظالمين؟","answer":"صُورت النار دارًا يحيط بها سرادق، مبالغة في إحاطة دار العذاب بهم؛ وفي استعارة شعار بيوت المترفين للنار تهكم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص743، تحت «بلاغة التشبيه والاستعارة في لفظ سرادقها»","url":""}]},{"id":"s18-65","number":65,"surah":18,"verses":[29],"references":[{"surah":18,"verses":[29]}],"verseLabel":"الكهف: 29","question":"ما سرّ تشبيه ماء أهل النار بـ﴿الْمُهْلِ﴾؟","answer":"للمهْل تفسيرات منها دُردي الزيت ومنها ما أذيب من المعادن، ويصور التشبيه سواد الماء وشدة حرارته. فبدل أن يبرد المستغيثين يزيدهم عذابًا، حتى يشوي وجوههم عند اقترابه منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص746، تحت «براعة تشبيه الماء بالمهل»","url":""}]},{"id":"s18-66","number":66,"surah":18,"verses":[30],"references":[{"surah":18,"verses":[30]}],"verseLabel":"الكهف: 30","question":"ما فائدة التعبير بالموصول من في قوله تعالى: ﴿إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا﴾؟","answer":"طمأنة للمؤمنين بأن عملهم مرعي عند ربهم، وصيغ الحكم عامًا ليشملهم وكل من يماثلهم في إحسان العمل، مع مزيد توكيد لتحقيق الجزاء لأربابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص757، تحت «فائدة التعبير بالموصول من»","url":""}]},{"id":"s18-68","number":68,"surah":18,"verses":[32],"references":[{"surah":18,"verses":[32]}],"verseLabel":"الكهف: 32","question":"ما دلالة ضرب مثل الرجلين بعد بيان حال المؤمنين والكافرين؟","answer":"لتمثيل حال الفريقين بقصة تظهر عاقبة غرور الكافر وخسارته، وعاقبة المؤمن المتواضع العارف بسنن الله؛ فتجعل المعنى العقدي في صورة محسوسة أوقع في العبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص775، تحت «بلاغة التمثيل بحال الرجلين»","url":""}]},{"id":"s18-69","number":69,"surah":18,"verses":[32],"references":[{"surah":18,"verses":[32]}],"verseLabel":"الكهف: 32","question":"ما دلالة إحاطة الجنتين بالنخل في قوله ﴿وَحَفَفْنَاهُمَا بِنَخْلٍ﴾؟","answer":"يصوّر النخل محيطًا بالجنتين إحاطة تحفظهما وتزيدهما جمالًا ونفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص776، تحت «بلاغة استعمال وحففناهما التصويرية»","url":""}]},{"id":"s18-222","number":222,"surah":18,"verses":[32],"references":[{"surah":18,"verses":[32]}],"verseLabel":"الكهف: 32","question":"ما سرّ تقديم ﴿بَيْنَهُمَا﴾ في قوله ﴿وَجَعَلْنَا بَيْنَهُمَا زَرْعًا﴾؟","answer":"للاهتمام بموقع الزرع بين الجنتين وتصوير إحكام ترتيب الضيعة وتكاملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص778، تحت «غرض تقديم بينهما على زرعًا»","url":""}]},{"id":"s18-70","number":70,"surah":18,"verses":[33],"references":[{"surah":18,"verses":[33]}],"verseLabel":"الكهف: 33","question":"ما سرّ التعبير بـ﴿وَلَمْ تَظْلِمْ مِنْهُ شَيْئًا﴾ في وصف الجنتين؟","answer":"استعير الظلم للنقص: فقد أوفت كل جنة بما يُترقب من مقدار الثمر في حال الخصب، فكأن نقصان الغلة حرمان لصاحب حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص780، تحت «فائدة الاستعارة في قوله ولم تظلم»","url":""}]},{"id":"s18-71","number":71,"surah":18,"verses":[34],"references":[{"surah":18,"verses":[34]}],"verseLabel":"الكهف: 34","question":"ما سرّ التعبير بـ﴿وَكَانَ لَهُ ثَمَرٌ﴾ بعد ذكر الجنتين؟","answer":"تحتمل «الثمر» حمل الشجر، وتأتي في بعض توجيهات اللفظ والقراءات بمعنى المال الكثير المتنوع. وعلى معنى المال، يتسع وصف غناه لما وراء محصول الجنتين؛ فلا يصح حصر اللفظ في معنى واحد مع تعدد توجيهاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص784، تحت «بديع اختيار الألفاظ وأثرها في الإيجاز»","url":""}]},{"id":"s18-72","number":72,"surah":18,"verses":[34],"references":[{"surah":18,"verses":[34]}],"verseLabel":"الكهف: 34","question":"ما وجه البلاغة في جملة ﴿وَهُوَ يُحَاوِرُهُ﴾؟","answer":"جاءت الجملة حالًا تستحضر تفاخر صاحب الجنتين أثناء الحوار نفسه، وتصور تبادل الكلام بينه وبين صاحبه المؤمن؛ أحدهما يعتد بماله ونفره والآخر يراجعه بالنصح والحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص786، تحت «بلاغة جملة ﴿وَهُوَ يُحَاوِرُهُ﴾»","url":""}]},{"id":"s18-223","number":223,"surah":18,"verses":[34],"references":[{"surah":18,"verses":[34]}],"verseLabel":"الكهف: 34","question":"ما دلالة إضافة الصاحب إلى ضمير صاحب الجنتين في قوله: ﴿قَالَ لَهُ صَاحِبُهُ﴾؟","answer":"تكشف الإضافة صلة الصحبة والتواصل بين الرجلين، وتبرز أن قرب المؤمن منه لم يمنعه من نصحه. وفيها كذلك تنبيه للمؤمن إلى أثر الصحبة وضرورة الحذر من الاغترار بزينة الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص785، تحت «معنى إضافة الصاحب إلى الضمير»","url":""}]},{"id":"s18-73","number":73,"surah":18,"verses":[35],"references":[{"surah":18,"verses":[35]}],"verseLabel":"الكهف: 35","question":"ما دلالة قوله ﴿وَهُوَ ظَالِمٌ لِنَفْسِهِ﴾ عند دخوله جنته؟","answer":"يكشف الوصف حقيقة حاله وهو داخل في زهو نعمته: كان مشركًا مكذبًا بالبعث بطرًا بنعمة الله عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص793، تحت «الغرض من ورود الخبر ظالم اسم فاعل»","url":""}]},{"id":"s18-74","number":74,"surah":18,"verses":[35],"references":[{"surah":18,"verses":[35]}],"verseLabel":"الكهف: 35","question":"ما سرّ التعبير بـ﴿مَا أَظُنُّ أَنْ تَبِيدَ هَذِهِ أَبَدًا﴾؟","answer":"أشار بـ﴿هذه﴾ إلى الجنة الحاضرة التي دخلاها، ونفى اعتقاده زوالها؛ والمراد بالأبد طول المدة وبقاؤها بقاء أمثالها، اغترارًا بقوة أسباب نمائها ودوامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص794، تحت «نكتة التعبير باسم الإشارة هذه»","url":""}]},{"id":"s18-75","number":75,"surah":18,"verses":[36],"references":[{"surah":18,"verses":[36]}],"verseLabel":"الكهف: 36","question":"ما الغرض البلاغي من الإخبار في ولئن رددت في قوله تعالى: ﴿وَلَئِنْ رُدِدْتُ إِلَى رَبِّي﴾؟","answer":"قاله تهكمًا بصاحبه المؤمن بعد أن نفى قيام الساعة؛ ثم بالغ في التهكم بلام القسم ونون التوكيد مدعيًا أنه ـ على فرض الرد ـ سيجد خيرًا من جنتيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص799، تحت «غرض الإخبار في ولئن رددت»","url":""}]},{"id":"s18-76","number":76,"surah":18,"verses":[37],"references":[{"surah":18,"verses":[37]}],"verseLabel":"الكهف: 37","question":"ما دلالة تذكير صاحب الجنتين بخلقه من تراب ثم من نطفة؟","answer":"يذكّره بأصل خلقه ومراحله، من التراب إلى النطفة، ليقيم عليه الحجة في إنكار البعث؛ فمن أوجده أول مرة قادر على إعادته. وفي تذكيره بهذه البداية الضعيفة تقريع على جحوده واغتراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص15، تحت «معنى من ودلالتها في من تراب»","url":""}]},{"id":"s18-77","number":77,"surah":18,"verses":[37],"references":[{"surah":18,"verses":[37]}],"verseLabel":"الكهف: 37","question":"ما سرّ التعبير بـ﴿ثُمَّ سَوَّاكَ رَجُلًا﴾؟","answer":"تُبرز «ثم» التدرج بين أطوار الخلق، و«سواك» تحقق العناية بإيجاده إنسانًا سويًّا. و«رجلًا» حال تشير إلى بلوغ مرحلة الرجولة والقوة؛ فتزيد تقريعه على جحود نعمة من خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص17، تحت «دلالة التعبير بالفعل الماضي سواك»","url":""}]},{"id":"s18-78","number":78,"surah":18,"verses":[38],"references":[{"surah":18,"verses":[38]}],"verseLabel":"الكهف: 38","question":"ما دلالة قول المؤمن: ﴿لَكِنَّا هُوَ اللَّهُ رَبِّي﴾؟","answer":"بعد إنكار اعتقاد صاحبه، يعلن المؤمن اعتقاده هو. والاستدراك يبرز المقابلة بين كفر صاحبه وتوحيده؛ فليست مواجهته بالفخر بالمال، بل بالتصريح بأن الله ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص18، تحت «معنى لكنا ودلالتها في السياق»","url":""}]},{"id":"s18-79","number":79,"surah":18,"verses":[38],"references":[{"surah":18,"verses":[38]}],"verseLabel":"الكهف: 38","question":"ما سرّ التعبير بـ﴿وَلَا أُشْرِكُ بِرَبِّي أَحَدًا﴾ لا «واحدًا»؟","answer":"«أحدًا» في سياق النفي أعم؛ تنفي أي شريك على أي صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص20، تحت «نكتة إيثار التعبير بأحدًا دون واحدًا»","url":""}]},{"id":"s18-80","number":80,"surah":18,"verses":[39],"references":[{"surah":18,"verses":[39]}],"verseLabel":"الكهف: 39","question":"ما دلالة قول صاحب المؤمن لصاحبه: ﴿مَا شَاءَ اللَّهُ﴾؟","answer":"هو إقرار بأن ما في الجنة من خير حاصل بمشيئة الله، لا باستحقاق الإنسان واستقلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص26، تحت «معنى ما ودلالتها»","url":""}]},{"id":"s18-224","number":224,"surah":18,"verses":[39],"references":[{"surah":18,"verses":[39]}],"verseLabel":"الكهف: 39","question":"ما دلالة القصر في قوله ﴿لَا قُوَّةَ إِلَّا بِاللَّهِ﴾؟","answer":"ينفي استقلال العبد بالقوة، ويثبت أن قدرته على العمل والحفظ لا تكون إلا بمعونة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص27، تحت «دلالة القصر في لا قوة إلا بالله»","url":""}]},{"id":"s18-81","number":81,"surah":18,"verses":[39],"references":[{"surah":18,"verses":[39]}],"verseLabel":"الكهف: 39","question":"ما سرّ التعبير بـ﴿إِنْ تَرَنِ أَنَا أَقَلَّ مِنْكَ﴾؟","answer":"يرد على تفاخر صاحبه بكثرة المال والولد، ويربط القلة الحالية برجاء فضل الله؛ فقد يؤتيه خيرًا من جنته. فلا تجعل قلة المال المؤمن حقيرًا، ولا تجعل كثرته عند الآخر ضمانًا لدوام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص28، تحت «دلالة التعبير بأقل في السياق»","url":""}]},{"id":"s18-82","number":82,"surah":18,"verses":[40],"references":[{"surah":18,"verses":[40]}],"verseLabel":"الكهف: 40","question":"ما سرّ التعبير بـ﴿حُسْبَانًا مِنَ السَّمَاءِ﴾؟","answer":"الحسبان عذاب من السماء، ومن تفسيره الصواعق أو النار. وتقييده بـ«من السماء» يشدد التهديد؛ فهو عذاب نازل من فوق لا يملك دفعه، وفي ذلك بيان لعجزه أمام قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص33، تحت «الغرض من القيد بالجار والمجرور من السماء»","url":""}]},{"id":"s18-83","number":83,"surah":18,"verses":[40],"references":[{"surah":18,"verses":[40]}],"verseLabel":"الكهف: 40","question":"ما دلالة وصف مآل الجنة بأنها ﴿صَعِيدًا زَلَقًا﴾؟","answer":"تتحول الجنة إلى أرض جرداء ملساء تزِل عليها القدم، بعد كثرة الشجر والنبات. ووصفها بـ«زلقًا» يزيد تصوير الخراب والخلو من أسباب النماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص35، تحت «سر وصف الصعيد بزلقًا ودلالتها»","url":""}]},{"id":"s18-84","number":84,"surah":18,"verses":[41],"references":[{"surah":18,"verses":[41]}],"verseLabel":"الكهف: 41","question":"ما سرّ وصف الماء بالمصدر في قوله ﴿أَوْ يُصْبِحَ مَاؤُهَا غَوْرًا﴾؟","answer":"جاء المصدر وصفًا للمبالغة، فكأن الماء نفسه صار غؤورًا لشدة ذهابه في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص36، تحت «الغرض من التعبير بالمصدر غورًا»","url":""}]},{"id":"s18-225","number":225,"surah":18,"verses":[41],"references":[{"surah":18,"verses":[41]}],"verseLabel":"الكهف: 41","question":"ما دلالة قوله عن الماء الغائر ﴿فَلَنْ تَسْتَطِيعَ لَهُ طَلَبًا﴾؟","answer":"يبلغ في إظهار العجز؛ فلا يستطيع الوصول إلى الماء ولا تحصيله وردّه إلى جنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص37، تحت «دلالة التعبير بلفظ الطلب»","url":""}]},{"id":"s18-85","number":85,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]}],"verseLabel":"الكهف: 42","question":"ما دلالة التعبير بـ﴿وَأُحِيطَ بِثَمَرِهِ﴾؟","answer":"الإحاطة كناية عن الهلاك والفساد؛ تشبه استيلاء العدو على الشيء من جميع جوانبه. وهي تصور شمول الهلاك لما كان يعتز به صاحب الجنتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص42، تحت «الغرض من التعبير بالكناية في الآية»","url":""}]},{"id":"s18-86","number":86,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]}],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿بِثَمَرِهِ﴾ لا «بزرعه» أو «جنتيه»؟","answer":"الثمر هو الغاية التي يرجوها صاحب الزرع، فذكر هلاكه يزيد تصوير الفجيعة بعد الإنفاق وانتظار الانتفاع. وتعدد توجيهات «الثمر» وقراءاته يتسع للمحصول والمال، مع دلالة السياق على خراب الأصل أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص43، تحت «سر التعبير بالقيد بثمره»","url":""}]},{"id":"s18-87","number":87,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]}],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿يُقَلِّبُ كَفَّيْهِ﴾؟","answer":"تقليب الكفين كناية عن الندم والحسرة، تُرى في حركة اليدين شدة ما أصابه. وصيغة المضارع تستحضر تكرر هذه الحركة واستمرار تحسره على ما أنفق في جنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص45، تحت «الغرض من التعبير بالكناية في سياق الآية»","url":""}]},{"id":"s18-88","number":88,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]},{"surah":22,"verses":[45]}],"verseLabel":"الكهف: 42؛ الحج: 45","question":"ما دلالة وصف جنة صاحب الجنتين بأنها ﴿خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"يصور خراب الجنة وسقوطها على ما رفعت عليه كرومها، فجمع هلاك الثمر وأصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص48، تحت «سر التقييد بعروشها دون غيرها»","url":""}]},{"id":"s18-226","number":226,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]},{"surah":22,"verses":[45]}],"verseLabel":"الكهف: 42؛ الحج: 45","question":"ما دلالة وصف القرية في سورة الحج بأنها ﴿خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"كناية عن غاية خرابها؛ تهدمت سقوفها ثم سقطت الجدران فوقها، وقيل خلت من أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص726، تحت «بلاغة الكناية في خاوية على عروشها»","url":""}]},{"id":"s18-89","number":89,"surah":18,"verses":[43],"references":[{"surah":18,"verses":[43]}],"verseLabel":"الكهف: 43","question":"ما سرّ التعبير بـ﴿وَلَمْ تَكُنْ لَهُ فِئَةٌ يَنْصُرُونَهُ﴾؟","answer":"ينفي وجود فئة تستطيع دفع العذاب عنه، لا مجرد أنها امتنعت عن نصرته؛ فالمقام مقام عجز أمام قدرة الله. ويضم إليه ﴿وَمَا كَانَ مُنْتَصِرًا﴾ لينفي قدرته على إنقاذ نفسه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص54، تحت «سر التعبير بفعل الكون»","url":""}]},{"id":"s18-90","number":90,"surah":18,"verses":[44],"references":[{"surah":18,"verses":[44]}],"verseLabel":"الكهف: 44","question":"ما سرّ تقديم ﴿هُنَالِكَ﴾ في ﴿هُنَالِكَ الْوَلَايَةُ لِلَّهِ الْحَقِّ﴾؟","answer":"يشير إلى لحظة سقوط الأسباب خاصة؛ عندها يظهر بلا غطاء أن السلطان والنصرة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص60، تحت «الغرض من تقديم هنالك على الولاية»","url":""}]},{"id":"s18-91","number":91,"surah":18,"verses":[45],"references":[{"surah":18,"verses":[45]}],"verseLabel":"الكهف: 45","question":"ما دلالة تمثيل الحياة الدنيا بالماء والنبات الذي يصير هشيمًا؟","answer":"يضرب المثل لسرعة نضارة الدنيا ثم زوالها؛ فالنبات ينتعش بالماء ويشتبك، ثم يصير هشيمًا تفرقه الرياح. والمقصود تشبيه دورة الازدهار والفناء، لا تشبيه الدنيا بالماء وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص68، تحت «دلالة أسلوب التمثيل في السياق»","url":""}]},{"id":"s18-92","number":92,"surah":18,"verses":[45],"references":[{"surah":18,"verses":[45]}],"verseLabel":"الكهف: 45","question":"ما سرّ التعبير بـ﴿فَأَصْبَحَ هَشِيمًا تَذْرُوهُ الرِّيَاحُ﴾؟","answer":"الفاء تسرع الانتقال من الاخضرار إلى التفتت، والرياح تفرق ما ظن ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص72، تحت «دلالة التعبير بصيغة فعيل في هشيم»","url":""}]},{"id":"s18-93","number":93,"surah":18,"verses":[46],"references":[{"surah":18,"verses":[46]}],"verseLabel":"الكهف: 46","question":"ما دلالة وصف المال والبنين بأنهما ﴿زِينَةُ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"وصفهما بالزينة يقر بما فيهما من جمال وقوة في الدنيا، لكنه يبين محدودية ذلك وزواله. وإضافة الزينة إلى الحياة الدنيا تمهد للمقابلة بالأعمال الصالحة التي يبقى نفعها في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص79، تحت «سر إضافة الزينة إلى الحياة»","url":""}]},{"id":"s18-94","number":94,"surah":18,"verses":[46],"references":[{"surah":18,"verses":[46]}],"verseLabel":"الكهف: 46","question":"ما دلالة وصف الباقيات الصالحات بأنها ﴿خَيْرٌ أَمَلًا﴾؟","answer":"لأن أثرها يبقى عند الله، فهي خير في الثواب وخير فيما يصح أن يعلّق به الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص83، تحت «سر التقييد بالتمييز أملًا»","url":""}]},{"id":"s18-95","number":95,"surah":18,"verses":[47],"references":[{"surah":18,"verses":[47]}],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿وَيَوْمَ نُسَيِّرُ الْجِبَالَ﴾؟","answer":"المضارع يستحضر تسيير الجبال كأنه مشهد يُرى، فيعظم وقعه في النفس. وافتتاح الكلام بذكر اليوم يجمع أهوال ذلك الموقف ويهيئ السامع لما بعده من بروز الأرض والحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص87، تحت «دلالة التعبير بالفعل المضارع»","url":""}]},{"id":"s18-96","number":96,"surah":18,"verses":[47],"references":[{"surah":18,"verses":[47]}],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿وَتَرَى الْأَرْضَ بَارِزَةً﴾؟","answer":"بعد زوال الجبال والستر تبدو الأرض مكشوفة لا مخبأ فيها ولا معلم يحجب أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص89، تحت «الغرض من تنكير بارزة»","url":""}]},{"id":"s18-97","number":97,"surah":18,"verses":[47],"references":[{"surah":18,"verses":[47]}],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا﴾؟","answer":"تنكير «أحدًا» في سياق النفي يفيد الاستغراق؛ فلا يتخلف عن الحشر فرد من الأولين أو الآخرين. وجاء نفي المغادرة بعد ﴿وَحَشَرْنَاهُمْ﴾ توكيدًا لشمول الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص92، تحت «دلالة التعبير بالمفعول به لفظ أحدًا منكرًا»","url":""}]},{"id":"s18-98","number":98,"surah":18,"verses":[48],"references":[{"surah":18,"verses":[48]}],"verseLabel":"الكهف: 48","question":"ما دلالة عرض الناس على ربهم ﴿صَفًّا﴾؟","answer":"يصورهم مجتمعين منتظمين لا يحجب بعضهم بعضًا، كالجند المعروضين على السلطان. فتبرز هيئة العرض شمول الحضور وهيبة الموقف، وأن أحدًا لا يفلت من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص98، تحت «سر التقييد بالحال صفًّا»","url":""}]},{"id":"s18-99","number":99,"surah":18,"verses":[48],"references":[{"surah":18,"verses":[48]}],"verseLabel":"الكهف: 48","question":"ما بلاغة التعبير بقوله يوم القيامة ﴿لَقَدْ جِئْتُمُونَا﴾؟","answer":"يصوّر حضور الخلق للحساب مجيئًا لا مهرب منه، وفيه تبكيت لمن أنكر هذا الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص99، تحت «بلاغة الاستعارة في لفظ لقد جئتمونا»","url":""}]},{"id":"s18-227","number":227,"surah":18,"verses":[48],"references":[{"surah":18,"verses":[48]}],"verseLabel":"الكهف: 48","question":"ما الغرض البلاغي من التشبيه في كما خلقناكم أول مرة في قوله تعالى: ﴿كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ﴾؟","answer":"يشبه إعادتهم ببدء خلقهم تقريرًا لقدرة الله على البعث، ويذكر أنهم يأتون مجردين مما تفاخروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص100، تحت «الغرض من التشبيه في كما خلقناكم أول مرة»","url":""}]},{"id":"s18-100","number":100,"surah":18,"verses":[49],"references":[{"surah":18,"verses":[49]}],"verseLabel":"الكهف: 49","question":"ما سرّ التعبير بـ﴿وَوُضِعَ الْكِتَابُ﴾ لا «ووضعنا الكتاب»؟","answer":"البناء للمجهول يوجه الأنظار إلى رهبة السجل الموضوع نفسه وما يكشفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص106، تحت «دلالة بناء الفعل للمفعول»","url":""}]},{"id":"s18-101","number":101,"surah":18,"verses":[49],"references":[{"surah":18,"verses":[49]}],"verseLabel":"الكهف: 49","question":"ما سرّ التعبير بقوله تعالى: ﴿يَا وَيْلَتَنَا﴾ بصيغة التأنيث؟","answer":"صيغة «الويلة» تبالغ في وصف الهلاك وشدته، وليست تأنيثًا لشخص. ونداؤها يصور غاية الندم والفزع حتى كأنهم يدعون الهلاك ليحضر حين رأوا أعمالهم محصاة في الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص110، تحت «سر التعبير عن الويل بصيغة التأنيث»","url":""}]},{"id":"s18-102","number":102,"surah":18,"verses":[49],"references":[{"surah":18,"verses":[49]}],"verseLabel":"الكهف: 49","question":"ما النكتة البلاغية في تقديم الصغيرة على الكبيرة في قوله تعالى: ﴿لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً﴾؟","answer":"تنكير الصغيرة والكبيرة مع النفي يفيد شمول الإحصاء لكل عمل. وتقديم الصغيرة يبرز دقة الكتاب؛ فإذا لم تفته الصغائر فالكبائر أولى، ثم ذُكرت صراحة لتأكيد الشمول وزيادة التهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص112، تحت «نكتة تقديم الصغيرة على الكبيرة»","url":""}]},{"id":"s18-103","number":103,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما دلالة إيراد قصة سجود الملائكة وإباء إبليس في هذا الموضع من سورة الكهف؟","answer":"تذكر القصة بأصل عداوة الشيطان واستكباره، بعد مشاهد الحشر والحساب، فتدعو إلى الحذر من اتباعه. وتناسب أيضًا ذم الافتخار بالمال واحتقار المؤمنين؛ إذ تعرض نموذج الاستكبار الذي أورث العصيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص118، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s18-104","number":104,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما دلالة ﴿عَنْ﴾ في قوله عن إبليس ﴿فَفَسَقَ عَنْ أَمْرِ رَبِّهِ﴾؟","answer":"تصور خروجه ومجاوزته دائرة أمر الله بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص123، تحت «دلالة حرف المجاوزة عن»","url":""}]},{"id":"s18-228","number":228,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما سرّ إضافة الأمر إلى الرب في قوله ﴿عَنْ أَمْرِ رَبِّهِ﴾؟","answer":"تشنّع عصيان إبليس؛ إذ خرج عن أمر من رباه وأنعم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص124، تحت «سر الإضافة أمر ربه»","url":""}]},{"id":"s18-105","number":105,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما سرّ التعبير بـ﴿أَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِيَاءَ﴾؟","answer":"الاستفهام يعجب من موالاة عدو أعلن عداوته منذ خلق أبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص125، تحت «الغرض من أسلوب الاستفهام في أفتتخذونه»","url":""}]},{"id":"s18-106","number":106,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما سر إظهار وصف ﴿لِلظَّالِمِينَ﴾ في قوله: ﴿بِئْسَ لِلظَّالِمِينَ بَدَلًا﴾؟","answer":"ليحكم عليهم بالظلم ويبين أن استبدال ولاية الشيطان بولاية الله هو عين وضع الشيء في غير موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص128، تحت «الغرض من التعبير بالإظهار دون الإضمار»","url":""}]},{"id":"s18-107","number":107,"surah":18,"verses":[51],"references":[{"surah":18,"verses":[51]}],"verseLabel":"الكهف: 51","question":"ما الغرض من نفي إشهاد إبليس وذريته خلق السماوات والأرض؟","answer":"ينفي ذلك أن يكونوا قد شاركوا في الخلق أو عاونوا عليه أو أُحضروا للمشورة فيه؛ فيسقط كل وجه لاتخاذهم أولياء من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص132، تحت «الغرض من نفي الإشهاد في خلق السماوات»","url":""}]},{"id":"s18-229","number":229,"surah":18,"verses":[51],"references":[{"surah":18,"verses":[51]}],"verseLabel":"الكهف: 51","question":"ما دلالة التعبير بـ﴿خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ﴾ في نفي استحقاق الشركاء للولاية؟","answer":"يستدل بخلق السماوات والأرض على أن الله هو الخالق المستقل لكل شيء، ومنه خلق الشركاء أنفسهم؛ فمن انفرد بالخلق هو المستحق للعبادة والولاية دونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص132، تحت «دلالة التعبير بـ﴿خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ﴾»","url":""}]},{"id":"s18-108","number":108,"surah":18,"verses":[51],"references":[{"surah":18,"verses":[51]}],"verseLabel":"الكهف: 51","question":"ما سرّ التعبير بـ﴿وَمَا كُنْتُ مُتَّخِذَ الْمُضِلِّينَ عَضُدًا﴾؟","answer":"استعير العضد للمعين، لأنه مما يقوم به الإسناد والقوة، فنفى الله اتخاذ المضلين أعوانًا. وإظهار وصف «المضلين» يذمهم وينبه إلى فساد اتخاذهم أولياء، مع غنى الله عن المعين أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص135، تحت «بلاغة الاستعارة بالتعبير بالعضد»","url":""}]},{"id":"s18-109","number":109,"surah":18,"verses":[52],"references":[{"surah":18,"verses":[52]}],"verseLabel":"الكهف: 52","question":"ما دلالة الأمر في قوله للمشركين ﴿نَادُوا شُرَكَائِيَ﴾؟","answer":"أمر تعجيز وتوبيخ؛ ليظهر عمليًا أن من عبدوهم لا يستجيبون لهم ولا ينصرونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص138، تحت «دلالة التعبير بفعل الأمر نادوا»","url":""}]},{"id":"s18-230","number":230,"surah":18,"verses":[52],"references":[{"surah":18,"verses":[52]}],"verseLabel":"الكهف: 52","question":"ما سرّ إضافة الشركاء إلى ضمير الجلالة في قوله ﴿شُرَكَائِيَ﴾؟","answer":"الإضافة تهكم بدعواهم؛ فليس لله شريك، وإنما هم شركاء زعموهم من عند أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص139، تحت «سر إضافة الشركاء إلى ضمير الجلالة»","url":""}]},{"id":"s18-110","number":110,"surah":18,"verses":[52],"references":[{"surah":18,"verses":[52]}],"verseLabel":"الكهف: 52","question":"ما دلالة التعبير بصيغة موبقًا في قوله تعالى: ﴿وَجَعَلْنَا بَيْنَهُمْ مَوْبِقًا﴾؟","answer":"الموبق موضع الهلاك، ومن توجيهاته جهنم التي تفصل بينهم وبين من دعوهم. فبدل أن تنفعهم الصلة المزعومة بالشركاء، يواجهون الهلاك وتنقطع الاستجابة التي رجَوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص142، تحت «دلالة التعبير بصيغة موبقًا»","url":""}]},{"id":"s18-111","number":111,"surah":18,"verses":[53],"references":[{"surah":18,"verses":[53]}],"verseLabel":"الكهف: 53","question":"لماذا قال عن المجرمين عند رؤية النار: ﴿فظنوا أنهم مواقعوها﴾؟","answer":"عبّر بالظن لأنهم لم يباشروا دخولها بعد، مع أن أمارات الوقوع جعلت توقعهم قريبًا من اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص146، تحت «سر إيثار لفظ الظن دون العلم أو اليقين»","url":""}]},{"id":"s18-231","number":231,"surah":18,"verses":[53],"references":[{"surah":18,"verses":[53]}],"verseLabel":"الكهف: 53","question":"ما دلالة وصف المجرمين بأنهم ﴿مواقعوها﴾؟","answer":"يصوّر اللفظ تلاقيهم بالنار ووقوع بعضهم على بعض فيها، فيوحي بالمباشرة التي لا مهرب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص146، تحت «إيثار لفظ المواقعة»","url":""}]},{"id":"s18-112","number":112,"surah":18,"verses":[53],"references":[{"surah":18,"verses":[53]}],"verseLabel":"الكهف: 53","question":"ما سرّ التعبير بـ﴿وَلَمْ يَجِدُوا عَنْهَا مَصْرِفًا﴾؟","answer":"«مصرفًا» اسم مكان في هذا التوجيه؛ أي لم يجدوا موضعًا ينصرفون إليه عن النار. ونفي وجدانه يصور انقطاع طريق النجاة وعجزهم عن الهرب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص147، تحت «سر التعبير بالمفعول به بصيغة مفعل»","url":""}]},{"id":"s18-113","number":113,"surah":18,"verses":[54],"references":[{"surah":18,"verses":[54]}],"verseLabel":"الكهف: 54","question":"ما دلالة وصف الإنسان بأنه ﴿أَكْثَرَ شَيْءٍ جَدَلًا﴾؟","answer":"بالغ في رسوخ الجدل فيه؛ فهو يحول تنوع الأمثال إلى خصومة بدل الهداية إن فسد قصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص165، تحت «دلالة الجدل في الآية الكريمة»","url":""}]},{"id":"s18-114","number":114,"surah":18,"verses":[55],"references":[{"surah":18,"verses":[55]}],"verseLabel":"الكهف: 55","question":"ما سرّ التعبير بـ﴿وَمَا مَنَعَ النَّاسَ أَنْ يُؤْمِنُوا﴾؟","answer":"«ما» هنا نافية، وليست استفهامية. والنفي مع الاستثناء يصور عنادهم بعد قيام الهدى؛ فكأنهم لا ينتظرون إلا حلول عذاب الأولين أو مواجهة العذاب، وفي هذا تعجيب من حالهم وتهديد لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص170، تحت «إيثار لفظ منع دون غيره من مرادفاته»","url":""}]},{"id":"s18-115","number":115,"surah":18,"verses":[55],"references":[{"surah":18,"verses":[55]}],"verseLabel":"الكهف: 55","question":"ما سرّ التعبير بـ﴿إِلَّا أَنْ تَأْتِيَهُمْ سُنَّةُ الْأَوَّلِينَ﴾؟","answer":"جعل إصرارهم كأنهم لا ينتظرون إلا نموذج الهلاك القديم أو العذاب عيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص182، تحت «بلاغة الكناية في سنة الأولين»","url":""}]},{"id":"s18-116","number":116,"surah":18,"verses":[56],"references":[{"surah":18,"verses":[56]}],"verseLabel":"الكهف: 56","question":"ما مناسبة قصر وظيفة المرسلين على التبشير والإنذار قبل ذكر جدال الكافرين بالباطل في سورة الكهف؟","answer":"جاء القصر ليحدد وظيفة الرسل في البلاغ الجامع بين الرجاء والخوف، ثم يكشف أن مجادلة الكافرين بالباطل خروج عن مقتضى الرسالة وطلب متعنت لما ليس من وظيفة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص191، تحت «براعة القصر في سياق الآية الكريمة»","url":""}]},{"id":"s18-117","number":117,"surah":18,"verses":[56],"references":[{"surah":18,"verses":[56]}],"verseLabel":"الكهف: 56","question":"ما سرّ التعبير بـ﴿وَيُجَادِلُ الَّذِينَ كَفَرُوا بِالْبَاطِلِ﴾؟","answer":"المضارع يصور خصومة تتجدد كلما جاءهم بيان، والباطل آلة لمحاولة إسقاط الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص198، تحت «فائدة التقييد بقوله بالباطل»","url":""}]},{"id":"s18-118","number":118,"surah":18,"verses":[56],"references":[{"surah":18,"verses":[56]}],"verseLabel":"الكهف: 56","question":"ما سرّ التعبير بـ﴿لِيُدْحِضُوا بِهِ الْحَقَّ﴾؟","answer":"الإدحاض إزلاق القدم؛ استعارة لمحاولة إزالة ثبات الحق بحجة زائفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص199، تحت «بلاغة الاستعارة في قوله ليدحضوا»","url":""}]},{"id":"s18-119","number":119,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿ذُكِّرَ بِآيَاتِ رَبِّهِ﴾ بالبناء للمجهول؟","answer":"لأن المعتبر وصول التذكير إليه أيًا كان مبلغه، فلا عذر بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص214، تحت «سبب مجيء ذكر مبنيًّا للمفعول»","url":""}]},{"id":"s18-120","number":120,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿بِآيَاتِ رَبِّهِ﴾ لا «بالقرآن»؟","answer":"المراد في هذا التوجيه القرآن، وتسميته «آيات» تستحضر وضوح دلائله وتعددها، فيكون الإعراض عنها أشد قبحًا. وإضافتها إلى الرب تذكّر بإحسانه وتزيد التعجيب ممن يعرض عما بلغه من ربه المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص214، تحت «دلالة التعبير بآيات ربه دون بالقرآن»","url":""}]},{"id":"s18-121","number":121,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما دلالة قوله عن المعرض: ﴿ونسي﴾؟","answer":"كُنّي بالنسيان عن الإهمال والإعراض، ثم صُوّر تركه لذنوبه كأنها شيء غاب عن ذاكرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص218، تحت «بلاغة النسيان هنا في الكناية ثم الاستعارة»","url":""}]},{"id":"s18-232","number":232,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"لماذا نُسب ما عمله الإنسان إلى يديه في قوله: ﴿ما قدمت يداه﴾؟","answer":"نُسب العمل إلى اليدين لأن أكثر الأفعال تباشر بهما، فدل الجزء على عمل الإنسان كله ومسؤوليته عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص218، تحت «بلاغة المجاز المرسل في قدمت يداه»","url":""}]},{"id":"s18-123","number":123,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿وَإِنْ تَدْعُهُمْ إِلَى الْهُدَى فَلَنْ يَهْتَدُوا﴾؟","answer":"يصور الشرط دعوة من استحكم إعراضهم، ويؤكد نفي الاهتداء حالَ طبع قلوبهم وتوليهم. وفيه تسلية للنبي عن هؤلاء المعاندين، مع بقاء الدعوة إلى الهدى؛ فلا يحمل على منع دعوة الناس أو نفي إمكان هداية كل عاصٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص228، تحت «نكتة مجيء الجزاء بصيغة فلن يهتدوا»","url":""}]},{"id":"s18-124","number":124,"surah":18,"verses":[58],"references":[{"surah":18,"verses":[58]}],"verseLabel":"الكهف: 58","question":"ما سرّ التعبير بـ﴿وَرَبُّكَ الْغَفُورُ ذُو الرَّحْمَةِ﴾ لا «الرحيم»؟","answer":"يمهد وصفه بأنه «ذو الرحمة» لبيان إمهالهم وترك تعجيل العذاب. ومن توجيهات العدول عن صيغة المبالغة أن المقام يذكر الرحمة بهذا الإمهال خاصة، بينما أبرز «الغفور» سعة المغفرة لمن آمن وتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص235، تحت «سر العدول عن الرحيم إلى ذو الرحمة»","url":""}]},{"id":"s18-125","number":125,"surah":18,"verses":[58],"references":[{"surah":18,"verses":[58]}],"verseLabel":"الكهف: 58","question":"ما سرّ التعبير بـ﴿بِمَا كَسَبُوا﴾؟","answer":"الباء تربط المؤاخذة بما اقترفوه، و«ما» تشمل ما كسبوا من الذنوب. وفي تصوير المعاصي كسبًا تهكم بهم؛ فقد حسبوا أنهم يجلبون لأنفسهم نفعًا، فإذا عاقبة فعلهم شر وضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص238، تحت «بلاغة الاستعارة في قوله كسبوا»","url":""}]},{"id":"s18-126","number":126,"surah":18,"verses":[58],"references":[{"surah":18,"verses":[58]}],"verseLabel":"الكهف: 58","question":"ما سرّ تقديم ﴿لَهُمْ﴾ في ﴿بَلْ لَهُمْ مَوْعِدٌ﴾؟","answer":"لتخصيصهم وتهديدهم بأن موعدًا معينًا يترصدهم لا يفلتون منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص241، تحت «سر التقديم في قوله لهم موعد»","url":""}]},{"id":"s18-127","number":127,"surah":18,"verses":[59],"references":[{"surah":18,"verses":[59]}],"verseLabel":"الكهف: 59","question":"ما سرّ التعبير بـ﴿وَتِلْكَ الْقُرَى أَهْلَكْنَاهُمْ﴾ فجمع القرى وأعاد الضمير إلى أهلها؟","answer":"أشار إلى آثار قرى متعددة، ثم راعى سكانها في ضمير العقلاء لأنهم محل الظلم والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص251، تحت «نكتة عود الضمير مجموعًا في أهلكناهم»","url":""}]},{"id":"s18-128","number":128,"surah":18,"verses":[59],"references":[{"surah":18,"verses":[59]}],"verseLabel":"الكهف: 59","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا لِمَهْلِكِهِمْ مَوْعِدًا﴾؟","answer":"يبين أن لإهلاكهم وقتًا مقدرًا لا يتقدمون عليه ولا يتأخرون عنه؛ فالإمهال ليس إلغاءً للجزاء. وتقديم «لمهلكهم» يوجه الاهتمام إلى هذا المصير ويزيد التخويف منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص253، تحت «دلالة صيغة مهلك»","url":""}]},{"id":"s18-129","number":129,"surah":18,"verses":[60],"references":[{"surah":18,"verses":[60]}],"verseLabel":"الكهف: 60","question":"ما دلالة قول موسى: ﴿لَا أَبْرَحُ حَتَّى أَبْلُغَ﴾؟","answer":"عبّر عن استمرار السير بلا فتور حتى الغاية، فصار طلب العلم عزمًا مفتوح المدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص262، تحت «دلالة النفي بلا في السياق الحكيم»","url":""}]},{"id":"s18-130","number":130,"surah":18,"verses":[60],"references":[{"surah":18,"verses":[60]}],"verseLabel":"الكهف: 60","question":"ما سرّ التعبير بـ﴿مَجْمَعَ الْبَحْرَيْنِ﴾ لا «ملتقى البحرين»؟","answer":"يفيد «المجمع» الاجتماع وما يصاحبه من كثرة وتجانس، بينما أصل اللقاء مقابلة الشيء، وقد يقع مصادفة. فالتعبير يحدد الموضع المقصود ويصور اجتماع البحرين، ويهيئ في السياق للقاء موسى بمن يطلب علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص263، تحت «سبب إيثار لفظ مجمع دون ملتقى»","url":""}]},{"id":"s18-131","number":131,"surah":18,"verses":[60],"references":[{"surah":18,"verses":[60]}],"verseLabel":"الكهف: 60","question":"ما سرّ التعبير بـ﴿أَوْ أَمْضِيَ حُقُبًا﴾؟","answer":"يبالغ في طول الاستعداد للسفر؛ فالحقب زمن طويل، والعلم يستحق الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص265، تحت «بلاغة الكناية في أو أمضي حقبًا»","url":""}]},{"id":"s18-132","number":132,"surah":18,"verses":[61],"references":[{"surah":18,"verses":[61]}],"verseLabel":"الكهف: 61","question":"ما سرّ التعبير بـ﴿فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا﴾؟","answer":"تربط «لما» بلوغهما مجمع البحرين بما وقع عنده من نسيان الحوت، بعد سيرهما نحو الموعد. وإظهار ﴿مَجْمَعَ بَيْنِهِمَا﴾ يعيد إبراز أهمية المكان الذي قصداه للقاء العبد الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص270، تحت «بلاغة مجيء الكلام على خلاف الظاهر في الآية»","url":""}]},{"id":"s18-133","number":133,"surah":18,"verses":[61],"references":[{"surah":18,"verses":[61]}],"verseLabel":"الكهف: 61","question":"ما دلالة وصف مسلك الحوت بقوله: ﴿فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ سَرَبًا﴾؟","answer":"شُبّه الطريق الذي اتخذه الحوت في الماء بالسرب، وهو النفق، فصار مسلكه ظاهرًا على هيئة عجيبة. وهذا المشهد الخارق للعادة كان علامة لموسى على موضع اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص274، تحت «بلاغة التشبيه في قوله سربًا»","url":""}]},{"id":"s18-134","number":134,"surah":18,"verses":[62],"references":[{"surah":18,"verses":[62]}],"verseLabel":"الكهف: 62","question":"ما دلالة ظهور النصب في رحلة موسى بعد مجاوزة موضع اللقاء؟","answer":"صرف الله عنه التعب حتى تجاوز المكان، ثم جعله سببًا للرجوع إلى العلامة التي نسيها فتاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص284، تحت «دلالة جملة التعبير عن النصب وما فيها من بيان عجب»","url":""}]},{"id":"s18-135","number":135,"surah":18,"verses":[62],"references":[{"surah":18,"verses":[62]}],"verseLabel":"الكهف: 62","question":"ما سرّ التعبير بـ﴿آتِنَا غَدَاءَنَا﴾ بالإيتاء لا الإعطاء؟","answer":"الإيتاء هنا أنسب بطلب إحضار الغداء ومناولته، لا بإنشاء ملك له؛ فهو طعامهما أصلًا. ويذكر المصدر أن الإيتاء أقوى في معنى الإحضار، وأن الأمر به مناسب لمقام موسى مع فتاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص282، تحت «سر التعبير بلفظ آتنا عوضًا عن لفظ أعطنا»","url":""}]},{"id":"s18-136","number":136,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما دلالة افتتاح الفتى كلامه بـ﴿أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ﴾؟","answer":"يستدعي الفتى انتباه موسى إلى ما حدث عند الصخرة، وفي الاستفهام تعجيب من النسيان مع عظم الأمر المشاهد. ويحتمل معنى «أخبرني» أو «انتبه» تمهيدًا لذكر خبر الحوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص287، تحت «دلالة الاستفهام في قوله تعالى أرأيت»","url":""}]},{"id":"s18-137","number":137,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما سر إضافة الإيواء إلى الصخرة في كلام الفتى؟","answer":"الصخرة معروفة لهما، وإضافة الإيواء إليها تعيّن موضع الحادثة بدقة وتستحضر وقت الاستراحة. وفي ذلك تأكيد لاعتذار الفتى؛ فهذا هو المكان الذي وقع فيه الأمر العجيب ثم نسي إخبار موسى به.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص290، تحت «علة إضافة الإيواء إلى الصخرة دون مجمع البحرين»","url":""}]},{"id":"s18-138","number":138,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما دلالة إسناد النسيان إلى الحوت في قول الفتى: ﴿فَإِنِّي نَسِيتُ الْحُوتَ﴾؟","answer":"من توجيهات العبارة أنه نسي ذكر خبر الحوت لموسى، فحُذف المضاف وأقيم الحوت مقامه. ويذكر المصدر أيضًا نسيان حفظه وتفقده؛ فلا يلزم حصر النسيان في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص291، تحت «دلالة النسيان في قوله فإني نسيت»","url":""}]},{"id":"s18-139","number":139,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما سرّ التعبير بـ﴿وَمَا أَنْسَانِيهُ إِلَّا الشَّيْطَانُ﴾؟","answer":"قصر سبب النسيان العارض على وسوسة الشيطان، مع بقاء الحدث داخل تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص293، تحت «سر نسبة فعل النسيان إلى الشيطان لا إلى الإنسان»","url":""}]},{"id":"s18-140","number":140,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"لماذا عطف ﴿وَاتَّخَذَ سَبِيلَهُ﴾ بالواو، وفي الآية 61 بالفاء؟","answer":"الفاء في الآية 61 تصل اتخاذ الحوت سبيله بما سبق في سرد الحدث وتفيد التعقيب. أما الواو في كلام الفتى فتعرض حال الحوت التي نسي ذكرها؛ فالسياق يستحضر ما وقع عجبًا، ولا يرتب ذهابه على نسيان إخباره موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص295، تحت «علة التعبير بالواو العاطفة في جملة واتخذ»","url":""}]},{"id":"s18-141","number":141,"surah":18,"verses":[64],"references":[{"surah":18,"verses":[64]}],"verseLabel":"الكهف: 64","question":"ما دلالة قول موسى: ﴿ذَلِكَ مَا كُنَّا نَبْغِ﴾؟","answer":"أدرك أن فقد الحوت هو العلامة المطلوبة؛ فاسم الإشارة يحسم أن هذا عين المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص302، تحت «سر الإشارة بما يدل على البعد بلفظ ذلك»","url":""}]},{"id":"s18-142","number":142,"surah":18,"verses":[64],"references":[{"surah":18,"verses":[64]}],"verseLabel":"الكهف: 64","question":"ما سرّ التعبير بـ﴿فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا﴾ لا «فرجعا»؟","answer":"الارتداد رجوع على الطريق نفسه، و«قصصًا» يصور تتبع الأثر بدقة حتى لا يضيعا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص306، تحت «سر التعبير بلفظ قصصًا في ثنايا السياق»","url":""}]},{"id":"s18-143","number":143,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سر تقديم الخضر بوصفه ﴿عَبْدًا﴾؟","answer":"العبودية لله أرفع أوصاف التكريم؛ فافتتاح التعريف بالخضر بها يرفع قدره ويهيئ لبيان ما خصه الله به من الرحمة والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص313، تحت «سر التعبير بلفظ ﴿عَبْدًا﴾ دون مرادفاته»","url":""}]},{"id":"s18-233","number":233,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما دلالة تنكير لفظ ﴿عَبْدًا﴾ في التعريف بالخضر؟","answer":"جاء التنكير للتفخيم والتعظيم، فيدل على عبد رفيع المنزلة اصطفاه الله، وإن لم يُذكر اسمه في الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص313، تحت «سر التنكير في لفظ ﴿عَبْدًا﴾ في السياق»","url":""}]},{"id":"s18-234","number":234,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سر إضافة العبد إلى ضمير العظمة في قوله: ﴿عَبْدًا مِنْ عِبَادِنَا﴾؟","answer":"الإضافة إلى الله إضافة تشريف وتكريم، وتدل على خصوصية هذا العبد بالقرب والاصطفاء، مع بقائه واحدًا من عباد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص314، تحت «سر الإضافة في المركب الإضافي ﴿عِبَادِنَا﴾»","url":""}]},{"id":"s18-144","number":144,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سر قوله: ﴿رحمة من عندنا﴾ و﴿من لدنا علمًا﴾؟","answer":"خص العلم بـ﴿لدنا﴾ للدلالة على مزيد اختصاصه بالله ومباشرة تعليمه، وجاءت الرحمة بـ﴿عندنا﴾ الدالة على الفضل الممنوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص318، تحت «سر عند مع الرحمة ولدن مع العلم في الآية»","url":""}]},{"id":"s18-235","number":235,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما دلالة تنكير ﴿علمًا﴾ في وصف الخضر؟","answer":"يفيد تفخيم علم خاص وهبه الله له، متعلق بحِكَم خفية لم يطلع عليها موسى في بداية الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص319، تحت «المراد بالعلم وغرض تنكيره»","url":""}]},{"id":"s18-236","number":236,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"لماذا قُدمت الرحمة على العلم في وصف الخضر؟","answer":"لأن الرحمة أصل في حسن استعمال العلم؛ فالعلم الذي لا تحكمه الرحمة قد يتحول إلى أذى أو غرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص320، تحت «سر تقديم الرحمة على العلم»","url":""}]},{"id":"s18-145","number":145,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سرّ تقديم ﴿مِنْ لَدُنَّا﴾ على ﴿عِلْمًا﴾؟","answer":"لقصر مصدر هذا العلم الخاص على تعليم الله، لا على كسب معتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص318، 319، تحت «سر تقديم الجار والمجرور من لدنا على المفعول به علمًا»","url":""}]},{"id":"s18-146","number":146,"surah":18,"verses":[66],"references":[{"surah":18,"verses":[66]}],"verseLabel":"الكهف: 66","question":"ما دلالة استئذان موسى بقوله: ﴿هَلْ أَتَّبِعُكَ﴾ وهو نبي؟","answer":"تواضع المتعلم لمن عنده علم لا يعلمه، واستأذن في الصحبة بدل أن يطالب بالتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص325، تحت «نكتة تقديم إثبات الاتباع على طلب التعليم»","url":""}]},{"id":"s18-147","number":147,"surah":18,"verses":[66],"references":[{"surah":18,"verses":[66]}],"verseLabel":"الكهف: 66","question":"ما سرّ التعبير بـ﴿مِمَّا عُلِّمْتَ رُشْدًا﴾ لا «علمًا»؟","answer":"طلب من العلم ما يقود إلى الصواب والعمل، لا معلومات مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص328، تحت «سر التعبير والتنكير للفظ رشدًا»","url":""}]},{"id":"s18-148","number":148,"surah":18,"verses":[67],"references":[{"surah":18,"verses":[67]}],"verseLabel":"الكهف: 67","question":"ما دلالة قول الخضر لموسى: ﴿لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا﴾؟","answer":"لم يطعن في موسى، بل أخبر أن ظاهر الأفعال سيصادم علم الشريعة الذي يحمله قبل كشف بواطنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص337، تحت «المراد بالصبر وسر التعبير به»","url":""}]},{"id":"s18-149","number":149,"surah":18,"verses":[68],"references":[{"surah":18,"verses":[68]}],"verseLabel":"الكهف: 68","question":"ما سرّ التعبير بـ﴿وَكَيْفَ تَصْبِرُ عَلَى مَا لَمْ تُحِطْ بِهِ خُبْرًا﴾؟","answer":"الاستفهام للتعجيب أو الإنكار، وفيه بيان سبب تعذر صبر موسى على أفعال تبدو منكرة قبل أن يعلم حكمتها. و«تحط» تصور العلم المستوعب لبواطنها وعواقبها، وهي أمور لم يُطلع عليها بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص340، تحت «بلاغة استعمال لفظ الإحاطة»","url":""}]},{"id":"s18-150","number":150,"surah":18,"verses":[68],"references":[{"surah":18,"verses":[68]}],"verseLabel":"الكهف: 68","question":"ما سرّ التعبير بـ﴿خُبْرًا﴾ لا «علمًا»؟","answer":"الخبر معرفة باطن الشيء وتجربته، وهو المطلوب لفهم الأفعال الغريبة لا مجرد علم إجمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص342، تحت «معنى لفظ خبرًا وسر تنكيره»","url":""}]},{"id":"s18-151","number":151,"surah":18,"verses":[69],"references":[{"surah":18,"verses":[69]}],"verseLabel":"الكهف: 69","question":"ما دلالة قول موسى: ﴿سَتَجِدُنِي إِنْ شَاءَ اللَّهُ صَابِرًا﴾؟","answer":"ربط وعده بالمشيئة تأدبًا، واختار اسم الفاعل ليدل على ثبات الصبر المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص349، تحت «دلالة الاستثناء في قوله إن شاء الله»","url":""}]},{"id":"s18-152","number":152,"surah":18,"verses":[69],"references":[{"surah":18,"verses":[69]}],"verseLabel":"الكهف: 69","question":"ما سرّ التعبير بـ﴿وَلَا أَعْصِي لَكَ أَمْرًا﴾ ولم يقل «لن أعصي»؟","answer":"من توجيهات اختيار «لا» أنها لا تحمل تأكيد النفي الذي تفيده «لن» في هذا السياق، فيناسب ذلك وعد موسى المعلق بمشيئة الله. ومع تنكير «أمرًا» يعلن استعداده لاتباع أوامر الخضر في هذه الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص352، تحت «سر النفي بلا دون لن»","url":""}]},{"id":"s18-153","number":153,"surah":18,"verses":[70],"references":[{"surah":18,"verses":[70]}],"verseLabel":"الكهف: 70","question":"ما دلالة تقييد النهي عن السؤال بـ﴿حَتَّى أُحْدِثَ لَكَ مِنْهُ ذِكْرًا﴾؟","answer":"اشترط تأخير السؤال والاعتراض حتى يبدأ هو ببيان وجه ما يفعله وحكمته. و«حتى» تجعل للسكوت غاية؛ فالمراد الصبر إلى وقت البيان في هذه الرحلة، مع وعده بأن يكشف لموسى ما خفي عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص359، تحت «غرض النهي في قوله فلا تسألني»","url":""}]},{"id":"s18-154","number":154,"surah":18,"verses":[71],"references":[{"surah":18,"verses":[71]}],"verseLabel":"الكهف: 71","question":"ما سرّ التعبير بـ﴿خَرَقَهَا﴾ فور ركوب السفينة؟","answer":"بادر الخضر إلى الخرق عند الركوب؛ وتقديم ظرف الركوب يدل على أن الخرق وقع بمجرده، وأن الفعل كان مقصودًا مدبرًا من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص369، تحت «حقيقة الخرق وسر التعبير بالفعل خرقها»","url":""}]},{"id":"s18-155","number":155,"surah":18,"verses":[71],"references":[{"surah":18,"verses":[71]}],"verseLabel":"الكهف: 71","question":"ما دلالة إنكار موسى بقوله: ﴿لَقَدْ جِئْتَ شَيْئًا إِمْرًا﴾؟","answer":"الإِمر هو الأمر العظيم المنكر؛ فأكد موسى إنكاره لما ظهر له من كون الخرق ذريعة إلى إغراق أهل السفينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص374، تحت «معنى إمرًا وسر التعبير بها»","url":""}]},{"id":"s18-156","number":156,"surah":18,"verses":[72],"references":[{"surah":18,"verses":[72]}],"verseLabel":"الكهف: 72","question":"ما دلالة تذكير الخضر موسى بقوله: ﴿أَلَمْ أَقُلْ إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا﴾؟","answer":"ليعيده إلى الشرط الذي قبله وهو يرى تحقق الخبر عمليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص379، تحت «دلالة الاستفهام في قوله ألم أقل»","url":""}]},{"id":"s18-157","number":157,"surah":18,"verses":[73],"references":[{"surah":18,"verses":[73]}],"verseLabel":"الكهف: 73","question":"ما دلالة اعتذار موسى بقوله: ﴿لَا تُؤَاخِذْنِي بِمَا نَسِيتُ﴾؟","answer":"اعتذر موسى بأن اعتراضه الأول صدر عن نسيان شرط الصحبة، وسأل الصفح عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص385، تحت «نكتة إيثار التعبير بالمؤاخذة»","url":""}]},{"id":"s18-158","number":158,"surah":18,"verses":[73],"references":[{"surah":18,"verses":[73]}],"verseLabel":"الكهف: 73","question":"ما سرّ التعبير بـ﴿وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا﴾؟","answer":"طلب ألا يعامله الخضر بالشدة بسبب نسيانه، وأن يغضي ويصفح ليستمر أمر الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص387، تحت «بلاغة استعمال الفعل ترهقني مادة وصيغة»","url":""}]},{"id":"s18-159","number":159,"surah":18,"verses":[74],"references":[{"surah":18,"verses":[74]}],"verseLabel":"الكهف: 74","question":"ما دلالة شدة المبادرة والإنكار في مشهد قتل الغلام مقارنة بخرق السفينة؟","answer":"زادت الفاء في «فقتله» تصوير المبادرة بالقتل عقب اللقاء، على نحو أشد من مشهد خرق السفينة. واشتد إنكار موسى لأن قتل النفس وقع بالفعل، بينما خرق السفينة بدا له وسيلة إلى إغراق قد يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص404، تحت «سر التعبير بقوله نكرًا»","url":""}]},{"id":"s18-160","number":160,"surah":18,"verses":[74],"references":[{"surah":18,"verses":[74]}],"verseLabel":"الكهف: 74","question":"ما دلالة قول موسى: ﴿نَفْسًا زَكِيَّةً بِغَيْرِ نَفْسٍ﴾؟","answer":"وصفها بالزكية يبرز ما ظهر لموسى من طهارتها وعدم استحقاقها القتل، و«بغير نفس» ينفي القصاص فيزيد الإنكار. ويذكر المصدر خلافًا في بلوغ الغلام؛ فلا يُجزم بصغر سنه على أنه التفسير الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص402، تحت «فائدة ذكر القيد بغير نفس»","url":""}]},{"id":"s18-161","number":161,"surah":18,"verses":[74],"references":[{"surah":18,"verses":[74]}],"verseLabel":"الكهف: 74","question":"ما سر وصف قتل الغلام بأنه ﴿شَيْئًا نُكْرًا﴾ ووصف خرق السفينة بأنه ﴿إِمْرًا﴾؟","answer":"النُّكر أشد من الإمر؛ لأن قتل الغلام فساد حاصل، أما خرق السفينة فكان في الظاهر ذريعة إلى فساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص376، تحت «الإمر والنكر والصعب»","url":""}]},{"id":"s18-162","number":162,"surah":18,"verses":[75],"references":[{"surah":18,"verses":[75]}],"verseLabel":"الكهف: 75","question":"ما دلالة زيادة ﴿لَكَ﴾ في التذكير الثاني: ﴿أَلَمْ أَقُلْ لَكَ﴾؟","answer":"زيادة ﴿لك﴾ تحقق وقوع القول وتثبته وتقويه؛ لأن موسى أهمل العمل بالتنبيه السابق، فصار التقرير والإنكار أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص410، تحت «دلالة اللام وسر زيادة شبه الجملة لك»","url":""}]},{"id":"s18-163","number":163,"surah":18,"verses":[76],"references":[{"surah":18,"verses":[76]}],"verseLabel":"الكهف: 76","question":"ما دلالة جعل موسى السؤال التالي سببًا لإنهاء الصحبة؟","answer":"أنصف موسى صاحبه، فجعل له العذر في قطع الصحبة إن عاد إلى السؤال ثالثة، تجنبًا لإحراجه بعد تكرر الاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص415، تحت «بلاغة التعبير بالفعل بلغت»","url":""}]},{"id":"s18-164","number":164,"surah":18,"verses":[77],"references":[{"surah":18,"verses":[77]}],"verseLabel":"الكهف: 77","question":"ما دلالة ﴿اسْتَطْعَمَا أَهْلَهَا﴾ وما تبعها من رفض الضيافة؟","answer":"السين والتاء للطلب، أي طلبا الطعام من أهل القرية لما أصابهما من الجوع. ثم أبرز رفضهم الضيافة شدة لؤمهم، وإعادة «أهلها» تعيّن الجماعة التي وُجه إليها الطلب فامتنعت.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص426، تحت «دلالة السين في الفعل استطعما»","url":""}]},{"id":"s18-165","number":165,"surah":18,"verses":[77],"references":[{"surah":18,"verses":[77]}],"verseLabel":"الكهف: 77","question":"ما سرّ التعبير بـ﴿جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ﴾؟","answer":"استعيرت الإرادة لقرب سقوط الجدار: فقد مال وأشرف على الانقضاض، فشُبّه قرب وقوعه بإرادة العاقل للفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص430، تحت «بلاغة السياق بين الاستعارة والمجاز العقلي»","url":""}]},{"id":"s18-166","number":166,"surah":18,"verses":[77],"references":[{"surah":18,"verses":[77]}],"verseLabel":"الكهف: 77","question":"ما دلالة إقامة الجدار بلا أجر في قرية امتنعت عن الضيافة؟","answer":"كانت إقامة الجدار لحفظ كنز اليتيمين حتى يبلغا ويقدرا على استخراجه وصيانته، رحمة بهما وإكرامًا لأبيهما الصالح. فسبب العمل يتجاوز ما ظهر من لؤم أهل القرية وحاجتهما إلى الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص466، تحت «سر الوصف باليتم هنا»","url":""}]},{"id":"s18-167","number":167,"surah":18,"verses":[78],"references":[{"surah":18,"verses":[78]}],"verseLabel":"الكهف: 78","question":"ما سرّ التعبير بـ﴿هَذَا فِرَاقُ بَيْنِي وَبَيْنِكَ﴾؟","answer":"يشير ﴿هذا﴾ إلى ما حصل الآن من تحقق الشرط الذي ألزمه موسى نفسه؛ فصار الاعتراض الثالث هو لحظة انقطاع الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص435، تحت «دلالة الفراق في هذا السياق»","url":""}]},{"id":"s18-168","number":168,"surah":18,"verses":[78],"references":[{"surah":18,"verses":[78]}],"verseLabel":"الكهف: 78","question":"ما سرّ التعبير بـ﴿سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِعْ عَلَيْهِ صَبْرًا﴾؟","answer":"أوفى الخضر بوعده السابق، فأنبأ موسى عند الفراق بأسباب الأفعال التي أنكرها وبعواقبها الخفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص438، تحت «بلاغة استعمال لفظ تأويل»","url":""}]},{"id":"s18-169","number":169,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا نسب الخضر عيب السفينة إلى نفسه: ﴿فَأَرَدْتُ أَنْ أَعِيبَهَا﴾؟","answer":"نسب العيب إلى نفسه مراعاةً لحسن الأدب مع الله، مع إقراره أن الفعل كان بأمره. والتعبير بـ«أردت» يوضح أنه خرق مقصود لحفظ السفينة، لا إفساد عبثي لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص448، تحت «سر إسناد العبد الصالح العيب إلى نفسه»","url":""}]},{"id":"s18-170","number":170,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا وصف أصحاب السفينة بأنهم ﴿مساكين﴾ مع امتلاكهم سفينة؟","answer":"لأن ملكهم للسفينة لم يرفع حاجتهم؛ كانت أداة كسبهم الوحيدة ومعاشهم معرضًا للسلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص445، تحت «سر الوصف بقوله لمساكين»","url":""}]},{"id":"s18-237","number":237,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا ذُكر عيب السفينة قبل ذكر الملك الذي يغتصب السفن؟","answer":"قُدّم الفعل المستنكر أولًا ليبقى السامع متشوقًا إلى حكمته، ثم كشف السبب فتحول ظاهر الضرر إلى رحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص447، تحت «سر تقديم المسبب على السبب»","url":""}]},{"id":"s18-238","number":238,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا حُذفت صفة السفينة في قوله: ﴿يأخذ كل سفينة غصبًا﴾؟","answer":"دل السياق على أن المراد كل سفينة صالحة؛ لأن السفينة المعيبة لا يطمع الملك في اغتصابها، فحذفت الصفة اعتمادًا على القرينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص450، تحت «دلالة حذف صفة لفظ سفينة»","url":""}]},{"id":"s18-171","number":171,"surah":18,"verses":[80],"references":[{"surah":18,"verses":[80]}],"verseLabel":"الكهف: 80","question":"ما دلالة قول الخضر عن الغلام: ﴿فَخَشِينَا أَنْ يُرْهِقَهُمَا﴾؟","answer":"من توجيهات الكلام أن الخضر يتحدث عما علمه بإعلام الله من حال الغلام لو بقي، وأن ضمير الجمع يشير إلى أن فعله لم يستقل به عن الأمر الإلهي. ويذكر المصدر للضمير والخشية توجيهات أخرى؛ والمقصود كشف ما خفي من عاقبة الغلام على أبويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص454، تحت «التعبير بالفعل المضارع يرهقهما»","url":""}]},{"id":"s18-172","number":172,"surah":18,"verses":[80],"references":[{"surah":18,"verses":[80]}],"verseLabel":"الكهف: 80","question":"لماذا جمع بين ﴿طُغْيَانًا وَكُفْرًا﴾؟","answer":"يجمع التعبير مجاوزة الحد والكفر، فيعظم الخطر على الأبوين المؤمنين. ومن توجيهاته أنه يرهقهما بطغيانه وكفره، أو يحملهما حبهما له على موافقته؛ وليس المقصود أذى دنيويًّا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص454، تحت «سر عطف قوله كفرًا على طغيانًا»","url":""}]},{"id":"s18-173","number":173,"surah":18,"verses":[81],"references":[{"surah":18,"verses":[81]}],"verseLabel":"الكهف: 81","question":"ما سرّ التعبير بـ﴿فَأَرَدْنَا أَنْ يُبْدِلَهُمَا رَبُّهُمَا﴾ بضمير الجمع؟","answer":"من توجيهات ضمير الجمع أنه للمتكلم مع إظهار المشاركة والتواضع، لأن الخضر يبين ما أطلعه الله عليه وأمره به. ويذكر المصدر توجيهات أخرى للمغايرة بين الإفراد والجمع، ثم يسند التبديل إلى الرب لأنه وحده الذي يهب العوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص455، تحت «سر التعبير بالجمع في فأردنا دون أردت»","url":""}]},{"id":"s18-174","number":174,"surah":18,"verses":[81],"references":[{"surah":18,"verses":[81]}],"verseLabel":"الكهف: 81","question":"ما دلالة وصف البديل بأنه ﴿خيرًا منه زكاة﴾؟","answer":"أي أطهر نفسًا وأصلح دينًا وخلقًا، فلا يرهق أبويه بطغيان أو كفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص457، تحت «سر الوصف بالزكاة في قوله خيرًا منه زكاة»","url":""}]},{"id":"s18-239","number":239,"surah":18,"verses":[81],"references":[{"surah":18,"verses":[81]}],"verseLabel":"الكهف: 81","question":"ما دلالة وصف البديل بأنه ﴿أقرب رحمًا﴾؟","answer":"يبشر بولد أبر بوالديه وأشد رحمة وصلة بهما، فيجمع صلاح نفسه وحسن أثره في أسرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص458، تحت «سر عطف قوله وأقرب رحمًا على سابقه»","url":""}]},{"id":"s18-175","number":175,"surah":18,"verses":[82],"references":[{"surah":18,"verses":[82]}],"verseLabel":"الكهف: 82","question":"ما سرّ التعبير في قصة الجدار بـ﴿فَأَرَادَ رَبُّكَ﴾؟","answer":"أُسندت الإرادة إلى الله لأن حفظ الكنز كرامة محضة لأبي الغلامين بسبب صلاحه، بخلاف القصتين السابقتين ففيهما دفع فساد يدركه من وقف على سره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص469، تحت «نكتة نسبة الإرادة إلى الرب هنا دون ما سبق»","url":""}]},{"id":"s18-176","number":176,"surah":18,"verses":[82],"references":[{"surah":18,"verses":[82]}],"verseLabel":"الكهف: 82","question":"ما دلالة ذكر صلاح الأب في بيان سبب حفظ كنز الغلامين؟","answer":"كان حفظ الكنز لطفًا بالغلامين وجزاءً لأبيهما على صلاحه واهتمامه بمعيشتهما بعده، لئلا ينكشف المال قبل بلوغهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص468، تحت «فائدة الوصف بالصلاح للأب»","url":""}]},{"id":"s18-177","number":177,"surah":18,"verses":[82],"references":[{"surah":18,"verses":[82]}],"verseLabel":"الكهف: 82","question":"ما دلالة ختام بيان الخضر بقوله: ﴿وَمَا فَعَلْتُهُ عَنْ أَمْرِي﴾؟","answer":"ليزيل إنكار موسى ويبين أن التصرفات رحمة ومصلحة، وأنها لم تصدر عن اجتهاد الخضر أو هوى نفسه بل عن وحي وأمر من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص473، تحت «فائدة التقييد بشبه الجملة عن أمري»","url":""}]},{"id":"s18-178","number":178,"surah":18,"verses":[83],"references":[{"surah":18,"verses":[83]}],"verseLabel":"الكهف: 83","question":"لماذا عُبّر بـ﴿سَأَتْلُو﴾ في خبر ذي القرنين دون سأخبر؟","answer":"التلاوة تفيد اتباع أجزاء الخبر بعضها بعضًا في ترتيب واتصال، وهو أنسب بعرض أحداث القصة متتابعة على السامعين من مجرد الإخبار المجمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص484، تحت «التعبير بالتلاوة في ﴿سَأَتْلُو﴾ دون الإخبار وغيره»","url":""}]},{"id":"s18-240","number":240,"surah":18,"verses":[83],"references":[{"surah":18,"verses":[83]}],"verseLabel":"الكهف: 83","question":"ما دلالة ﴿مِنْهُ﴾ في قوله: ﴿سَأَتْلُو عَلَيْكُمْ مِنْهُ ذِكْرًا﴾؟","answer":"تفيد (من) التبعيض؛ أي سيتلو عليهم بعض خبر ذي القرنين مما تتحقق به العبرة، لا جميع أخباره وأحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص484، تحت «معنى (مِنْ) في شبه الجملة ﴿مِنْهُ﴾»","url":""}]}]);
